        [SessionExpireFilterAttribute]
        public ActionResult ManageTeamMemberChecks(int page = 1, bool fetchDataCheckbox = false, string sort = "", string sortDir = "desc", string Search = "", short ClientRowID = 0, string CheckStatus = "", byte tatdays = 0, string RecievingToDate = "", string RecievingFromDate = "", string CompletedToDate = "", string CompletedFromDate = "", string DCheckStatus = "", string CaseStatus = "", string EmployerName = "", string Allocatedto = "", short State = 0, short City = 0, short Partner = 0, string version = "New", string CheckStatusId = "", string Aging = "", string VEmploymentId = "", string SearchType = "", string CompleteFunction = "", bool isMessageSend = false, string VerificationIds = "", short AllocatePTR = 0, short StateRowId = 0)
        {
            VerificationInfoListPagedModel model = new VerificationInfoListPagedModel();
            if (CompleteFunction == "Complete by Data entry QC")
            {
                DataTable dt = new DataTable();
                dt = cc.CompleteByDataEntryQC(CompletedFromDate, CompletedToDate);
                ExportToExcel(dt, "Data Entry QC Completion");
            }
            if (CompleteFunction == "DT To RWQC Instant Check MIS")
            {
                if (string.IsNullOrEmpty(CompletedToDate))
                {
                    CompletedToDate = DateTime.Now.ToString("yyyy-MM-dd");
                }
                DataTable dt = new DataTable();
                dt = cc.DTToRWQCInstantCheckMIS(CompletedFromDate, CompletedToDate);
                ExportToExcel(dt, "Instant Check MIS");
            }

            if (Aging == "True")
            {
                return RedirectToAction("Index", "Verification");
            }
            try
            {
                Session["CheckStatus"] = CheckStatus;
                Session["version"] = version;
                Session["Member"] = "TM";
                int pageSize = 500;
                short teamMemerRowId = Convert.ToInt16(Session["TeamMemberRowID"]);
                string Designation = Session["Designation"].ToString();


                //BindClientList();
                BindClientListBaseOnLogin(teamMemerRowId);
                CheckStatusOptionDropDown();
                CaseStatusOptionDropDown();

                if (CompleteFunction != "Bulk Process ID Check")
                {
                    if (Designation == "Team Member-Add")
                    {
                        string Statename = "";
                        if (StateRowId > 0)
                        {
                            DataTable dtstate = cc.GetStateName(StateRowId);
                            if (dtstate.Rows.Count > 0)
                            {
                                Statename = dtstate.Rows[0]["StateName"].ToString();
                            }
                        }
