        public bool GetPerfiosAadhaar(int PersonalRowId, int SubCheckRowId, string CandidateName, string aadhaarNo, int clientRowid)
        {
            bool resurlt = false;
            Aadhaar_verificationRoot Obj = new Aadhaar_verificationRoot();
            try
            {
                var ErrorPath = Server.MapPath("~\\ErrorLogs\\Logfiles");
                var APIPath = Server.MapPath("~\\APILogs\\Logfiles");
                ClientCustomize CC = new ClientCustomize();
                PerfiosAPI perfiosAPI = new PerfiosAPI();
                Obj = perfiosAPI.GetPerfiosAadhaar(CandidateName, PersonalRowId.ToString(), aadhaarNo, ErrorPath, APIPath);

                int teamMemerRowId = Convert.ToInt16(Session["TeamMemberRowID"]);
                if (Obj.statuscode == "101")
                {
                    int AutoId = cc.InsertUpdatePerfiosAadhaar_verification(Obj, PersonalRowId, aadhaarNo, teamMemerRowId, SubCheckRowId);

                    if (AutoId > 0)
                    {
                        var adhardt = CC.Antecedents_client_select_form(clientRowid, SubCheckRowId, "Operation", "Check");
                        if (adhardt.Rows.Count > 0)
                        {
                            for (int i = 0; i < adhardt.Rows.Count; i++)
                            {
                                int Antecedents = Convert.ToInt32(adhardt.Rows[i]["AntecedentsRowID"]);
                                int rst = CC.InsertUpdateAadhaarNumberCheckDetails(PersonalRowId, SubCheckRowId, Antecedents, clientRowid, aadhaarNo, CandidateName);
                            }
                        }
                        var tbl = CC.GetPerfiosAadhaar_verification(PersonalRowId, AutoId, SubCheckRowId);
                        string body = string.Empty;
                        using (StreamReader reader = new StreamReader(Server.MapPath("~/Emailers/PerfiosAadhaarCard.html")))
                        {
                            body = reader.ReadToEnd();
                        }
                        if (tbl.Rows.Count > 0)
                        {
                            if (tbl.Rows.Count > 0)
                            {
                                string companyRefNo = "";

                                companyRefNo = Convert.ToString(tbl.Rows[0]["CompanyRefNo"]);
                                body = body.Replace("{companyRefNo}", companyRefNo);
                                body = body.Replace("{name}", CandidateName);
                                body = body.Replace("{aadhaar_number}", aadhaarNo);
                                body = body.Replace("{age_range}", Convert.ToString(tbl.Rows[0]["ageBand"]));
                                body = body.Replace("{state}", Convert.ToString(tbl.Rows[0]["state"]));
                                body = body.Replace("{gender}", Convert.ToString(tbl.Rows[0]["gender"]));
                                string isIssued = "N";
                                if (Convert.ToInt32(tbl.Rows[0]["isIssued"]) == 1)
                                {
                                    isIssued = "Y";
                                }
                                body = body.Replace("{last_digits}", Convert.ToString(tbl.Rows[0]["mobile"]));
                                body = body.Replace("{is_mobile}", isIssued);
                                body = body.Replace("{verifiedDate}", DateTime.Now.Date.ToString("dd-MMM-yyyy"));

                                SavePQVerifiedUploadUANDoc(PersonalRowId, Convert.ToInt16(SubCheckRowId), "Verified", "Aadhaar", "provideddocuments", body, "Aadhaar Verified", 0, companyRefNo);
                                cc.UpdateTmMemberID(PersonalRowId, SubCheckRowId, "Perfios Software Solutions Pvt Ltd");
                                var rst = cc.UpdateCandidateChecksReportComments(PersonalRowId, Convert.ToInt16(SubCheckRowId));
                                cc.UpdateCheckStatus(PersonalRowId, SubCheckRowId, 1, 36, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));

                                if (clientRowid == 69)
                                {
                                    DataTable dtCount = cc.GetTitanCompleteCheckListCount(PersonalRowId);
                                    if (dtCount.Rows.Count > 0)
                                    {
                                        if (dtCount.Rows[0]["compChecks"].ToString() == "4")
                                        {
                                            DataTable dts = cc.CheckOpenInterimRequest(PersonalRowId);
                                            if (dts.Rows.Count == 0)
                                            {
                                                cc.Insert_InterimRequestForLTI(PersonalRowId, Convert.ToInt16(Session["TeamMemberRowID"]));
                                            }
                                        }
                                    }
                                }
                                cc.UpdatePQCandidateChecksColorCode(0, 6, "Green", PersonalRowId, SubCheckRowId, "Exact Match Found");
