        [HttpPost]
        [ValidateInput(false)]
        public ActionResult BulkpendingCaseapprovecriminal(string hdnSelected)
        {
            int ClientRowID = 0;
            int approvedCount = 0;
            try
            {
                ClientCustomize cc = new ClientCustomize();
                if (hdnSelected != "")
                {
                    string[] items = hdnSelected.Split(',');
                    foreach (string item in items)
                    {
                        string[] parts = item.Split('/');

                        int PersonalRowID = int.Parse(parts[0]);
                        int Subcheckrowid = int.Parse(parts[1]);
                        if (PersonalRowID > 0)
                        {
                            int result = cc.ISQcValueNullOrEmpty(PersonalRowID, Subcheckrowid);
                            if (result == 1)
                            {
                                continue;
                            }
                            #region Save LogTransaction Details
                            clsCommonMethods.AddPQLogTrasaction(PersonalRowID, "Criminal QC Approve", "Approve", "", "Criminal QC Approve");
                            #endregion
                            #region Case/Check Action History Save 
                            clsCommonMethods.AddCaseActionHistory(PersonalRowID, "Criminal QC Approve", "Approve");
                            #endregion
                            int clientRowid = 0;
                            string ColorName = "";
                            string ReportComment = "";
                            DataTable dtDisp = new DataTable();
                            dtDisp = cc.GetDispositionPQCandidateChecks(PersonalRowID, Subcheckrowid);
                            if (dtDisp.Rows.Count > 0)
                            {
                                ClientRowID = Convert.ToInt32(dtDisp.Rows[0]["ClientRowID"]);
                                ColorName = Convert.ToString(dtDisp.Rows[0]["ColorName"]);
                                ReportComment = Convert.ToString(dtDisp.Rows[0]["ReportComments"]).Replace("\r\n", "");

                            }
                            MasterArtifactMappingsApproving(PersonalRowID, 5, Subcheckrowid, "", ClientRowID);
                            if (ClientRowID == 277 || ClientRowID == 249)
                            {
                                var root = Server.MapPath("~/ExportPDF/");
                                InterimReportGenerateViewModel models = ConverdReportPDFFileToWord(PersonalRowID, Convert.ToInt16(ClientRowID));
                                DataTable cudt = new DataTable();
                                cudt = cc.GetSutherlandCRCCheck(PersonalRowID);
                                string sourcefile = models.ClientRefID + "_Interim" + "_" + models.FinalColor.ToUpper() + ".pdf";

                                if (cudt.Rows.Count > 0)
                                {
                                    if (cudt.Rows[0]["CheckFamilyRowID"].ToString() == "5")
                                    {
                                        cc.UploadReportDetails(PersonalRowID, sourcefile, "Completed", "");
                                        cc.finalReportDetail(PersonalRowID, 0, "Final", ColorName, Convert.ToString(PersonalRowID).ToString() + ".pdf", 1);
                                    }
                                }

                                #region Sutherland CRC API
                                DataTable dtDate = cc.getCheckStatus(PersonalRowID, Subcheckrowid);
                                if (ColorName.ToLower() == "green")
                                {
                                    Byte[] bytes = System.IO.File.ReadAllBytes(root + PersonalRowID + ".pdf");
                                    String file = Convert.ToBase64String(bytes);
                                    new API().UpdateAPICheckStatus(clientRowid.ToString().Trim(), PersonalRowID, Subcheckrowid, "CompletedbyOpsQC");  //APICheckStatus
                                    SutherlandCRC_StatusAPI(models.ClientRefID, models.CompanyRefNo, "Green-Interim Report", "Interim", "CRC Done", root + PersonalRowID + ".pdf", file, dtDate.Rows[0]["CreationDate"].ToString(), DateTime.Now.Date.ToString(), ReportComment);
                                }
                                else if (ColorName.ToLower() == "red")
                                {
                                    Byte[] bytes = System.IO.File.ReadAllBytes(root + PersonalRowID + ".pdf");
                                    String file = Convert.ToBase64String(bytes);
                                    SutherlandCRC_StatusAPI(models.ClientRefID, models.CompanyRefNo, ColorName, "Interim", "Major Discrepancy", root + PersonalRowID + ".pdf", file, dtDate.Rows[0]["CreationDate"].ToString(), DateTime.Now.Date.ToString(), ReportComment);
                                }
                                else if (ColorName.ToLower() == "grey")
                                {
                                    Byte[] bytes = System.IO.File.ReadAllBytes(root + PersonalRowID + ".pdf");
                                    String file = Convert.ToBase64String(bytes);
                                    SutherlandCRC_StatusAPI(models.ClientRefID, models.CompanyRefNo, ColorName, "Interim", "Insuff", root + PersonalRowID + ".pdf", file, dtDate.Rows[0]["CreationDate"].ToString(), DateTime.Now.Date.ToString(), ReportComment);

                                }
