                        addModel.PTRMgrAllocatedTo = AllocatePTR;

                        foreach (var item in verIDs)
                        {
                            addModel.AddressRowID = item;
                            DataTable dtcheck = cc.GetCheckDetails(item);
                            int PersonalRowID = 0;
                            short SubCheckRowID = 0;
                            string UniqueComponentID = "";
                            if (dtcheck.Rows.Count > 0)
                            {
                                PersonalRowID = Convert.ToInt32(dtcheck.Rows[0]["personalrowid"]);
                                SubCheckRowID = Convert.ToInt16(dtcheck.Rows[0]["SubCheckFamilyID"]);
                                UniqueComponentID = (dtcheck.Rows[0]["CheckUniqueID"].ToString());
                            }
                            //var addDetails = repoAddressInfo.GetPQAddressDetailsById(item);

                            //repoAddressInfo.UpdateAddressStatusByTeamMember(addModel);
                            cc.UpdateCheckStatus(PersonalRowID, SubCheckRowID, 1, 27, "Check", teamMemerRowId);
