                            cc.UpdatePartnerUserAllocationphysicalver(addModel.PTRMgrAllocatedTo, item);
                            #region Save LogTransaction Details
                            clsCommonMethods.AddPQLogTrasaction(PersonalRowID, "AddressTeamMemberAllocationToPartnerMgr", addModel.CheckStatus, UniqueComponentID, "Update");
                            #endregion

                            #region Case/Check Action History Save 
                            clsCommonMethods.AddCheckActionHistory(PersonalRowID, SubCheckRowID, addModel.CheckStatus, "Team Member Allocated To Partner");
                            #endregion

                            if (isMessageSend)
                            {
                                var CandidateData = repoPQPersonal.GetPQPersonalInfoForSession(PersonalRowID);
                                MessageStatus objMessage = new MessageStatus();
                                WhatsAppAPI objs = new WhatsAppAPI();
                                objMessage = objs.SendWhatsAppMessage("+91" + CandidateData.MobileNo, "pre_message_physical_visit_mode", CandidateData.CandidateFullName, "media_template", "", "");
                                cc.sp_AddAuditWhatsAppAPI(PersonalRowID, objMessage.message, objMessage.status, "Pre message Physical Visit mode message to candidate");
                            }

                        }
                    }

                    if (version == "New")
                    {
                        //model = repoVerificationInfo.GetCandidateAddressListForPTRMgrAllocationByTM1(page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, department, statusid, teamMemerRowId, StateRowId, CheckStatus, LocationId, Statename);
                        model = repoVerificationInfo.GetCandidateAddressListForPTRMgrAllocationByOPTM(page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, department, statusid, teamMemerRowId, StateRowId, CheckStatus, LocationId, Statename);
                        if (CheckStatus == "Reverification")
                        {
                            var list = model.PQVerificationInfo.Where(T => T.CheckType == "ReVerification").ToList();
                            model.PQVerificationInfo = list;
                            model.TotalRecords = list.Count();
                        }
                        else if (CheckStatus == "Pending" || CheckStatus == "Team Member PV")
                        {
                            var list = model.PQVerificationInfo.Where(T => T.CheckType != "ReVerification").ToList();
                            model.PQVerificationInfo = list;
                            model.TotalRecords = list.Count();
                        }
                    }
                    else
                    {
                        //model = repoVerificationInfo.GetCandidateAddressListForPTRMgrAllocationByTM(page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, teamMemerRowId, StateRowId, CheckStatus);
                        model = repoVerificationInfo.GetCandidateAddressListForPTRMgrAllocationByTM1(page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, department, statusid, teamMemerRowId, StateRowId, CheckStatus, LocationId);

                    }
                }

                if (model == null)
                {
                    ViewBag.ErrorMsg = "No item found!";
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View(model);
        }


