        public int DocUpload_EDU_ResearchToVerifiedDoc(int personalRowID = 0, int SubCheckid = 0)
        {
            try
            {
                ClientCustomize CCObj = new ClientCustomize();
                DataTable Dt = CCObj.GetEducationResearchDoc(personalRowID, SubCheckid);
                if (Dt.Rows.Count > 0)
                {
                    for (int i = 0; i < Dt.Rows.Count; i++)
                    {
                        string FldPathDoc = ConfigurationManager.AppSettings["MasterCollegeDocs"].ToString();
                        string PathDoc = ConfigurationManager.AppSettings["provideddocuments"].ToString();
                        string DocumentType = Convert.ToString(Dt.Rows[i]["DocumentType"]);
                        string FileName = Convert.ToString(Dt.Rows[i]["FileName"]);
                        var File_Name = "";
                        if (FileName.Length >= 50)
                        {
                            File_Name = FileName.Substring(0, 49);
                        }
                        else
                        {
                            File_Name = FileName;
                        }
                        DataTable FileExists = CCObj.VerifiedUploadDocsByDocumentType(File_Name, personalRowID, SubCheckid);
                        if (FileExists.Rows.Count == 0)
                        {
                            PQAddVerifiedUploadDocViewModel DocModel = new PQAddVerifiedUploadDocViewModel();
                            DocModel.PersonalRowID = personalRowID;
                            DocModel.SubCheckRowID = Convert.ToInt16(SubCheckid);
                            DocModel.DocumentUploadFrom = "Verified"; //  Provided / Verified


                            var MasterCollegeDocsPath = Server.MapPath(FldPathDoc + FileName);
                            var Timestamp = new DateTimeOffset(DateTime.UtcNow).ToUnixTimeSeconds();
                            string ext = Path.GetExtension(MasterCollegeDocsPath);
                            string FileNameToSave = DocumentType + Timestamp.ToString() + ext;
                            var provideddocumentsPath = Server.MapPath(PathDoc + FileNameToSave);
                            Byte[] bytes = System.IO.File.ReadAllBytes(MasterCollegeDocsPath);
                            string file = Convert.ToBase64String(bytes);
                            System.IO.File.WriteAllBytes(provideddocumentsPath, Convert.FromBase64String(file));
                            DocModel.FileName = FileNameToSave;
                            DocModel.DocumentType = FileNameToSave;
                            DocModel.FilePath = PathDoc;
                            DocModel.UploadDate = DateTime.Now;
                            DocModel.StatusDocxConvert = 0;
                            DocModel.StatusPDF2DOCXConvert = 0;
                            DocModel.PDF_FileName = "";
                            DocModel.Status = 1;
                            DocModel.RptArtiFacts = 0;
                            DocModel.Remarks = "Research Verified";
                            repoPQVerifiedUploadDoc.AddPQVerifiedUploadDoc(DocModel);
                            repoPQVerifiedUploadDoc.SaveChanges();
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                string msg = ex.Message;

            }
            return 0;
        }
