                        else if (CheckStatus == "Save")
                        {
                            cc.UpdatePQCandidateChecksColorCode(hdnDispositionID, hdnSeverity, ColorName, PersonalRowid, SubCheckid, ReportComment);
                        }
                        else
                        {
