                            }

                            #region If check Insuff then send alert mail for Client/Spoc/Candidate By the Company
                            if (CheckStatusId == 53)
                            {
                                ReportComment = Regex.Replace(ReportComment, "<.*?>", string.Empty);
                                ReportComment = clsCommonMethods.HTMLToText(ReportComment);
                                ReportComment = ReportComment.Replace("&nbsp;", "");
                                ReportComment = ReportComment.Replace("\r\n", "");
                                cc.UpdateCheckStatus(PersonalRowid, SubCheckid, 1, 22, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                                cc.Process_Remarks_Insert(PersonalRowid, SubCheckid, 22, ReportComment, "Operation-QC", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                                cc.UpdatePQCandidateChecksDates(PersonalRowid, SubCheckid, "InsuffRaised");
                                var data = repoPQClient.GetClientContractConditions(clientRowid);
                                var CandidateData = repoPQPersonal.GetPQPersonalInfoForSession(PersonalRowid);
                                int insuff = cc.GetCandidateIncludeInInsuffMail(clientRowid);
                                if (insuff == 1)
                                {
                                    //SendAlertMassageToGetInsuffDetailsFromCandidate(clientRowid, 0, 30, SubCheckid, PersonalRowid, CandidateData.EmailID, checkstatusid);
                                    SendAlertMassageToCandidate(clientRowid, 0, 30, SubCheckid, PersonalRowid, CandidateData.EmailID, checkstatusid);
                                    try
                                    {
                                        MessageStatus objMessage = new MessageStatus();
                                        WhatsAppAPI objs = new WhatsAppAPI();
                                        string ClientRowId = clsCommonMethods.PEncrypt(CandidateData.ClientRowID.ToString());
                                        string ChFamilRowId = clsCommonMethods.PEncrypt("30");
                                        string subCheckId = clsCommonMethods.PEncrypt(SubCheckid.ToString());
                                        string PersonalRowID = clsCommonMethods.PEncrypt(PersonalRowid.ToString());
                                        string CheckName = cc.GetCheckName(SubCheckid);
