        #region Update Special Check Verification By Quality Check
        [SessionExpireFilterAttribute]
        [HttpGet]
        public ActionResult UpdateSpecialCheckInfoByTMQC(int id = 0, int CheckStatusId = 0, bool Aging = false, int PersonalRowID = 0, short subCheckId = 0, short ClientRowId = 0, string ErrorMessage = "")
        {
            if (ErrorMessage != "")
            {
                ViewBag.ErrorMsg = ErrorMessage;
            }
            dynamic expando = new ExpandoObject();
            var marksModel = expando as IDictionary<string, object>;
            ViewBag.PersonalBind = repoPQPersonal.GetPersonalDetailsForTM(PersonalRowID, subCheckId);
            ClientCustomize cc = new ClientCustomize();

            DataTable dt = new DataTable();
            dt = cc.Antecedents_client_select_form(ClientRowId, subCheckId, "Operation", "Check");
            DataTable dbValue = new DataTable();
            dbValue = cc.GetOperationsValue(PersonalRowID, subCheckId);
            DataTable dts = cc.GetDispositionPQCandidateChecks(PersonalRowID, subCheckId);
            short ChFamilRowId = ViewBag.PersonalBind.CheckFamilyRowID;
            string CandidateName = ViewBag.PersonalBind.CandidateName;
            string CompanyRefNo = ViewBag.PersonalBind.CompanyReferenceNo;
            string SubReferenceID = ViewBag.PersonalBind.SubReferenceID;
            int tmid = Convert.ToInt32(Session["TeamMemberRowID"]);
            string Department = Session["Department"].ToString();
            int dptid = GetDepartmentIDName(tmid, Department);
            ViewBag.SpecialInstruction = GetSpecialInstructionsVerification(ClientRowId, ChFamilRowId, dptid);
            GetSpocActionRemark(PersonalRowID, subCheckId);
            int SeverityRowID = 0;
            string ColorCode = "";
            string SeverityGrid = "";
            DataTable dtcheck = cc.getCheckStatus(PersonalRowID, subCheckId);
            if (dtcheck.Rows.Count > 0)
            {
                int checkstatusid = Convert.ToInt32(dtcheck.Rows[0]["CheckStatusID"].ToString());
                if (dts.Rows.Count > 0)
                {

                    if (checkstatusid == 53)
                    {
                        SeverityRowID = 0;
                    }
                    else
                    {
                        if (checkstatusid != 107)
                        {
                            if (Convert.ToInt32(dts.Rows[0]["SeverityRowID"].ToString()) != 0)
                            {
                                SeverityRowID = Convert.ToInt32(dts.Rows[0]["SeverityRowID"].ToString());
                            }
                        }
                    }

                    ColorCode = dts.Rows[0]["ColorName"].ToString();
                    SeverityGrid = dts.Rows[0]["SeverityGrid"].ToString();

                    ViewBag.ReportComments = dts.Rows[0]["ReportComments"].ToString();
                    ViewBag.SeverityRowID = SeverityRowID;
                    ViewBag.ColorCode = ColorCode;
                    ViewBag.SeverityGrid = SeverityGrid;
                }
            }
            if (CheckStatusId == 53)
            {
                string OperationTMRemarks = cc.GetOperationTM_ProcessRemarks(PersonalRowID, subCheckId, CheckStatusId, "Operation-TM");
                ViewBag.ReportComments = OperationTMRemarks.Replace("\r\n", "");
            }


            foreach (DataRow d in dt.Rows)
            {
                DataRow[] rowsFiltered = dbValue.Select("AntecedentRowID=" + d[0].ToString());
                if (rowsFiltered.Length > 0)
                {
                    if (d[4].ToString() == "textbox")
                    {
                        marksModel.Add(d[1].ToString(), rowsFiltered[0][1]);
                    }
                    else if (d[4].ToString() == "dropdown")
                    {
                        marksModel.Add(d[1].ToString() + "_" + rowsFiltered[0][1].ToString() + "_" + d[3].ToString(), rowsFiltered[0][1].ToString());
                    }
                    else if (d[4].ToString() == "checkbox")
                    {
                        marksModel.Add(d[1].ToString() + "_" + rowsFiltered[0][1].ToString(), rowsFiltered[0][1].ToString());
                    }
                    else if (d[4].ToString() == "fileUpload")
                        marksModel.Add(d[1].ToString(), d[0].ToString().ToString());

                }
                else
                {

                    if (d[4].ToString() == "textbox")
                    {
                        marksModel.Add(d[1].ToString(), "");
                    }
                    else if (d[4].ToString() == "dropdown")
                    {
                        marksModel.Add(d[1].ToString() + "_" + d[2].ToString() + "_" + d[3].ToString(), d[0].ToString());
                    }
                    else if (d[4].ToString() == "checkbox")
                    {
                        marksModel.Add(d[1].ToString() + "_" + d[2].ToString(), d[0].ToString());
                    }
                    else
                        marksModel.Add(d[1].ToString(), d[0].ToString());
                }
            }


            ViewBag.PersonalRowid = PersonalRowID.ToString();
            ViewBag.CandCheckRowID = id.ToString();
            ViewBag.CandidateName = CandidateName.ToString();
            ViewBag.SubReferenceID = SubReferenceID.ToString();
            ViewBag.CompanyRefNo = CompanyRefNo.ToString();
            ViewBag.SubCheckId = subCheckId.ToString();
            ViewBag.clientRowId = ClientRowId.ToString();
            ViewBag.CheckStatusid = CheckStatusId.ToString();
            GetCaseDocumentList(PersonalRowID);
            BindDocumentList(PersonalRowID, subCheckId);
            BindSeverityGrids(ClientRowId);
            BindDispositions(40, ClientRowId);
            MasterArtifactMappingsApproving(PersonalRowID, 40, subCheckId, "", ClientRowId);

            return View(marksModel);
        }

