        [SessionExpireFilterAttribute]
        public ActionResult ExportDigilockerchecks(string ClientRowId, string dtf, string dtt)
        {
            short ClientRowID = 0;
            try
            {
                //var tblRowID = GetClientRowID(ClientRowId);
                //ClientRowID = Convert.ToInt16(clsCommonMethods.PDecrypt(ClientRowId));

                short teamMemerRowId = Convert.ToInt16(Session["TeamMemberRowID"]);
                ClientCustomize cc = new ClientCustomize();
                DataSet ds = new DataSet();

                ds = cc.GetDigiLockerTrackerCheck("", teamMemerRowId, dtf, dtt);
                if (ds.Tables.Count > 0)
                {
                    var dt = new DataTable("Details");
                    dt = ds.Tables[0];
                    using (ClosedXML.Excel.XLWorkbook wb = new ClosedXML.Excel.XLWorkbook())
                    {
                        var ws = wb.Worksheets.Add(dt);
                        ws.Tables.FirstOrDefault().ShowAutoFilter = false;
                        //wb.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                        wb.Style.Font.Bold = true;
                        Response.Clear();
                        Response.Buffer = true;
                        Response.Charset = "";
                        Response.ContentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
                        Response.AddHeader("content-disposition", "attachment;filename=DigiLockerTracker.xlsx");

                        using (MemoryStream MyMemoryStream = new MemoryStream())
                        {
                            wb.SaveAs(MyMemoryStream);
                            MyMemoryStream.WriteTo(Response.OutputStream);
                            Response.Flush();
                            Response.End();
                        }
                    }
                }


                return null;
            }

            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return RedirectToAction("DigiLockerTracker", "Verification");
            }
        }


        [SessionExpireFilterAttribute]
        public ActionResult ManageRWQCApprovalChecksForDepartmentTL(int page = 1, string sort = "", string sortDir = "asc", string Search = "", short ClientRowID = 0, string CheckStatus = "", string version = "New", string CheckStatusId = "")
        {
            string statusid = "";
            string department = "";
            if (CheckStatus == "Review")
            {
                statusid = "19";
            }
            else if (CheckStatus == "Reverification")
            {
                statusid = "20";
            }
            else
            {
                statusid = CheckStatusId;
            }
            Session["CheckStatus"] = CheckStatus;
            Session["version"] = version;
            Session["Member"] = "TL";
            VerificationInfoListPagedModel model = new VerificationInfoListPagedModel();
            try
            {
                int pageSize = clsGlobalCommon.PageSize;
                short teamMemberId = Convert.ToInt16(Session["TeamMemberRowID"]);
                string Designation = Session["Designation"].ToString();
                if (version == "New")
                {
                    if (Designation == "Team Leader-Emp")
                    {
                        department = "Employment";
                    }
                    else if (Designation == "Team Leader-Ide")
                    {
                        department = "National Identity";
                    }
                    else if (Designation == "Team Leader-Ref")
                    {
                        department = "Reference";
                    }
                    else if (Designation == "Team Leader-SPL")
                    {
                        department = "Special Check";
                    }
                    else if (Designation == "Team Leader-Cri")
                    {
                        department = "Criminal";
                    }
                    else if (Designation == "Team Leader-Add")
                    {
                        department = "Address";
                    }
                    else if (Designation == "Team Leader-Edu")
                    {
                        department = "Education";
                    }
                    if (CheckStatus == "Reverification")
                    {
                        if (department.ToLower() == "employment")
                        {
                            model = repoVerificationInfo.GetCandidateEmploymentListByDepartmentTeamLeader1(page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, department, statusid, teamMemberId, ClientRowID, CheckStatus, designation: Designation);

                        }
                        else
                        {
                            model = repoVerificationInfo.GetCandidateEducationReverificationDetails(page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, department, statusid, teamMemberId, ClientRowID, CheckStatus);
                        }
                    }
                    if (CheckStatus == "WIP")
                    {
                        model = repoVerificationInfo.GetCandidateEducationReverificationDetails(page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, department, statusid, teamMemberId, ClientRowID, CheckStatus);

                    }
                    else
                    {
                        model = repoVerificationInfo.GetCandidateListForTMMQCNew(page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, department, statusid, teamMemberId, ClientRowID, CheckStatus, designation: Designation);

                    }

                }
                else
                {
                    model = repoVerificationInfo.GetRWApprovalCheckListForDepartmentTL(page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, ClientRowID, teamMemberId);

                }

            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            BindClientList();
            return View(model);

        }

        [HttpGet]
        [SessionExpireFilterAttribute]
        public ActionResult UpdateAddressVerInfoByTeamLeader(int id, int CheckStatusId = 0, bool Aging = false, int PersonalRowID = 0, short subCheckId = 0, short ClientRowId = 0)
        {
            dynamic expando = new ExpandoObject();
            var marksModel = expando as IDictionary<string, object>;
            ClientCustomize cc = new ClientCustomize();

            DataTable dt = new DataTable();
            dt = cc.Antecedents_client_select_form(ClientRowId, subCheckId, "Operation", "Check");

            DataTable dbValue = new DataTable();
            dbValue = cc.GetReportValue(PersonalRowID, subCheckId);
            GetSpocActionRemark(PersonalRowID, subCheckId);

            foreach (DataRow d in dt.Rows)
            {
                DataRow[] rowsFiltered = dbValue.Select("AntecedentRowID=" + d[0].ToString());
                if (rowsFiltered.Length > 0)
                {
                    if (d[4].ToString() == "textbox")
                    {
                        marksModel.Add(d[1].ToString(), rowsFiltered[0][1]);
                    }
                    else if (d[4].ToString() == "dropdown")
                    {
                        marksModel.Add(d[1].ToString() + "_" + rowsFiltered[0][1].ToString() + "_" + d[3].ToString(), rowsFiltered[0][1].ToString());
                    }
                    else if (d[4].ToString() == "checkbox")
                    {
                        marksModel.Add(d[1].ToString() + "_" + rowsFiltered[0][1].ToString(), rowsFiltered[0][1].ToString());
                    }
                    else if (d[4].ToString() == "fileUpload")
                        marksModel.Add(d[1].ToString(), d[0].ToString().ToString());

                }
                else
                {

                    if (d[4].ToString() == "textbox")
                    {
                        marksModel.Add(d[1].ToString(), "");
                    }
                    else if (d[4].ToString() == "dropdown")
                    {
                        marksModel.Add(d[1].ToString() + "_" + d[2].ToString() + "_" + d[3].ToString(), d[0].ToString());
                    }
                    else if (d[4].ToString() == "checkbox")
                    {
                        marksModel.Add(d[1].ToString() + "_" + d[2].ToString(), d[0].ToString());
                    }
                    else
                        marksModel.Add(d[1].ToString(), d[0].ToString());
                }
            }

            DataTable dtDisp = new DataTable();
            dtDisp = cc.GetDispositionPQCandidateChecks(PersonalRowID, subCheckId);
            if (dtDisp.Rows.Count > 0)
            {
                ViewBag.CDispositionName = dtDisp.Rows[0]["DispositionRowId"].ToString();
                ViewBag.ColorName = dtDisp.Rows[0]["ColorName"].ToString();
                ViewBag.Severity = dtDisp.Rows[0]["SeverityGrid"].ToString();
                ViewBag.Severityid = dtDisp.Rows[0]["SeverityRowId"].ToString();
            }
            ViewBag.ReportComments = cc.GetProcessRemarks(PersonalRowID, subCheckId, CheckStatusId);

            ViewBag.PersonalRowid = PersonalRowID.ToString();
            ViewBag.SubCheckId = subCheckId.ToString();
            ViewBag.clientRowId = ClientRowId.ToString();
            ViewBag.CheckStatusid = CheckStatusId.ToString();
            BindDispositions(12, ClientRowId);
            BindDocumentList(PersonalRowID, subCheckId);
            GetCaseDocumentList(PersonalRowID);
            BindMailList(PersonalRowID, subCheckId);
            ViewBag.PersonalBind = repoPQPersonal.GetPersonalDetailsForTM(PersonalRowID, subCheckId);
            //GetEmploymentList();
            return View(marksModel);
        }

