            dynamic expando = new ExpandoObject();
            var marksModel = expando as IDictionary<string, object>;
            try
            {
                short teamMemerRowId = Convert.ToInt16(Session["TeamMemberRowID"]);
                int PersonalRowid = Convert.ToInt32(formCollection["PersonalRowid"].ToString());
                short SubCheckid = Convert.ToInt16(formCollection["SubCheckId"].ToString());
                short clientRowid = Convert.ToInt16(formCollection["clientRowId"].ToString());
                string ReportComment = formCollection["Remark"].ToString();
                string ColorsName = formCollection["ColorsName"].ToString();
                GetSpocActionRemark(PersonalRowid, SubCheckid);

                string Checkstatus = action;
                ViewBag.Error = "";
                if (ModelState.IsValid)
                {
                    if (SubCheckid > 0 && PersonalRowid > 0)
                    {
                        int CheckStatusId = cc.getCurrentCheckStatus(PersonalRowid, SubCheckid);
                        DataTable Dtcheck = cc.getCheckStatus(PersonalRowid, SubCheckid);
                        if (Dtcheck.Rows.Count > 0)
                        {
                            ColorsName = Dtcheck.Rows[0]["ColorCode"].ToString();
                        }
                        #region Update Employment Information

                        string DesignationName = Convert.ToString(Session["Designation"]);


                        #region Save LogTransaction Details
                        clsCommonMethods.AddPQLogTrasaction(PersonalRowid, "UpdateSpecialVerInfoByTeamLeader", Checkstatus, "", "Update");
                        #endregion
                        if (CheckStatusId == 54)
                        {
                            if (Checkstatus == "Reject")
                            {
                                cc.UpdateCheckStatus(PersonalRowid, SubCheckid, 1, 20, "Check", teamMemerRowId);
                                clsCommonMethods.AddCheckActionHistory(PersonalRowid, SubCheckid, Checkstatus, "Rejected By Verifier Team Lead");
                            }
                            else
                            {
                                ReportComment = Regex.Replace(ReportComment, "<.*?>", string.Empty);
                                ReportComment = clsCommonMethods.HTMLToText(ReportComment);
                                ReportComment = ReportComment.Replace("&nbsp;", "");
                                ReportComment = ReportComment.Replace("\r\n", "");
                                cc.UpdateCheckStatus(PersonalRowid, SubCheckid, 1, 22, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                                cc.Process_Remarks_Insert(PersonalRowid, SubCheckid, 22, ReportComment, "Operation-TL", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                                cc.UpdatePQCandidateChecksDates(PersonalRowid, SubCheckid, "InsuffRaised");
                                new API().UpdateAPICheckStatus(clientRowid.ToString().Trim(), PersonalRowid, SubCheckid, "L2Insuff");  //APICheckStatus
                                var data = repoPQClient.GetClientContractConditions(clientRowid);
                                var CandidateData = repoPQPersonal.GetPQPersonalInfoForSession(PersonalRowid);
                                int insuff = cc.GetCandidateIncludeInInsuffMail(clientRowid);
                                if (insuff == 1)
                                {
                                    SendAlertMassageToCandidate(clientRowid, 0, 40, SubCheckid, PersonalRowid, CandidateData.EmailID, CheckStatusId);
                                    try
                                    {
                                        MessageStatus objMessage = new MessageStatus();
                                        WhatsAppAPI objs = new WhatsAppAPI();
                                        string ClientRowId = clsCommonMethods.PEncrypt(CandidateData.ClientRowID.ToString());
                                        string ChFamilRowId = clsCommonMethods.PEncrypt("40");
                                        string subCheckId = clsCommonMethods.PEncrypt(SubCheckid.ToString());
                                        string PersonalRowID = clsCommonMethods.PEncrypt(PersonalRowid.ToString());
                                        string CheckName = cc.GetCheckName(SubCheckid);
                                        var Remarks = "Securitas ID:" + CandidateData.CompanyRefNo + ", " + CheckName + " " + TempData["Remarks"].ToString();
                                        var links = "https://bgv.securitas-india.com/account/InsuffClear/?CRId=" + ClientRowId + "&ChRId=" + ChFamilRowId + "&sCId=" + subCheckId + "&PRID=" + PersonalRowID;
                                        //var links = "https://stg.weverifyglobal.com/account/InsuffClear/?CRId=" + ClientRowId + "&ChRId=" + ChFamilRowId + "&sCId=" + subCheckId + "&PRID=" + PersonalRowID;
                                        objMessage = objs.SendWhatsAppMessage("+91" + CandidateData.MobileNo, "insuff_message_to_candidate", CandidateData.CandidateFullName, "media_template", Remarks, links);
                                        cc.sp_AddAuditWhatsAppAPI(PersonalRowid, objMessage.message, objMessage.status, "Insufficiency message to candidate");
                                    }
                                    catch (Exception ex) { }
                                }
                                else
                                {
                                    SendAlertMassageForInsuffClearationForClientSpoc(clientRowid, 0, 40, SubCheckid, CandidateData.ClientUserRowId, PersonalRowid, CheckStatusId);
                                }
                                clsCommonMethods.AddCheckActionHistory(PersonalRowid, SubCheckid, Checkstatus, ReportComment);
                            }
                        }
                        else if (Checkstatus == "Approve" && ColorsName == "")
                        {

                            TempData["ErrorMsg"] = "Reject Check color code is blank!";
                            ViewBag.Error = "Reject Check color code is blank!";
                        }
                        else
                        {
                            if (Checkstatus != "Reject")
                            {
                                if (ColorsName == "Red")
                                {
                                    cc.UpdateCheckStatus(PersonalRowid, SubCheckid, 1, 71, "Check", teamMemerRowId);
                                }
                                else
                                {
                                    cc.UpdateCheckStatus(PersonalRowid, SubCheckid, 1, 71, "Check", teamMemerRowId);
                                }
                            }
                            else
                            {
                                cc.UpdateCheckStatus(PersonalRowid, SubCheckid, 1, 20, "Check", teamMemerRowId);
                            }

                            #region Case/Check Action History Save 
                            clsCommonMethods.AddCheckActionHistory(PersonalRowid, SubCheckid, Checkstatus, ReportComment);
                            #endregion
                        }
                        if (ViewBag.Error == "")
                        {

                            DataTable dt = new DataTable();
                            dt = cc.Antecedents_client_select_form(clientRowid, SubCheckid, "Operation", "Check");

                            DataTable dbValue = new DataTable();
                            dbValue = cc.GetReportValue(PersonalRowid, SubCheckid);


                            foreach (DataRow d in dt.Rows)
                            {
                                DataRow[] rowsFiltered = dbValue.Select("AntecedentRowID=" + d[0].ToString());
                                if (rowsFiltered.Length > 0)
                                {
                                    if (d[4].ToString() == "textbox")
                                    {
                                        marksModel.Add(d[1].ToString(), rowsFiltered[0][1]);
                                    }
                                    else if (d[4].ToString() == "dropdown")
                                    {
                                        marksModel.Add(d[1].ToString() + "_" + rowsFiltered[0][1].ToString() + "_" + d[3].ToString(), rowsFiltered[0][1].ToString());
                                    }
                                    else if (d[4].ToString() == "checkbox")
                                    {
                                        marksModel.Add(d[1].ToString() + "_" + rowsFiltered[0][1].ToString(), rowsFiltered[0][1].ToString());
                                    }
                                    else if (d[4].ToString() == "fileUpload")
                                        marksModel.Add(d[1].ToString(), d[0].ToString().ToString());

                                }
                                else
                                {

                                    if (d[4].ToString() == "textbox")
                                    {
                                        marksModel.Add(d[1].ToString(), "");
                                    }
                                    else if (d[4].ToString() == "dropdown")
                                    {
                                        marksModel.Add(d[1].ToString() + "_" + d[2].ToString() + "_" + d[3].ToString(), d[0].ToString());
                                    }
                                    else if (d[4].ToString() == "checkbox")
                                    {
                                        marksModel.Add(d[1].ToString() + "_" + d[2].ToString(), d[0].ToString());
                                    }
                                    else
                                        marksModel.Add(d[1].ToString(), d[0].ToString());
                                }
                            }


                            TempData["SuccessMsg"] = "Record Update Successfully!";
                        }
                        ModelState.Clear();
                        if (Session["Designation"] != null && Session["Designation"].ToString() == "Team Leader-Edu" && CheckStatusId == 54)
                        {
                            return RedirectToAction("DepartmentTeamLeaderAllocation", "Verification", new { CheckStatus = "L2InsuffApproved", version = "New" });
                        }
                        else if (Session["Designation"] != null && Session["Designation"].ToString() == "Team Leader-SPL")
                        {
                            return RedirectToAction("ManageRWQCApprovalChecksForDepartmentTL", "Verification", new { CheckStatusId = CheckStatusId });
                        }
                        else
                        {
                            return RedirectToAction("ManageRWQCApprovalChecksForDepartmentManager", "Verification");
                        }
                    }
                    #endregion
                }
                else
                {
                    ModelState.AddModelError("", "Invalid model!");
                }


            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            //ViewBag.ListEmployment = repoDDL.GetAntecedentList(model.ClientRowID, model.CheckFamilyRowID, model.SubCheckRowID);

            //model.UploadedDocInfo = repoPQVerifiedUploadDoc.GetCheckUploadDocList(model.PersonalRowID, model.SubCheckRowID);
            return View(marksModel);
        }

