                        }
                    }
                    To = spocEmail + "," + cSpocEmail + "," + toMail;
                }
                else
                {
                    To = spocEmail + "," + cSpocEmail;
                }
                string ToMail = To.ToLower();
                bool flag = false;
                if (ClientAcctessType == 3)
                {
                    string cc = "";
                    string Tos = "";
                    Tos = spocEmail;
                    cc = cSpocEmail;
                    if (ClientRowID == 559)
                    {
                        Tos = spocEmail;
                        cc = cSpocEmail + "," + "rrashwini@firstam.com" + "," + "mvsubbarao@firstam.com";

                        flag = mail.SendMail(DisplayName, From, Tos, cc, Subject, body);

                    }
                    else
