                }

                //using (StreamReader reader = new StreamReader(Server.MapPath("~/Emailers/Company/insuffCandidate.html")))
                //{
                //    body = reader.ReadToEnd();
                //}
                body = body.Replace("{CandidateName}", personalData.CandidateName);
