                mail = new clsSendMail(cSmtp.SMTPServer, cSmtp.SMTPPort, cSmtp.SMTPUserName, clsCommonMethods.PDecrypt(cSmtp.SMTPPassword), Convert.ToBoolean(cSmtp.EnableSsl));
                From = cSmtp.CSendInsuffEmail != null ? cSmtp.CSendInsuffEmail : cSmtp.SMTPUserName;
                DisplayName = cSmtp.CSendInsuffDisplay != null ? cSmtp.CSendInsuffDisplay : cSmtp.ClientName.Trim();
                MailSignature = string.Concat("<b>", cSmtp.ClientName.Trim(), "</b><br /><b>E-mail id </b>: <a style='color:#df012a;' href='mailto:", cSmtp.SMTPUserName, "'>", cSmtp.SMTPUserName, "</a>");
            }
            else
            {
                mail = new clsSendMail();
                var signature = mail.GetCompanyMailSignature();
                if (signature != null)
                {
                    MailSignature = string.Concat("For Securitas India. <br /><br />");
                    MailSignature = string.Concat(MailSignature, "<b>", signature.CompanyName.Trim(), "</b><br /><b>Mobile: ", signature.MobileNo,
                        " | Direct Tel: ", signature.PhoneNo, " | Fax: ", signature.FaxNo, "</b><br /><b>E-mail id </b>: <a style='color:#df012a;' href='mailto:", signature.GeneralEmail, "'>", signature.GeneralEmail, "</a>");
                }
                From = signature.GeneralEmail;
                DisplayName = signature.CompanyName.Trim();
            }

            var personalData = repoPQPersonal.GetCheckOrPersonalDetailsForSendMailByIdNew(CheckFamilyRowID, SubCheckRowID, PersonalRowID, CheckStatusId);

            if (personalData != null)
            {
                var templateDBInsuffMail = cc.getAlertMailtemplate(Convert.ToInt32(personalData.ClientRowID), "Candidate Insuff", 0, 1, "CandidateInsufficiency");
                if (templateDBInsuffMail.Rows.Count > 0)
                {
                    body1 = Convert.ToString(templateDBInsuffMail.Rows[0]["MailTemplate"]);
                }


                body1 = body1.Replace("{FCandidateName}", personalData.CandidateName);
                body1 = body1.Replace("{FCheckName}", personalData.SubCheckName);
                body1 = body1.Replace("{FClientRefId}", personalData.ClientRefID);
                body1 = body1.Replace("{FInsuffRemarks}", personalData.Remarks);
                body1 = body1.Replace("{FReferenceID}", personalData.CompanyRefNo);
                //if (personalData.ClientRowID == 8)
                //{
                body1 = body1.Replace("{Verificationsource}", personalData.Verificationsource);
                body1 = body1.Replace("{FLocationName}", personalData.locationName);
                //}
                TempData["Remarks"] = personalData.Remarks;
                string ClientRowId = clsCommonMethods.PEncrypt(personalData.ClientRowID.ToString());
                string ChFamilRowId = clsCommonMethods.PEncrypt(personalData.CheckFamilyRowID.ToString());
                string subCheckId = clsCommonMethods.PEncrypt(personalData.SubCheckRowID.ToString());
                string PersonalRowId = clsCommonMethods.PEncrypt(personalData.PersonalRowID.ToString());
                string actionFrom = clsCommonMethods.PEncrypt("");
                var links = "https://bgv.securitas-india.com/account/InsufficiencyClearByClient/?ClientRowId=" + ClientRowId + "&ChFamilRowId=" + ChFamilRowId + "&subCheckId=" + subCheckId + "&PersonalRowID=" + clsCommonMethods.PEncrypt(Convert.ToString(personalData.PersonalRowID)) + "&actionFrom=" + actionFrom;
                //var links = "https://stg.weverifyglobal.com/account/InsuffClear/?CRId=" + ClientRowId + "&ChRId=" + ChFamilRowId + "&sCId=" + subCheckId + "&PRID=" + PersonalRowId;
                body1 = body1.Replace("{DBInsuffLink}", links);
                body1 = body1.Replace("{MailSignature}", MailSignature);

                string Subject = "";
                if (personalData.ClientUserRowID == 4988)
                {
                    Subject = "Insufficiency " + personalData.CandidateName + "  " + personalData.SubCheckName + " - Senior Hire";
                }
                else
                {
                    Subject = "Insufficiency " + personalData.CandidateName + "  " + personalData.SubCheckName;
                }


                string ToMail = CandidateEmail.ToLower();

                ToMail = ToMail.Replace(",", ";");
                string[] arToMail = ToMail.Split(';');
                ToMail = "";
                foreach (string a in arToMail)
                {
                    if (!ToMail.Contains(a))
                    {
                        ToMail = ToMail + a.Trim() + ",";
                    }
                }
                if (ToMail.Length > 1)
                    ToMail = ToMail.Substring(0, ToMail.Length - 1);
                bool flag = false;
                if (ClientRowID == 113)
                {
                    flag = mail.SendmicrolandMail(DisplayName, From, personalData.EmailID, Subject, body1);
                }
                else if (ClientRowID == 1674)
                {
                    ClientCustomize cc = new ClientCustomize();
                    string Ccmail = cc.Get_SendInsuffEmailForCandidate(PersonalRowID, ClientRowID);
                    if (!string.IsNullOrWhiteSpace(Ccmail))
                    {

                        flag = mail.SendMail(DisplayName, From, Ccmail, Subject, body1);
                    }
                }
                else
                {
                    ClientCustomize cc = new ClientCustomize();
                    string Ccmail = cc.Get_SendInsuffEmailForCandidate(PersonalRowID, ClientRowID);
                    //===========================
                    var recuiterEmail = "";
                    if ((ClientRowID == 636 || ClientRowID == 1618) && CheckStatusId == 53)
                    {
                        if (CheckStatusId == 53)
                        {
                            DataTable dto = cc.GetRecuiterEmailIdbyClient(Convert.ToInt32(PersonalRowId), ClientRowID);
                            recuiterEmail = dto.Rows[0]["RecuriterEmail"].ToString();
                        }
                        if (Ccmail == "")
                        {
                            Ccmail = recuiterEmail;
                        }
                        if (Ccmail != "")
                        {
                            Ccmail += "," + recuiterEmail;
                        }
                    }

                    if (ClientRowID == 1481)
                    {

                        DataTable dto = cc.GetRecuiterEmailIdbyClient1(personalData.PersonalRowID, ClientRowID);

                        var recuiteremail = dto.Rows[0]["RecuriterEmail"].ToString();

                        {
                            Ccmail += "," + recuiteremail;
                        }
                    }

                    //====================================
                    if (Ccmail == "")
                    {

                        flag = mail.SendMail(DisplayName, From, personalData.EmailID, Subject, body1);
                    }
                    else
                    {
                        flag = mail.SendMail(DisplayName, From, personalData.EmailID, Ccmail, Subject, body1);
                    }

                    cc.saveCandidatemail(personalData.PersonalRowID, "Insuff mail", personalData.EmailID, Ccmail, Subject, body1, ClientRowID, 1, personalData.SubCheckRowID);

                    if (CheckStatusId == 53)
                    {
                        ClientCustomize ccc = new ClientCustomize();
                        ccc.InsertUpdateFollowUpEmails(CheckRowID, SubCheckRowID, "Insufff", CheckStatusId, Subject, body1, personalData.EmailID, Ccmail, "", null, Convert.ToInt32(Session["TeamMemberRowID"]), "Add_Update");
                    }
                }


                if (flag)
                {
                    result = true;
                }
                else
                {
                    TempData["ErrorMsg"] = "Mail sending failed!";
                }
            }
            else
            {
                TempData["ErrorMsg"] = "Candidate login details not found!";
            }
            return result;
        }


