        public void ExportToExcel(DataTable dt, string strFileName)
        {
            if (dt.Rows.Count > 0)
            {
                foreach (DataColumn col in dt.Columns)
                {
                    if (col.DataType != typeof(string)) continue;

                    foreach (DataRow row in dt.Rows)
                    {
                        if (row[col] == DBNull.Value) continue;

                        row[col] = row[col].ToString()
                            .Replace("&", "&amp;")   // ye sabse pehle hona zaroori hai-- Sunny
                            .Replace("<", "&lt;")
                            .Replace(">", "&gt;");
                    }
                }

                System.IO.StringWriter tw = new System.IO.StringWriter();
                System.Web.UI.HtmlTextWriter hw = new System.Web.UI.HtmlTextWriter(tw);
                DataGrid dgGrid = new DataGrid();
                dgGrid.DataSource = dt;
                dgGrid.DataBind();

                // Render the DataGrid control
                dgGrid.RenderControl(hw);

                // Prepare UTF-8 encoded bytes with meta tag
                string htmlWithMeta = @"<html><head>
        <meta http-equiv='Content-Type' content='text/html; charset=utf-8'>
        </head><body>" + tw.ToString() + "</body></html>";

                byte[] utfBytes = System.Text.Encoding.UTF8.GetBytes(htmlWithMeta);

                // Clear the response and set headers
                Response.Clear();
                Response.Buffer = true;
                Response.Charset = "utf-8";
                Response.ContentEncoding = System.Text.Encoding.UTF8;
                Response.ContentType = "application/vnd.ms-excel";
                Response.AddHeader("Content-Disposition", "attachment; filename=" + strFileName + ".xls");

                // Write UTF-8 bytes directly
                Response.BinaryWrite(utfBytes);
                Response.End();
            }
        }


        public void ExportToExcelNew(DataTable dt, string fileName)
        {
            // Remove leading spaces from first column
            foreach (DataRow row in dt.Rows)
            {
                if (row[0] != DBNull.Value)
                {
                    row[0] = row[0].ToString().TrimStart().TrimEnd();
                }
            }

            using (XLWorkbook wb = new XLWorkbook())
            {
                var ws = wb.Worksheets.Add("Sheet1");

                int colCount = dt.Columns.Count;
                int rowCount = dt.Rows.Count;

                // Add Header Row
                for (int col = 0; col < colCount; col++)
                {
                    ws.Cell(1, col + 1).Value = dt.Columns[col].ColumnName;
                }

                // Header formatting
                var headerRange = ws.Range(1, 1, 1, colCount);
                headerRange.Style.Font.Bold = true;
                headerRange.Style.Fill.BackgroundColor = XLColor.LightBlue;
                headerRange.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;

                // Add Data Rows
                for (int row = 0; row < rowCount; row++)
                {
                    for (int col = 0; col < colCount; col++)
                    {
                        ws.Cell(row + 2, col + 1).Value =
                            dt.Rows[row][col]?.ToString();
                    }
                }

                // Formatting
                //ws.Columns().AdjustToContents();
                ws.SheetView.FreezeRows(1);

                ws.Range(1, 1, rowCount + 1, colCount).Style.Border.OutsideBorder =
                    XLBorderStyleValues.Thin;

                ws.Range(1, 1, rowCount + 1, colCount).Style.Border.InsideBorder =
                    XLBorderStyleValues.Thin;

                // Response Download
                Response.Clear();
                Response.Buffer = true;
                Response.Charset = "";

                Response.ContentType =
                    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

                Response.AddHeader(
                    "content-disposition",
                    "attachment;filename=" + fileName + "-" + DateTime.Now.Date.ToString("dd-MM-yyyy") + ".xlsx"
                );

                using (MemoryStream stream = new MemoryStream())
                {
                    wb.SaveAs(stream);
                    stream.Position = 0;
                    stream.CopyTo(Response.OutputStream);
                    Response.Flush();
                    System.Web.HttpContext.Current.ApplicationInstance.CompleteRequest();
                }
            }
        }


