        [HttpPost]
        [SessionExpireFilterAttribute]

        public ActionResult UplodAddressCheckDocsAndComplete(VerifiedUploadAddressDocViewModel model)
        {
            try
            {
                if (ModelState.IsValid)
                {
                    string FldPathDoc = ConfigurationManager.AppSettings["provideddocuments"].ToString();
                    string proImg = string.Empty;
                    model.Remarks = "Uploaded By TM";

                    // ===== SIGNATURE =====
                    if (model.UploadSignatureDoc != null && model.UploadSignatureDoc.Length > 0)
                    {
                        ClientCustomize CC = new ClientCustomize();
                        int inputSize = CC.GetControlInputs("ArtifactPageSize");
                        foreach (HttpPostedFileBase sigFile in model.UploadSignatureDoc)
                        {
                            if (sigFile == null || sigFile.ContentLength <= 0) continue;
                            int pageCount = GetNoOfPageInPDFFile(sigFile);
                            if (pageCount <= inputSize)
                            {
                                model.DocumentType = "Signature";
                                model.DocumentUploadFrom = "Verified";
                                model.Status = 1;
                                model.UploadDate = DateTime.Now;

                                cc.UpdateImageArtifact(model.PersonalRowID, model.SubCheckRowID);
                                string ext = Path.GetExtension(sigFile.FileName).ToLower();
                                proImg = (model.SubCheckRowID + "_" + model.PersonalRowID + "_" + model.UploadDate.Value.ToString("ddmmyyyy") + "_" + model.DocumentType + "_" + Guid.NewGuid().ToString("N")).Replace("'", "_").Replace("&", "_").Replace(":", "_").Replace("-", "_").Replace(" ", "_") + ext;
                                sigFile.SaveAs(Server.MapPath(FldPathDoc + proImg));
