        public ViewResult Generate_MIS(string NM = "", string DateFrom = "", string DateTo = "", string clid = "")
        {
            try
            {
                short teamMemerRowId = Convert.ToInt16(Session["TeamMemberRowID"]);
                DataTable DT = new DataTable();
                //DT = cc.MIS_All(NM, DateFrom, DateTo, clid);
                if (clid == "null" || clid == "" || clid == "undefined")
                {
                    clid = "0";
                }
                if (teamMemerRowId == 528 && NM == "WIPPOOL")
                {
                    DT = cc.MIS_WIPPOOL_ALL(teamMemerRowId, DateFrom, DateTo, clid);
                }
                else if (teamMemerRowId == 528 && NM == "Genpact mis")
                {
                    DT = cc.MIS_genpact(DateFrom, DateTo);
                }
                else if (NM == "FundRequestRaised")
                {
                    DT = cc.MISFundRequestRaised(clid, DateFrom, DateTo);
                }
                else if (NM == "CapegiminiNONGreenReports")
                {
                    DT = cc.Capegiminiredorange(DateFrom, DateTo);
                }
                else
                {
                    DT = cc.MIS_All_MultipleClient(NM, DateFrom, DateTo, clid);
                }

                if (DT.Rows.Count > 0)
                {
                    if (NM == "Ageing RW Team")
                    {
                        ExportToExcel(DT, "WT_BT_Ageing_RW_Team");
                        BindClientList();
                    }
                    else if (NM == "Ageing Initiation and Scanning Team")
                    {
                        ExportToExcel(DT, "WT_BT_Ageing_Initiation_and_Scanning Team");
                        BindClientList();
                    }
                    else if (NM == "Ageing Verification Team")
                    {
                        ExportToExcel(DT, "WT_BT_Ageing_Verification_Team");
                        BindClientList();
                    }
                    else if (NM == "Capgemini MIS")
                    {
                        ExportToExcel(DT, "Capgemini_MIS");
                        BindClientList();
                    }
                    else if (NM == "DataEntryQC")
                    {
                        ExportToExcel(DT, "Ageing_DE_QC");
                        BindClientList();
                    }
                    else if (NM == "Scan")
                    {
                        ExportToExcel(DT, "Ageing_Scanning");
                        BindClientList();
                    }
                    else if (NM == "DataEntry")
                    {
                        ExportToExcel(DT, "Ageing_Data_Entry");
                        BindClientList();
                    }
                    else if (NM == "TMVerification")
                    {
                        ExportToExcel(DT, "Ageing_Verification_Team");
                        BindClientList();
                    }
                    else if (NM == "TMQCVerification")
                    {
                        ExportToExcel(DT, "Ageing_Verification_QC_Team");
                        BindClientList();
                    }
                    else if (NM == "WIPPOOL")
                    {
                        ExportToExcel(DT, "WIPPOOL_MIS");
                        BindClientList();
                    }
                    else if (NM == "FundRequestRaised")
                    {
                        ExportToExcel(DT, "MIS_FundRequestRaised");
                        BindClientList();
                    }
                    else if (NM == "CapegiminiNONGreenReports")
                    {
                        ExportToExcel(DT, "CapegiminiNONGreen");
                        BindClientList();
                    }
                    else
                    {
                        ExportToExcel(DT, "All_MIS");
                        BindClientList();
                    }
                }
                else
                    BindClientList();
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            //return View("MIS_MIS");
            //return View(model);

            return View("~/Views/Verification/MIS_MIS.cshtml");
        }



