        public void ExportToExcelDE_XLSX(
    DataTable dtMIS,
    DataTable dtSummary,
    string fileName)
        {
            using (XLWorkbook workbook = new XLWorkbook())
            {
                workbook.Worksheets.Add(dtMIS, "MIS");
                workbook.Worksheets.Add(dtSummary, "SUMMARY");

                Response.Clear();
                Response.Buffer = true;
                Response.Charset = "";

                Response.ContentType =
                    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
                Response.AddHeader(
                    "Content-Disposition",
                    "attachment; filename=" + fileName + ".xlsx"
                );

                using (MemoryStream ms = new MemoryStream())
                {
                    workbook.SaveAs(ms);
                    ms.Position = 0;
                    ms.WriteTo(Response.OutputStream);
                    Response.Flush();
                    Response.End();
                }
            }
        }



