                NetworkShare.ConnectToShare(@"\\10.83.0.55\Attachment", "itapp.support@walsonsverify.com", "@2Secure!@#321"); //Connect with the new credentials
                fileBytes = System.IO.File.ReadAllBytes(@"\\10.83.0.55\Attachment\RevertMail\" + ImageName);
                return File(fileBytes, System.Net.Mime.MediaTypeNames.Application.Octet, ImageName);






            }

            else if (Designation == "Team Member-Ref-QC" || Designation == "Team Member-Ref" || Designation == "Manager-Edu" || Designation == "Team Leader-Ref" || Designation == "Team Leader-CS" || Designation == "Manager-CS")
            {
                NetworkShare.DisconnectFromShare(@"\\10.80.0.53\Attachment", true); //Disconnect in case we are currently connected with our credentials;
                NetworkShare.ConnectToShare(@"\\10.80.0.53\Attachment", "itapp.support@walsonsverify.com", "@2Secure!@#321"); //Connect with the new credentials

                fileBytes = System.IO.File.ReadAllBytes(@"\\10.80.0.53\Attachment\Mails\" + ImageName);
                return File(fileBytes, System.Net.Mime.MediaTypeNames.Application.Octet, ImageName);

            }
            else
            {
                string ToPath = System.Configuration.ConfigurationManager.AppSettings["mailpath"].ToString();

                if (!System.IO.File.Exists(ToPath + ImageName))
                {
                    // copy file from mail server to application server 
                    ReadRevertdocument(ToPath, "", ImageName);
                }
                if (System.IO.File.Exists(ToPath + ImageName))
                {
                    try
                    {
                        fileBytes = System.IO.File.ReadAllBytes(ToPath + ImageName);
                        string fileName = ImageName;
                    }
                    catch
                    {
                        return null;
                    }
                    ;

                }

            }

            return File(fileBytes, System.Net.Mime.MediaTypeNames.Application.Octet, ImageName);
        }

