                {
                    NetworkShare.DisconnectFromShare(@"\\10.80.0.53\Attachment", true); //Disconnect in case we are currently connected with our credentials;
                    NetworkShare.ConnectToShare(@"\\10.80.0.53\Attachment", "itapp.support@walsonsverify.com", "@2Secure!@#321"); //Connect with the new credentials
                    msgFilePath = $@"\\10.80.0.53\Attachment\Mails\{ImageName}";
                }
                else
                {
                    string ToPath = System.Configuration.ConfigurationManager.AppSettings["mailpath"].ToString();
                    if (!System.IO.File.Exists(ToPath + ImageName))
                    {
                        // copy file from mail server to application server 
                        ReadRevertdocument(ToPath, "", ImageName);
                    }
                    if (System.IO.File.Exists(ToPath + ImageName))
                    {
                        try
                        {
                            msgFilePath = $@"{ToPath + ImageName}";
                        }
                        catch
                        {
                            return null;
                        }
                    }
                }

                var msg = new Storage.Message(msgFilePath);
                var subject = msg.Subject;
                var fromName = msg.Sender.DisplayName;
                var fromEmail = msg.Sender.Email;
                var from = fromName + " <" + fromEmail + "> ";
                var recipients = msg.GetEmailRecipients(RecipientType.To, false, false);
                var date = msg.ReceivedOn;
                var body = msg.BodyHtml;

                if (string.IsNullOrEmpty(body))
                {
                    body = msg.BodyText;
                }

                StringBuilder htmlContent = new StringBuilder();
                htmlContent.Append("<html><head><style>");
                htmlContent.Append("body { font-family: Arial, sans-serif: font-size: 12px; line-height:1.5; }");
                htmlContent.Append("</style></head><body>");

                //Subject
                htmlContent.Append("<h2>").Append(subject).Append("</h2>");

                //From
                htmlContent.Append("<p><strong>From: </strong>").Append(fromName)
                    .Append(" <a href=\"mailto:").Append(fromEmail).Append("\"> ").Append(fromEmail).Append("</a></p>");

                //To
                htmlContent.Append("<p><strong>To: </strong>").Append(recipients).Append("</p>");

                //Date
                htmlContent.Append("<p><strong>Date: </strong>").Append(date).Append("</p>");

                htmlContent.Append(body);
                htmlContent.Append("</body><html>");

                string strHtmlEmail = Path.GetFileNameWithoutExtension(ImageName) + ".html";
                string htmlTempPath = Path.Combine(Path.GetTempPath(), strHtmlEmail);
                System.IO.File.WriteAllText(htmlTempPath, htmlContent.ToString(), Encoding.UTF8);

                //Use wkhtmltopdf.exe to convert HTML to PDF
                string wkHtmlToPdfPath = Server.MapPath("~/App_Data/wkhtmltopdf/wkhtmltopdf.exe");
                string pdfFileName = Path.GetFileNameWithoutExtension(ImageName) + ".pdf";
                string pdfFilePath = Path.Combine(Path.GetTempPath(), pdfFileName);

                //Ensure wkhtmltopdf.exe exists
                if (!System.IO.File.Exists(wkHtmlToPdfPath))
                {
                    return Content("wkhtmltopdf.exe not found.");
                }

                //Start the process to convert HTML to PDF
                ProcessStartInfo startInfo = new ProcessStartInfo
                {
                    FileName = wkHtmlToPdfPath,
                    Arguments = $"\"{htmlTempPath}\" \"{pdfFilePath}\"",
                    CreateNoWindow = true,
                    UseShellExecute = false,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true
                };

                using (Process process = Process.Start(startInfo))
                {
                    process.WaitForExit();
                }

                // upload each file separately into model
                var uploadedFile = new CustomHttpPostedFileBase(pdfFilePath);
                var model = new VerifiedUploadDocViewModel
                {
                    PersonalRowID = personalRowId,
                    SubCheckRowID = subCheckId,
                    DocumentType = "Verification Artifact",
                    Remarks = "Verification Artifact",
                    UploadDoc = uploadedFile
                };

                ActionResult res = UplodEducationVerDocs(model);

                //Return the generated PDF file to the user
                byte[] pdfBytes = System.IO.File.ReadAllBytes(pdfFilePath);
                return File(pdfBytes, "application/pdf", pdfFileName);

            }
            catch (System.Exception ex)
            {
                return new HttpStatusCodeResult(500, "Error converting file: " + ex.Message);
            }
        }
        #endregion

        private void ReadRevertdocument(string localPath, string folderName, string fileName)
        {
            try
            {
                //localPath = @"d:\attachments\";
                //fileName = "test.txt";
                string ftppath = "";
                if (!string.IsNullOrEmpty(ConfigurationManager.AppSettings["ftppathRevertRec"].ToString()))
                {
                    ftppath = ConfigurationManager.AppSettings["ftppathRevertRec"].ToString();
                }
                var config = System.Configuration.ConfigurationManager.AppSettings;
                var Fusername = "";
                var Fpwd = "";
                if (config.Count > 0)
                {
                    Fusername = config["username"];
                    Fpwd = config["pwd"];

                }
                //FtpWebRequest requestFileDownload = (FtpWebRequest)WebRequest.Create("ftp://10.80.0.76/"+ folderName +"/" + fileName);
                FtpWebRequest requestFileDownload = (FtpWebRequest)WebRequest.Create(ftppath + fileName);
                requestFileDownload.Credentials = new NetworkCredential(Fusername, Fpwd);
                requestFileDownload.Method = WebRequestMethods.Ftp.DownloadFile;
                FtpWebResponse responseFileDownload = (FtpWebResponse)requestFileDownload.GetResponse();
                Stream responseStream = responseFileDownload.GetResponseStream();
                FileStream writeStream = new FileStream(localPath + fileName, FileMode.Create);
                int Length = 2048;
                Byte[] buffer = new Byte[Length];
                int bytesRead = responseStream.Read(buffer, 0, Length);
                while (bytesRead > 0)
                {
                    writeStream.Write(buffer, 0, bytesRead);
                    bytesRead = responseStream.Read(buffer, 0, Length);
                }
                responseStream.Close();
                writeStream.Close();
                requestFileDownload = null;
                responseFileDownload = null;
            }
            catch (System.Exception ex)
            {
                //string body = "<div>Exception:" + ex.ToString() + "</div><br></br><div>LocalPath:" + localPath + "</div><br></br><div>fileName:" + fileName + "</div><br></br><div>Exception:" + ex.ToString() + " </div><br></br><div></div><br></br><div></div><br></br>";
                //SendErrorEmail("BGV-Automation Error on Upload Documents", "bgv.helpdesk@securitas-india.com", body, "");
            }


        }

