        public InterimReportGenerateViewModel ConverdReportPDFFileToWordGallaghar(int PersonalRowID, short ClientRowID)
        {
            InterimReportGenerateViewModel model = new InterimReportGenerateViewModel();
            try
            {
                string ReportToPDF = "Export to PDF";

                if (ReportToPDF == "Export to PDF")
                {
                    model = repoReportQC.GetInterimReportPersonalInfo(PersonalRowID);
                    model.Report_Type = "Final";
                    model.ClientRowID = ClientRowID;
                    var root = Server.MapPath("~/ExportPDF/");
                    string FldPathDoc = ConfigurationManager.AppSettings["CandidateReportdoc".Trim().ToLower()].ToString();

                    var pdfname = string.Format("{0}.pdf", model.CompanyRefNo.ToString() + "_" + "Interim" + "_" + Guid.NewGuid().ToString("N").Substring(0, 4));
                    var path = System.IO.Path.Combine(root, pdfname);
                    model.LastName = pdfname;
                    string Path2 = Server.MapPath(FldPathDoc + pdfname);
                    var cookies = Request.Cookies.AllKeys.ToDictionary(k => k, k => Request.Cookies[k].Value);


                    var pdfResult = new Rotativa.ActionAsPdf("ReportMainGallaghar", model)
                    {
                        FormsAuthenticationCookieName = FormsAuthentication.FormsCookieName,
                        Cookies = cookies,
                        FileName = model.PersonalRowID + "_Report" + ".pdf",
                        PageOrientation = Rotativa.Options.Orientation.Portrait,
                        PageSize = Rotativa.Options.Size.A4,
                        PageMargins = new Rotativa.Options.Margins(0, 0, 0, 0),
                        CustomSwitches = "--custom-header \"X-Bypass-Auth\" \"QqI0bBY1DvUS4DKa9Vh2Fy5WtdBihEKp6rOMFz93xqkK1e2ZGg83fu7hjxztXo5x\""


                    };


                    //if (!System.IO.File.Exists(path))
                    //{
                    var byteArray = pdfResult.BuildFile(this.ControllerContext);
                    var fileStream = new FileStream(path, FileMode.Create, FileAccess.Write);
                    fileStream.Write(byteArray, 0, byteArray.Length);
                    fileStream.Close();
                    var fileStream1 = new FileStream(Path2, FileMode.Create, FileAccess.Write);
                    fileStream1.Write(byteArray, 0, byteArray.Length);
                    fileStream1.Close();
                    // }



                }

            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                if (ClientRowID == 249)
                {
                    clsSendMail mail;
                    mail = new clsSendMail();
                    var signature = mail.GetCompanyMailSignature();
                    string From = signature.GeneralEmail;
                    //mail.SendMail("API Error Sutherland", From, "bgv.helpdesk@securitas-india.com,raushan.singh@securitas-india.com", "Sutherland Report" + PersonalRowID.ToString() + "  " + ClientRowID, PersonalRowID.ToString() + "  " + ClientRowID);
                }
            }
            //return View();
            return model;
        }

