        [SessionExpireFilterAttribute]
        public ActionResult ReAllocationTeamLeaderToTeamMemberEducation(int page = 1, string sort = "", string sortDir = "desc", string Search = "", string VerificationIds = "", short AllocateTM = 0, short AllocateTMQC = 0, short ClientRowID = 0, string OCVerIDs = "", string CheckStatus = "", short SearchMemberRowID = 0)
        {
            VerificationInfoListPagedModel model = new VerificationInfoListPagedModel();
            try
            {
                BindStates();
                int pageSize = 10000;
                int pageSize1 = 10000;
                short teamMemerRowId = Convert.ToInt16(Session["TeamMemberRowID"]);
                string Designation = Session["Designation"].ToString();
                string department = Session["department"].ToString();

                string statusid = "";

                //BindClientList();
                BindClientListBaseOnLogin(teamMemerRowId);
                GetTMMemberForAllocate();
                GetTMQCMemberForAllocate();
                string ReAllocation = "ReAllocation";
                byte UnAllocatedCount = 0;

                if (Designation == "Team Leader-Edu" || Designation == "Manager-Edu")
                {
                    if (!string.IsNullOrEmpty(VerificationIds) && (AllocateTM > 0 || AllocateTMQC > 0))
                    {
                        int[] verIDs = VerificationIds.Split(',').Select(str => int.Parse(str)).ToArray();
                        PQUpdateEducationTeamLeaderViewModel eduModel = new PQUpdateEducationTeamLeaderViewModel();
                        eduModel.ModifiedBy = teamMemerRowId;
                        eduModel.ModifiedDate = DateTime.Now;
                        eduModel.CheckStatus = "Allocated-TM";
                        eduModel.TMAllocatedTo = AllocateTM;
                        eduModel.TMAllocatedDate = DateTime.Now;
                        eduModel.TMQCAllocatedTo = AllocateTMQC;
                        eduModel.TMQCAllocatedDate = DateTime.Now;
                        foreach (var item in verIDs)
                        {
                            eduModel.EducationRowID = item;
                            DataTable dtcheck = cc.GetCheckDetails(item);
                            DataTable dtcheck1 = cc.GetSubCheckFamilyForUpdateById(Convert.ToInt16(dtcheck.Rows[0]["SubCheckFamilyID"]));
                            var Teammember = dtcheck.Rows[0]["TMAllocatedTo"].ToString();
                            if (eduModel.TMAllocatedTo != 0)
                            {
                                if (Teammember == "684" || Teammember == "787" || Teammember == "873" || Teammember == "888" || Teammember == "999" || Teammember == "1003" || Teammember == "1004" || Teammember == "1010" || Teammember == "1011" || Teammember == "1015" || Teammember == "1180" || Teammember == "1080")
                                {
                                    StopVendor((short)Convert.ToInt32(dtcheck.Rows[0]["SubCheckFamilyID"]), Convert.ToInt32(dtcheck.Rows[0]["personalrowid"]), Convert.ToInt32(dtcheck.Rows[0]["CheckStatusID"]), dtcheck1.Rows[0]["CheckFamilyRowID"].ToString());
                                }
                                cc.OperationAllocation(eduModel.EducationRowID, eduModel.TMAllocatedTo, "OPTM");


                            }
                            if (eduModel.TMQCAllocatedTo != 0)
                            {
                                cc.OperationAllocation(eduModel.EducationRowID, eduModel.TMQCAllocatedTo, "OPQC");
                                // StopVendor((short)Convert.ToInt32(dtcheck.Rows[0]["SubCheckFamilyID"]), Convert.ToInt32(dtcheck.Rows[0]["personalrowid"]), Convert.ToInt32(dtcheck.Rows[0]["CheckStatusID"]), dtcheck1.Rows[0]["CheckFamilyRowID"].ToString());
                            }
                            #region Save LogTransaction Details
                            clsCommonMethods.AddPQLogTrasaction(Convert.ToInt32(dtcheck.Rows[0]["personalrowid"]), "TeamLeaderAllocationToTeamMember", eduModel.CheckStatus, dtcheck.Rows[0]["CheckUniqueID"].ToString(), "Update");
                            #endregion

                            #region Case/Check Action History Save 
                            clsCommonMethods.AddCheckActionHistory(Convert.ToInt32(dtcheck.Rows[0]["personalrowid"]), Convert.ToInt16(dtcheck.Rows[0]["SubCheckFamilyID"]), eduModel.CheckStatus, "");
                            #endregion

                        }
                    }
                    model = repoVerificationInfo.CheckDetailsForReAllocation(page, pageSize, Search, department, CheckStatus, SearchMemberRowID);


                }
                if (UnAllocatedCount > 0)
                {
                    ViewBag.ErrorMsg = UnAllocatedCount.ToString() + " Check(s) not allocated because teammember/teammemberQC not mapped with client!";
                }

                if (model == null)
                {
                    ViewBag.ErrorMsg = "No item found!";
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View(model);
