        private void TitanCRC_StatusAPI(string ClientRefId, string CompanyRefNo, string ColorCode, string reportType, string status, string ReportName = "", string ReportPath = "", string InitiatedDate = "", string CompletionDate = "", string VendorComments = "", string VendorSLA = "", string PersonalRowId = "0")
        {
            string apiResponse = "";
            try
            {
                string strUrl = "https://apipreprod1.zwayam.com/bgv/v1/candidate/" + ClientRefId + "/bgv_status";
                HttpWebRequest httpWebRequest = (HttpWebRequest)WebRequest.Create(strUrl.Trim());
                httpWebRequest.Method = "PUT";
                httpWebRequest.ContentType = "application/json";
                httpWebRequest.Headers.Add("api_key", "4c7jbn_710768b0803c59e65f85816a3e60891cbfaba8f829013b68a5a7bb57524bca375a9976db11c8be0108901f20bb187978c876241a352232f28f8578846d8e0106");
                string json = "";
                using (var streamWriter = new
                StreamWriter(httpWebRequest.GetRequestStream()))
                {
                    json = new JavaScriptSerializer().Serialize(new
                    {
                        vendorId = "SECURITAS",
                        verificationReferenceId = PersonalRowId,
                        status = status,
                        reportUrl = ReportPath,
                        reportFileName = ReportName,
                        message = VendorComments
                    });
                    streamWriter.Write(json);
                }
                var httpResponse = (HttpWebResponse)httpWebRequest.GetResponse();
                apiResponse = httpResponse.StatusCode.ToString();
                if (apiResponse == "OK")
                {
                    new API().InsertAPI_AuditDetail(ClientRefId, 69, "Success", "TitanCRC Report", "CompanyRefNo:" + CompanyRefNo + ",ColorCode:" + ColorCode + ",Status:" + status + ",ReportName:" + ReportName, ReportPath, "API");
                }
                else
                {
                    new API().InsertAPI_AuditDetail(ClientRefId, 69, "Failed", "TitanCRC Report", "CompanyRefNo:" + CompanyRefNo + ",ColorCode:" + ColorCode + ",Status:" + status + ",ReportName:" + ReportName, ReportPath, "API");
                }
            }
            catch (Exception ex)
            {
                new API().InsertAPI_AuditDetail(ClientRefId, 69, "Failed", "Status:" + status, "ReportType:" + reportType, "Exception:" + ex.Message, "API");
            }



        }

