        public string RenderViewToString(ControllerContext context, string viewPath, int personalRowid, bool partial = false)
        {
            ReportViewModel model = new ReportViewModel();
            model = GenerateReport(personalRowid);



            // first find the ViewEngine for this view
            ViewEngineResult viewEngineResult = null;
            if (partial)
                viewEngineResult = ViewEngines.Engines.FindPartialView(context, viewPath);
            else
                viewEngineResult = ViewEngines.Engines.FindView(context, viewPath, null);

            if (viewEngineResult == null)
                throw new FileNotFoundException("View cannot be found.");

            // get the view and attach the model to view data
            var view = viewEngineResult.View;
            context.Controller.ViewData.Model = model;

            string result = null;

            using (var sw = new StringWriter())
            {
                var ctx = new ViewContext(context, view, context.Controller.ViewData, context.Controller.TempData, sw);
                view.Render(ctx, sw);
                result = sw.ToString();
            }

            return result;
        }
        [HttpGet]
        public ActionResult DigitalVerification()
        {

            return View("");

        }
        [HttpPost]
        [ValidateAntiForgeryToken]
        public ActionResult DigitalVerification(FormCollection frm, string VerStatus, HttpPostedFileBase DigitalVer)
        {
            var Timestamp = new DateTimeOffset(DateTime.UtcNow).ToUnixTimeSeconds().ToString();
            string path = ConfigurationManager.AppSettings["DigitalVerificationPath"].ToString();
            string ext = Path.GetExtension(DigitalVer.FileName).ToLower();
            string filename = VerStatus + "_" + Timestamp + ext;
            string filePath = path + filename;
            DigitalVer.SaveAs(filePath);
            var count = DigitalVerificationExcelDataSend(filePath, ext, "Yes", VerStatus);
            ViewBag.SuccessMsg = "Successfully Send " + Convert.ToString(count) + " SMS !";
            return View("");
