        private int DigitalVerification2ExcelDataSend(string FilePath, string Extension, string isHDR, string VerStatus) //isHDR - means Include header Yes or No
        {
            int Count = 0;
            ClientCustomize cc = new ClientCustomize();
            try
            {
                string conStr = "";
                switch (Extension)
                {
                    case ".xls": //Excel 97-03
                        conStr = ConfigurationManager.ConnectionStrings["Excel03ConString"].ConnectionString;
                        break;
                    case ".xlsx": //Excel 07
                        conStr = ConfigurationManager.ConnectionStrings["Excel07ConString"].ConnectionString;
                        break;
                }
                conStr = String.Format(conStr, FilePath, isHDR);
                OleDbConnection connExcel = new OleDbConnection(conStr);
                OleDbCommand cmdExcel = new OleDbCommand();
                OleDbDataAdapter oda = new OleDbDataAdapter();
                DataTable dt = new DataTable();

                cmdExcel.Connection = connExcel;

                //Get the name of First Sheet
                connExcel.Open();
                DataTable dtExcelSchema;
                dtExcelSchema = connExcel.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, null);
                string SheetName = dtExcelSchema.Rows[0]["TABLE_NAME"].ToString();
                connExcel.Close();

                //Read Data from First Sheet
                connExcel.Open();
                cmdExcel.CommandText = "SELECT * From [" + SheetName + "]";
                oda.SelectCommand = cmdExcel;
                oda.Fill(dt);
                connExcel.Close();


                if (dt.Rows.Count > 0)
                {
                    string CompanyRefNo = string.Empty;
                    string MobileNo = string.Empty;
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        MessageStatus objMessage = new MessageStatus();
                        WhatsAppAPI objs = new WhatsAppAPI();
                        if (VerStatus == "3")
                        {
                            MobileNo = dt.Rows[i]["MobileNo"].ToString().Trim();
                            var Name = dt.Rows[i]["Name"].ToString().Trim();
                            //var urllink = dt.Rows[i]["URL"].ToString().Trim();
                            var ContactNo = dt.Rows[i]["For_any_queries_call"].ToString().Trim();
                            var emnailId = dt.Rows[i]["EmailId"].ToString().Trim();

                            if (!string.IsNullOrWhiteSpace(MobileNo) || !string.IsNullOrWhiteSpace(emnailId))
                            {
                                var a = CallSmartPingApi(MobileNo, Name, ContactNo);
                                ClientCustomize cccc = new ClientCustomize();
                                cccc.InsertCommunicationLog(Name, MobileNo, emnailId, "SmartPing", "Initiated", "Calling SmartPing API");


                                Thread.Sleep(1000);

                                // Only send email if email ID is present
                                if (!string.IsNullOrWhiteSpace(emnailId))
                                {
                                    sendemailmessage(emnailId, Name, ContactNo);
                                    cccc.InsertCommunicationLog(Name, MobileNo, emnailId, "Email", "Initiated", "Sending email to user");
                                }
                                else
                                {
                                    cccc.InsertCommunicationLog(Name, MobileNo, emnailId, "Email", "Skipped", "Email ID missing, skipping email send.");
                                }

                                Thread.Sleep(1000);

                                // Send SMS if MobileNo is present (optional guard)
                                if (!string.IsNullOrWhiteSpace(MobileNo))
                                {
                                    SmsSentAPI(MobileNo, "Hi Applicant, as a part of BGV process, a verifier will visit for your address verification. Please don't pay any money or send any WhatsApp to him. If asked, please connect on 9643318245,9870196693. Appreciate your support. WALSONS");

                                    cccc.InsertCommunicationLog(Name, MobileNo, emnailId, "SMS", "Initiated", "Sending SMS to user");
                                }
                                else
                                {
                                    cccc.InsertCommunicationLog(Name, MobileNo, emnailId, "SMS", "Skipped", "Mobile number missing, skipping SMS.");
                                }

                                Thread.Sleep(1000);
                                Count++;
                            }




                        }


                    }


                }
                else
                {
                    ViewBag.ErrorMsg = "No candidate found!";
                }
            }
            catch (Exception ex)
            {

                ClientCustomize cccc = new ClientCustomize();

                cccc.InsertCommunicationLog(null, null, null, null, "Failed", "Exception occurred: " + ex.Message);

                throw;
            }

            return Count;
        }

