        private int DigitalVerificationExcelDataSend(string FilePath, string Extension, string isHDR, string VerStatus) //isHDR - means Include header Yes or No
        {
            int Count = 0;
            ClientCustomize cc = new ClientCustomize();
            try
            {
                string conStr = "";
                switch (Extension)
                {
                    case ".xls": //Excel 97-03
                        conStr = ConfigurationManager.ConnectionStrings["Excel03ConString"].ConnectionString;
                        break;
                    case ".xlsx": //Excel 07
                        conStr = ConfigurationManager.ConnectionStrings["Excel07ConString"].ConnectionString;
                        break;
                }
                conStr = String.Format(conStr, FilePath, isHDR);
                OleDbConnection connExcel = new OleDbConnection(conStr);
                OleDbCommand cmdExcel = new OleDbCommand();
                OleDbDataAdapter oda = new OleDbDataAdapter();
                DataTable dt = new DataTable();

                cmdExcel.Connection = connExcel;

                //Get the name of First Sheet
                connExcel.Open();
                DataTable dtExcelSchema;
                dtExcelSchema = connExcel.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, null);
                string SheetName = dtExcelSchema.Rows[0]["TABLE_NAME"].ToString();
                connExcel.Close();

                //Read Data from First Sheet
                connExcel.Open();
                cmdExcel.CommandText = "SELECT * From [" + SheetName + "]";
                oda.SelectCommand = cmdExcel;
                oda.Fill(dt);
                connExcel.Close();


                if (dt.Rows.Count > 0)
                {
                    string CompanyRefNo = string.Empty;
                    string MobileNo = string.Empty;
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        MessageStatus objMessage = new MessageStatus();
                        WhatsAppAPI objs = new WhatsAppAPI();
                        if (VerStatus == "3")
                        {
                            MobileNo = dt.Rows[i]["MobileNo"].ToString().Trim();
                            var Name = dt.Rows[i]["Name"].ToString().Trim();
                            var urllink = dt.Rows[i]["URL"].ToString().Trim();
                            var ContactNo = dt.Rows[i]["For_any_queries_call"].ToString().Trim();
                            if (MobileNo != "")
                            {

                                objMessage = objs.SendWhatsAppMessage("+91" + MobileNo, "post_message_digital_with_link", Name, "media_template", urllink, ContactNo);
                                cc.sp_AddAuditWhatsAppAPI(0, objMessage.message, objMessage.status, "Post Message Digital with Link", MobileNo);
                                Count++;
                            }
                        }
                        else
                        {
                            CompanyRefNo = dt.Rows[i]["CompanyRefNo"].ToString().Trim();
                            var CandidateDT = cc.getDigitalVerificationCandidateDetails(CompanyRefNo);
                            if (CandidateDT.Rows.Count > 0)
                            {
                                string CandidateName = CandidateDT.Rows[0]["CandidateFullName"].ToString().Trim();
                                string CandidateMobileNo = CandidateDT.Rows[0]["MobileNo"].ToString().Trim();
                                if (CandidateMobileNo != "" && CandidateMobileNo.Length == 10)
                                {
                                    if (VerStatus == "1")
                                    {
                                        objMessage = objs.SendWhatsAppMessage("+91" + CandidateMobileNo, "pre_message_digital", CandidateName, "media_template", "", "");
                                        cc.sp_AddAuditWhatsAppAPI(Convert.ToInt32(CandidateDT.Rows[0]["PersonalRowID"]), objMessage.message, objMessage.status, "Pre-message-Digital");
                                        Count++;
                                    }
                                    else if (VerStatus == "2")
                                    {
                                        objMessage = objs.SendWhatsAppMessage("+91" + CandidateMobileNo, "digital_to_physical_mode", CandidateName, "media_template", "", "");
                                        cc.sp_AddAuditWhatsAppAPI(Convert.ToInt32(CandidateDT.Rows[0]["PersonalRowID"]), objMessage.message, objMessage.status, "Digital to physical mode");
                                        Count++;
                                    }
                                }

                            }
                        }

                    }


                }
                else
                {
                    ViewBag.ErrorMsg = "No candidate found!";
                }
            }
            catch (Exception ex)
            {
                throw;
            }

            return Count;
        }

