        [HttpPost]
        [ValidateAntiForgeryToken]
        public ActionResult GetBulkUAN(FormCollection frm, HttpPostedFileBase DigitalVer)
        {
            List<InstantCheckResultStatus> UANNoNotExistLst = new List<InstantCheckResultStatus>();
            try
            {
                var Timestamp = new DateTimeOffset(DateTime.UtcNow).ToUnixTimeSeconds().ToString();
                string path = ConfigurationManager.AppSettings["provideddocuments"].ToString();
                string ext = Path.GetExtension(DigitalVer.FileName).ToLower();
                string filename = "UAN_" + Timestamp + ext;
                string filePath = path + filename;
                filePath = Server.MapPath(path + filename);
                DigitalVer.SaveAs(filePath);
                var UANLst = BulkUANCheckMoveWithArtifactFromExcel(filePath, ext, "Yes", "UAN2");
                UANNoNotExistLst = UANLst;
                ClientCustomize cc = new ClientCustomize();
                ViewBag.PersonalDocDetails = UANLst;
                //ExportToExcel(UANLst, "BulkUANFindDetails");               
                ViewBag.ErrorMsg = Convert.ToString(UANLst.Count) + " UAN Number Process !";

            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return RedirectToAction("GetBulkUAN", new { errorMsg = Ex.Message });
            }

            return View(UANNoNotExistLst);
        }



