        private List<InstantCheckResultStatus> BulkUANCheckMoveWithArtifactFromExcel(string FilePath, string Extension, string isHDR, string instantCheckName)
        {
            int Count = 0;
            ClientCustomize cc = new ClientCustomize();
            List<InstantCheckResultStatus> UANNoNotExistLst = new List<InstantCheckResultStatus>();

            try
            {
                string conStr = "";
                switch (Extension)
                {
                    case ".xls": //Excel 97-03
                        conStr = ConfigurationManager.ConnectionStrings["Excel03ConString"].ConnectionString;
                        break;
                    case ".xlsx": //Excel 07
                        conStr = ConfigurationManager.ConnectionStrings["Excel07ConString"].ConnectionString;
                        break;
                }
                conStr = String.Format(conStr, FilePath, isHDR);
                OleDbConnection connExcel = new OleDbConnection(conStr);
                OleDbCommand cmdExcel = new OleDbCommand();
                OleDbDataAdapter oda = new OleDbDataAdapter();
                DataTable dt = new DataTable();

                cmdExcel.Connection = connExcel;

                //Get the name of First Sheet
                connExcel.Open();
                DataTable dtExcelSchema;
                dtExcelSchema = connExcel.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, null);
                string SheetName = dtExcelSchema.Rows[0]["TABLE_NAME"].ToString();
                connExcel.Close();

                //Read Data from First Sheet
                connExcel.Open();
                cmdExcel.CommandText = "SELECT * From [" + SheetName + "]";
                oda.SelectCommand = cmdExcel;
                oda.Fill(dt);
                connExcel.Close();
                // var dt = cc._walsonsUAN15_06();

                if (dt.Rows.Count > 0)
                {

                    string MobileNo = string.Empty;
                    string DocName = string.Empty;
                    string PRowId = string.Empty;
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        InstantCheckResultStatus NotExistUAN = new InstantCheckResultStatus();
                        AddUANCheckDetailsByAPI AddApiObj = new AddUANCheckDetailsByAPI();
                        string companyRefNo = "";
                        var UANNO = dt.Rows[i]["UANNO"].ToString().Trim();
                        companyRefNo = Convert.ToString(dt.Rows[i]["CompanyRefNo"]);

                        var dbPersonal = cc.GetpersonaldatafromCompanyRefNo(companyRefNo);
                        string PersonalRowId = "";
                        if (dbPersonal.Rows.Count > 0)
                        {
                            PersonalRowId = dbPersonal.Rows[0]["PersonalRowId"].ToString();
                        }
                        InstantCheckRepository InstantcheckObj = new InstantCheckRepository();

                        var DBCheck = cc.GetUANCheck(Convert.ToInt32(PersonalRowId), 430);
                        if (DBCheck.Rows.Count > 0)
                        {
                            var tbldb = cc.Sp_SprintVerifyGetUan(UANNO, companyRefNo);
                            int ClientRowId = Convert.ToInt32(DBCheck.Rows[0]["ClientRowID"]);
                            string data = "";
                            bool UANExists = false;
                            if (tbldb.Rows.Count > 0)
                            {
                                UANExists = true;
                                Count++;
                            }
                            else
                            {
                                var DataObj = InstantcheckObj.GetEPFO_without_otpLive(UANNO);
                                if (DataObj.statuscode == 200)
                                {
                                    var result = cc.InsertintoSprintVerifyEPFO_history(DataObj, PersonalRowId.ToString(), UANNO, 0);
                                    if (result != "")
                                    {
                                        Count++;
                                        string body = string.Empty;
                                        UANExists = true;
                                        tbldb = cc.GetSprintVerify_epfoReport(Convert.ToInt32(result));
                                    }
                                    else
                                    {
                                        NotExistUAN.PersonalRowID = PersonalRowId;
                                        NotExistUAN.CompanyRefNo = companyRefNo;
                                        NotExistUAN.FileName = "";
                                        NotExistUAN.UAN = UANNO;
                                        NotExistUAN.Action = "false";
                                        UANNoNotExistLst.Add(NotExistUAN);
                                    }
                                }
                                else
                                {
                                    NotExistUAN.PersonalRowID = PersonalRowId;
                                    NotExistUAN.CompanyRefNo = companyRefNo;
                                    NotExistUAN.FileName = "";
                                    NotExistUAN.UAN = UANNO;
                                    NotExistUAN.Action = "false";
                                    UANNoNotExistLst.Add(NotExistUAN);
                                }
                            }
                            if (UANExists == true)
                            {
                                string body = string.Empty;
                                using (StreamReader reader = new StreamReader(Server.MapPath("~/Emailers/UANCheck.html")))
                                {
                                    body = reader.ReadToEnd();
                                }
                                string name = "";
                                string guardian_name = "";
                                string uanNumberId = "";

                                for (int j = 0; j < tbldb.Rows.Count; j++)
                                {
                                    string date_of_joining = "";
                                    string date_of_exit = "";
                                    if (j == 0)
                                    {
                                        companyRefNo = Convert.ToString(tbldb.Rows[j]["companyRefNo"]);
                                        name = Convert.ToString(tbldb.Rows[j]["name"]);
                                        guardian_name = Convert.ToString(tbldb.Rows[j]["guardian_name"]);
                                        uanNumberId = Convert.ToString(tbldb.Rows[j]["UANNO"]);
                                    }
                                    if (Convert.ToString(tbldb.Rows[j]["date_of_joining"]) != "")
                                    {
                                        DateTime doj = Convert.ToDateTime(tbldb.Rows[j]["date_of_joining"]);
                                        date_of_joining = doj.ToString("dd-MMM-yyyy");
                                    }
                                    if (Convert.ToString(tbldb.Rows[j]["date_of_exit"]) != "")
                                    {
                                        DateTime doe = Convert.ToDateTime(tbldb.Rows[j]["date_of_exit"]);
                                        date_of_exit = doe.ToString("dd-MMM-yyyy");
                                    }
                                    data += "<tr>";
                                    data += "<td> " + Convert.ToString(tbldb.Rows[j]["establishment_name"]) + " (" + Convert.ToString(tbldb.Rows[j]["member_id"]) + ")" + " </td>";
                                    data += "<td> " + date_of_joining + " </td>";
                                    data += "<td> " + date_of_exit + " </td>";
                                    data += "</tr>";

                                }
                                body = body.Replace("{companyRefNo}", companyRefNo);
                                body = body.Replace("{name}", name);
                                body = body.Replace("{guardian_name}", guardian_name);
                                body = body.Replace("{uanNumberId}", uanNumberId);
                                body = body.Replace("{EstablishedDetails}", data);
                                body = body.Replace("{verifiedDate}", DateTime.Now.Date.ToString("dd-MMM-yyyy"));

                                // SavePQVerifiedUploadCaseUANDoc(Convert.ToInt32(PersonalRowId), "Verified", "UAN Case Report", "provideddocuments", body, "UAN No Verified", false, companyRefNo);
                                string FileName = SavePQVerifiedUploadUANDoc(Convert.ToInt32(PersonalRowId), 430, "Verified", "UAN Report", "provideddocuments", body, "UAN No Verified", 0, companyRefNo);


                                var Antecedentsdt = cc.Antecedents_client_select_form(ClientRowId, 430, "Operation", "Check");
                                if (Antecedentsdt.Rows.Count > 0)
                                {
                                    for (int K = 0; K < Antecedentsdt.Rows.Count; K++)
                                    {
                                        int Antecedents = Convert.ToInt32(Antecedentsdt.Rows[K]["AntecedentsRowID"]);
                                        int rst = cc.insertUpdateEMP_UANCheck(Convert.ToInt32(PersonalRowId), 430, Antecedents, ClientRowId, UANNO, name, guardian_name);

                                    }
                                }

                                cc.UpdateCheckStatus(Convert.ToInt32(PersonalRowId), 430, 1, 37, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                                cc.UpdateTmMemberID(Convert.ToInt32(PersonalRowId), 430);
                                clsCommonMethods.AddCheckActionHistory(Convert.ToInt32(PersonalRowId), 430, "Completed", "Verification recieve throught integration");

                                PRowId = PRowId + "," + PersonalRowId;

                                NotExistUAN.PersonalRowID = PersonalRowId;
                                NotExistUAN.FileName = FileName;
                                NotExistUAN.CompanyRefNo = companyRefNo;
                                NotExistUAN.UAN = UANNO;
                                NotExistUAN.Action = "true";
                                UANNoNotExistLst.Add(NotExistUAN);
                            }
                        }
                        else
                        {
                            NotExistUAN.PersonalRowID = PersonalRowId;
                            NotExistUAN.CompanyRefNo = companyRefNo;
                            NotExistUAN.FileName = "";
                            NotExistUAN.UAN = UANNO;
                            NotExistUAN.Action = "false";
                            UANNoNotExistLst.Add(NotExistUAN);
                        }
                    }
                }
                else
                {
                    ViewBag.ErrorMsg = "UAN Number found!";
                }

            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return UANNoNotExistLst;
            }
            return UANNoNotExistLst;

        }


