        public bool AddllmtechPanArtifact(int PersonalRowId, int SubCheckRowId, int clientRowid, string RefNo, string PanNo)
        {
            bool status = false;
            try
            {
                ClientCustomize CC = new ClientCustomize();
                AddUANCheckDetailsByAPI APiobj = new AddUANCheckDetailsByAPI();
                string logPath = Server.MapPath("~\\APILogs\\Logfiles");
                var model = APiobj.GetLlmtechPAN(PersonalRowId, SubCheckRowId, PanNo, RefNo, logPath);
                if (model.success)
                {
                    var dt = CC.Antecedents_client_select_form(clientRowid, SubCheckRowId, "Operation", "Check");
                    if (dt.Rows.Count > 0)
                    {
                        for (int i = 0; i < dt.Rows.Count; i++)
                        {
                            int Antecedents = Convert.ToInt32(dt.Rows[i]["AntecedentsRowID"]);
                            int rst = CC.InsertUpdatePanNumberCheckDetails(PersonalRowId, SubCheckRowId, Antecedents, clientRowid, PanNo, model.data.fullname, Convert.ToDateTime(model.data.date_of_birth).ToString("dd-MM-yyyy"));
                        }
                    }
                    string body = string.Empty;
                    using (StreamReader reader = new StreamReader(Server.MapPath("~/Emailers/llmTechPAN.html")))
                    {
                        body = reader.ReadToEnd();
                    }
                    string CandidateName = "";
                    string ProvidedDOB = "";
                    if (Convert.ToString(model.data.fullname) != "")
                    {
                        body = body.Replace("{CompanyRefNo}", RefNo);
                        body = body.Replace("{Name}", model.data.fullname);
                        body = body.Replace("{PAN_Number}", PanNo);
                        body = body.Replace("{PAN_DOB}", Convert.ToDateTime(model.data.date_of_birth).ToString("dd-MMM-yyyy"));
                        body = body.Replace("{Gender}", Convert.ToString(model.data.gender));
                        body = body.Replace("{PAN_Type}", Convert.ToString(model.data.pan_type));
                        body = body.Replace("{Calculated_Age}", Convert.ToString(model.data.calculated_age));
                        body = body.Replace("{VerifiedDate}", DateTime.Now.Date.ToString("dd-MMM-yyyy"));

                        SavePQVerifiedUploadUANDoc(PersonalRowId, Convert.ToInt16(SubCheckRowId), "Verified", "Verification Artifact", "provideddocuments", body, "PAN Verified", 0, RefNo);
                        status = true;
                        var idtblDT = cc.getNationalCheckFromDataEntry(PersonalRowId, SubCheckRowId);
                        if (idtblDT.Rows.Count > 0)
                        {
                            ProvidedDOB = Convert.ToString(idtblDT.Rows[0]["DOB"]);
                            CandidateName = Convert.ToString(idtblDT.Rows[0]["CandidateName"]);
                        }
                        if (ValidateCandidateName(CandidateName, model.data.fullname) && ValidateCandidateDOB(ProvidedDOB, Convert.ToString(model.data.date_of_birth)))
                        {
                            var rst = cc.UpdateCandidateChecksReportComments(PersonalRowId, Convert.ToInt16(SubCheckRowId));
                            cc.UpdateCheckStatus(PersonalRowId, SubCheckRowId, 1, 36, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                            new API().UpdateAPICheckStatus(clientRowid.ToString().Trim(), PersonalRowId, SubCheckRowId, "CompletedbyOpsQC");  //APICheckStatus

                            if (clientRowid == 69)
                            {
                                DataTable dtCount = cc.GetTitanCompleteCheckListCount(PersonalRowId);
                                if (dtCount.Rows.Count > 0)
                                {
                                    if (dtCount.Rows[0]["compChecks"].ToString() == "4")
                                    {
                                        DataTable dts = cc.CheckOpenInterimRequest(PersonalRowId);
                                        if (dts.Rows.Count == 0)
                                        {
                                            cc.Insert_InterimRequestForLTI(PersonalRowId, Convert.ToInt16(Session["TeamMemberRowID"]));
                                        }
                                    }
                                }
                            }
                            if (clientRowid == 735)
                            {
                                cc.UpdatePQCandidateChecksColorCode(654, 6, "No Risk", PersonalRowId, SubCheckRowId, "Exact Match Found");
                            }
                            else
                            {
                                cc.UpdatePQCandidateChecksColorCode(654, 6, "Green", PersonalRowId, SubCheckRowId, "Exact Match Found");
                            }
                        }
                        else
                        {
                            cc.UpdateCheckStatus(PersonalRowId, SubCheckRowId, 1, 107, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                        }
                        cc.UpdateTmMemberID(PersonalRowId, SubCheckRowId, "LlmTech");
                        clsCommonMethods.AddCheckActionHistory(PersonalRowId, Convert.ToInt16(SubCheckRowId), "Completed", "Verification recieve throught API");
                    }
                }

            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return status;
        }


        public void SavePQVerifiedUploadCaseUANDoc(int PersonalRowID = 0, string DocumentUploadFrom = "", string DocumentType = "", string FolderNameForSave = "", string UploadDoc = "", string remarks = "", bool NADoc = false, string secRefId = "")
        {
            try
            {

                AddPQVerifiedUploadCaseDocViewModel DocModel = new AddPQVerifiedUploadCaseDocViewModel();
                DocModel.PersonalRowID = PersonalRowID;
                DocModel.DocumentUploadFrom = DocumentUploadFrom; //  Provided / Verified
                DocModel.DocumentType = DocumentType; //Name of the selected docs
                if (!NADoc)
                {
                    string FileName = (secRefId + " " + DocumentType).Replace(" ", "_").Replace("-", "_");
                    if (FileName.Contains("24/7CPL_"))
                    {
                        FileName = FileName.Replace("/", "-");
                    }
                    string FldPathDoc = string.Empty;
                    FldPathDoc = ConfigurationManager.AppSettings[FolderNameForSave.Trim().ToLower()].ToString();

                    string existFile = repoPQVerifiedUploadCaseDoc.ExistFileByPersonalIdAndDocType(PersonalRowID, DocumentType);
                    if (!string.IsNullOrEmpty(existFile))
                    {
                        string path = Server.MapPath(FldPathDoc + existFile);
                        FileInfo file = new FileInfo(path);
                        if (file.Exists)//check file exsit or not
                        {
                            file.Delete();
                        }
                    }

                    string proImg = string.Empty;
                    proImg = FileName + ".pdf";


                    string IronKey = System.Configuration.ConfigurationManager.AppSettings["IronKey"].ToString();
                    var Renderer = new IronPdf.ChromePdfRenderer();
                    IronPdf.License.LicenseKey = IronKey;
                    var pdf = Renderer.RenderHtmlAsPdf(UploadDoc);

                    pdf.SaveAs(Server.MapPath(FldPathDoc + proImg)); // Saves our PdfDocument object as a PDF

                    DocModel.FileName = Path.GetFileName(proImg);
                    DocModel.FilePath = FldPathDoc;
                }
                else
                {
                    DocModel.FileName = "NA";
                    DocModel.FilePath = "NA";
                }
                DocModel.UploadDate = DateTime.Now;
                DocModel.Status = 1;
                DocModel.Remarks = remarks;
                repoPQVerifiedUploadCaseDoc.AddPQVerifiedUploadCaseDoc(DocModel);
                repoPQVerifiedUploadCaseDoc.SaveChanges();
            }
            catch (Exception ex)
            {
                string str = ex.Message;
                throw;
            }
        }

