                                    {
                                        if (d[4].ToString() == "textbox")
                                        {
                                            marksModel1.Add(d[1].ToString(), rowsFiltered[0][1]);
                                        }
                                        else if (d[4].ToString() == "dropdown")
                                        {
                                            marksModel1.Add(d[1].ToString() + "_" + rowsFiltered[0][1].ToString() + "_" + d[3].ToString(), rowsFiltered[0][1].ToString());
