        public JsonResult GetCandidatesRemarks()
        {
            var cc = new ClientCustomize();
            int CheckFamilRowId = Convert.ToInt32(Session["CheckFamilRowId"]);
            var department = Session["Department"].ToString();

            if (Session["sessSubCheckRowID"] != null)
            {
                string subCheckRowId = Session["sessSubCheckRowID"].ToString();

                var validProRefIds = new HashSet<string>
                {
                    "150", "151", "152", "153", "154", "311", "329", "335", "336", "364", "414"
                };

                if (validProRefIds.Contains(subCheckRowId))
                {
                    department = "ProReference";
                }
            }

            var candidates = cc.GetRemarks(department, CheckFamilRowId);
            if (candidates.Tables.Count > 0 && candidates.Tables[0].Rows.Count > 0)
            {
                var candidateList = candidates.Tables[0].Rows.Cast<DataRow>().Select(row => new RemarksList
                {
                    Remarks = row["Remarks"].ToString()
                }).ToList();
                return Json(candidateList, JsonRequestBehavior.AllowGet);
            }
            else
            {
                return Json(new { error = "No candidates found" }, JsonRequestBehavior.AllowGet);
            }
        }

