                                            body = body.Replace("{license_number}", Convert.ToString(tbl.Rows[0]["license_number"]));
                                            body = body.Replace("{state}", Convert.ToString(tbl.Rows[0]["state"]));
                                            body = body.Replace("{permanent_address}", Convert.ToString(tbl.Rows[0]["permanent_address"]));
                                            body = body.Replace("{temporary_address}", Convert.ToString(tbl.Rows[0]["temporary_address"]));

                                            body = body.Replace("{citizenship}", Convert.ToString(tbl.Rows[0]["citizenship"]));
                                            body = body.Replace("{gender}", Convert.ToString(tbl.Rows[0]["gender"]));
                                            body = body.Replace("{father_or_husband_name}", Convert.ToString(tbl.Rows[0]["father_or_husband_name"]));
                                            body = body.Replace("{dob}", Convert.ToString(tbl.Rows[0]["dob"]));
                                            body = body.Replace("{doe}", Convert.ToString(tbl.Rows[0]["doe"]));
                                            body = body.Replace("{transport_doe}", Convert.ToString(tbl.Rows[0]["transport_doe"]));
                                            body = body.Replace("{doi}", Convert.ToString(tbl.Rows[0]["doi"]));
                                            body = body.Replace("{blood_group}", Convert.ToString(tbl.Rows[0]["blood_group"]));
                                            body = body.Replace("{vehicle_classes}", Convert.ToString(tbl.Rows[0]["vehicle_classes"]));
                                            body = body.Replace("{verifiedDate}", DateTime.Now.Date.ToString("dd-MMM-yyyy"));

                                            body = body.Replace("{ImagePath}", Convert.ToString(tbl.Rows[0]["profile_image"]));

                                        }
                                        string FileName = SavePQVerifiedUploadUANDoc(Convert.ToInt32(PersonalRowId), Convert.ToInt16(SubCheckRowId), "Verified", "DrivingLicense", "provideddocuments", body, "License Verified", 0, companyRefNo);
                                        cc.UpdateTmMemberID(Convert.ToInt32(PersonalRowId), SubCheckRowId);
                                        cc.UpdateCheckStatus(Convert.ToInt32(PersonalRowId), SubCheckRowId, 1, 107, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));

                                        clsCommonMethods.AddCheckActionHistory(Convert.ToInt32(PersonalRowId), Convert.ToInt16(SubCheckRowId), "Completed", "Verification recieve throught integration");

                                        PRowId = PRowId + "," + PersonalRowId;

                                        NotExistUAN.PersonalRowID = PersonalRowId;
                                        NotExistUAN.CompanyRefNo = companyRefNo;
                                        NotExistUAN.FileName = FileName;
                                        NotExistUAN.IdNumber = IDNumber;
                                        NotExistUAN.IDType = IDType;
                                        NotExistUAN.Action = "true";
                                        UANNoNotExistLst.Add(NotExistUAN);
                                    }
                                }


                            }
                            else if (IDType == "AADHAAR CARD" || IDType.ToUpper() == "AADHAAR")
                            {
                                string FileName = GetLlmtechAadhaarLive(Convert.ToInt32(PersonalRowId), SubCheckRowId, ClientRowId, IDNumber, companyRefNo, CandidateName);
                                if (FileName != "")
                                {
                                    PRowId = PRowId + "," + PersonalRowId;
                                    NotExistUAN.PersonalRowID = PersonalRowId;
                                    NotExistUAN.CompanyRefNo = companyRefNo;
                                    NotExistUAN.FileName = FileName;
                                    NotExistUAN.IdNumber = IDNumber;
                                    NotExistUAN.IDType = IDType;
                                    NotExistUAN.Action = "true";
                                    UANNoNotExistLst.Add(NotExistUAN);
                                }
                                else
                                {
                                    NotExistUAN.PersonalRowID = PersonalRowId;
                                    NotExistUAN.CompanyRefNo = companyRefNo;
                                    NotExistUAN.FileName = "";
                                    NotExistUAN.IdNumber = IDNumber;
                                    NotExistUAN.IDType = IDType;
                                    NotExistUAN.Action = "false";
                                    UANNoNotExistLst.Add(NotExistUAN);
                                }
                            }
                        }
                        else
                        {
                            NotExistUAN.PersonalRowID = PersonalRowId;
                            NotExistUAN.CompanyRefNo = companyRefNo;
                            NotExistUAN.FileName = "";
                            NotExistUAN.IdNumber = IDNumber;
                            NotExistUAN.IDType = IDType;
                            NotExistUAN.Action = "false";
                            UANNoNotExistLst.Add(NotExistUAN);
                        }
                    }
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return UANNoNotExistLst;
            }
            return UANNoNotExistLst;
        }

