        public ActionResult BulKClosure(HttpPostedFileBase fileUpload)
        {
            if (fileUpload != null && fileUpload.ContentLength > 0)
            {
                var fileName = Path.GetFileName(fileUpload.FileName);

                var fileExtension = Path.GetExtension(fileName).ToLower();
                if (fileExtension != ".xls" && fileExtension != ".xlsx")
                {
                    ViewBag.Message = "Invalid file type. Please upload an Excel file.";
                    return View();
                }
                var filePath = Path.Combine(Server.MapPath("~/Uploads/BulkClosureUploads/"), fileName);

                var directoryPath = Path.GetDirectoryName(filePath);
                if (!Directory.Exists(directoryPath))
                {
                    Directory.CreateDirectory(directoryPath);
                }

                fileUpload.SaveAs(filePath);

                //==============================================
                string conStr = "";
                switch (fileExtension)
                {
                    case ".xls": //Excel 97-03
                        conStr = ConfigurationManager.ConnectionStrings["Excel03ConString"].ConnectionString;
                        break;
                    case ".xlsx": //Excel 07
                        conStr = ConfigurationManager.ConnectionStrings["Excel07ConString"].ConnectionString;
                        break;
                }
                conStr = String.Format(conStr, filePath, "Yes");
                OleDbConnection connExcel = new OleDbConnection(conStr);
                OleDbCommand cmdExcel = new OleDbCommand();
                OleDbDataAdapter oda = new OleDbDataAdapter();
                DataTable dt = new DataTable();

                cmdExcel.Connection = connExcel;

                //Get the name of First Sheet
                connExcel.Open();
                DataTable dtExcelSchema;
                dtExcelSchema = connExcel.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, null);
                string SheetName = dtExcelSchema.Rows[0]["TABLE_NAME"].ToString();
                connExcel.Close();

                //Read Data from First Sheet
                connExcel.Open();
                cmdExcel.CommandText = "SELECT * From [" + SheetName + "]";
                oda.SelectCommand = cmdExcel;
                oda.Fill(dt);
                connExcel.Close();
                AddClosureBulkUpViewModel Model = new AddClosureBulkUpViewModel();
                if (dt.Rows.Count > 0)
                {
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        string companyRefNo = dt.Rows[i]["CompanyRefNo"].ToString().Trim();
                        string checkUniqueID = dt.Rows[i]["CheckUniqueID"].ToString().Trim();
                        if (string.IsNullOrWhiteSpace(companyRefNo) || string.IsNullOrWhiteSpace(checkUniqueID))
                        {

                            continue;
                        }
                        //========================
                        DataTable dd = new DataTable();
                        ClientCustomize cc1 = new ClientCustomize();
                        dd = cc1.GetCheckDetailsByCheckUniqueId(checkUniqueID);
                        if (dd.Rows.Count > 0)
                        {
                            if (dd.Rows.Count != 0 || dd.Rows[0]["CheckStatusID"] != DBNull.Value)
                            {
                                string checkstatus = Convert.ToString(dd.Rows[0]["CheckStatusID"]);
                                string[] statuses = { "20", "21", "56", "61", "75", "76", "77", "78", "79", "80", "82", "88", "90", "92", "106" };
                                if (statuses.Contains(checkstatus))
                                {

                                    Model.ClientName = dt.Rows[i]["ClientName"].ToString().Trim();
                                    Model.TMName = dt.Rows[i]["TMName"].ToString().Trim();
                                    Model.CompanyRefNo = dt.Rows[i]["CompanyRefNo"].ToString().Trim();
                                    Model.CandidateName = dt.Rows[i]["CandidateName"].ToString().Trim();
                                    Model.CheckUniqueID = dt.Rows[i]["CheckUniqueID"].ToString().Trim();
                                    Model.TypeOfEducation = dt.Rows[i]["TypeOfEducation"].ToString().Trim();
                                    Model.CollegeName = dt.Rows[i]["CollegeName"].ToString().Trim();
                                    Model.UniversityName = dt.Rows[i]["UniversityName"].ToString().Trim();
                                    Model.CourseName = dt.Rows[i]["CourseName"].ToString().Trim();
                                    Model.YearOfPassing = dt.Rows[i]["YearOfPassing"].ToString().Trim();
                                    Model.RollNo = dt.Rows[i]["RollNo"].ToString().Trim();
                                    Model.Respondents_Name_and_Designation = dt.Rows[i]["Respondent's Name and Designation"].ToString().Trim();
                                    Model.Check_status = dt.Rows[i]["Check status"].ToString().Trim();
                                    Model.Closure_date = dt.Rows[i]["Closure date (Today Date)"].ToString().Trim();
                                    Model.Mode_of_Verification = dt.Rows[i]["* Mode of Verification"].ToString().Trim();
                                    Model.Link = dt.Rows[i]["Link"].ToString().Trim();
                                    Model.Verified_From = dt.Rows[i]["Verified From"].ToString().Trim();
                                    Model.Attachments = dt.Rows[i]["Attachments"].ToString().Trim();
                                    Model.Other_Comment = dt.Rows[i]["Other Comments"].ToString().Trim();

                                    OperationViewModel cd = new OperationViewModel();
