                                    cd.SubCheckRowID = cc.getSubCheckRowIdByCheckUniqueId(Model.CheckUniqueID);
                                    cd.clientRowId = Convert.ToInt32(dt1.Rows[0]["ClientRowID"]);
                                    cd.CreatedBy = 0;
                                    cd.moduleName = "OPTM";
                                    DataRow row = dt.Rows[i];
                                    foreach (DataColumn column in dt.Columns)
                                    {
                                        string columnname = column.Caption.Trim();
                                        string fieldValue = row[column].ToString().Trim();
                                        if (columnname == "CandidateName")
                                        {
                                            cd.AntecedentRowID = 68;
                                            cd.DisplayName = cc.GetCADisplayNamebyAntecedentsRowID(Convert.ToInt32(cd.AntecedentRowID));
                                            cd.DataEntryValue = Model.CandidateName;
                                        }
                                        else if (columnname == "CollegeName")
                                        {
                                            cd.AntecedentRowID = 69;
                                            cd.DisplayName = cc.GetCADisplayNamebyAntecedentsRowID(Convert.ToInt32(cd.AntecedentRowID));
                                            cd.DataEntryValue = Model.CollegeName;
                                        }
                                        else if (columnname == "UniversityName")
                                        {
                                            cd.AntecedentRowID = 67;
                                            cd.DisplayName = cc.GetCADisplayNamebyAntecedentsRowID(Convert.ToInt32(cd.AntecedentRowID));
                                            cd.DataEntryValue = Model.UniversityName;

                                        }
                                        else if (columnname == "RollNo")
                                        {
                                            cd.AntecedentRowID = 78;
                                            cd.DisplayName = cc.GetCADisplayNamebyAntecedentsRowID(Convert.ToInt32(cd.AntecedentRowID));
                                            cd.DataEntryValue = Model.RollNo;
                                        }
                                        else if (columnname == "Respondent's Name and Designation")
                                        {
                                            cd.AntecedentRowID = 138;
                                            cd.DisplayName = cc.GetCADisplayNamebyAntecedentsRowID(Convert.ToInt32(cd.AntecedentRowID));
                                            cd.DataEntryValue = Model.Respondents_Name_and_Designation;
                                        }
                                        else if (columnname == "* Mode of Verification")
                                        {
                                            cd.AntecedentRowID = 140;
                                            cd.DisplayName = cc.GetCADisplayNamebyAntecedentsRowID(Convert.ToInt32(cd.AntecedentRowID));
                                            cd.DataEntryValue = Model.Mode_of_Verification;
                                        }
                                        else if (columnname == "YearOfPassing")
                                        {
                                            cd.AntecedentRowID = 80;
                                            cd.DisplayName = cc.GetCADisplayNamebyAntecedentsRowID(Convert.ToInt32(cd.AntecedentRowID));
                                            cd.DataEntryValue = Model.YearOfPassing;
                                        }
                                        else if (columnname == "CourseName")
                                        {
                                            cd.AntecedentRowID = 72;
                                            cd.DisplayName = cc.GetCADisplayNamebyAntecedentsRowID(Convert.ToInt32(cd.AntecedentRowID));
                                            cd.DataEntryValue = Model.CourseName;
                                        }
                                        else if (columnname == "Other Comments")
                                        {
                                            cd.AntecedentRowID = 66;
                                            cd.DisplayName = cc.GetCADisplayNamebyAntecedentsRowID(Convert.ToInt32(cd.AntecedentRowID));
                                            cd.DataEntryValue = Model.Other_Comment;
                                        }
                                        else if (columnname == "Check status")
                                        {
                                            cd.AntecedentRowID = 139;
                                            cd.DisplayName = cc.GetCADisplayNamebyAntecedentsRowID(Convert.ToInt32(cd.AntecedentRowID));
                                            cd.DataEntryValue = Model.Check_status;
                                        }
                                        else if (columnname == "Closure date (Today Date)")
                                        {
                                            cd.AntecedentRowID = 172;
                                            cd.DisplayName = cc.GetCADisplayNamebyAntecedentsRowID(Convert.ToInt32(cd.AntecedentRowID));
                                            cd.DataEntryValue = Model.Closure_date;
                                        }

                                        if (cd.AntecedentRowID > 0)
                                        {
                                            cc.tblDataEntry_OperationInsert(cd);
                                        }

                                    }

                                    if (!string.IsNullOrEmpty(Model.Attachments))
                                    {

                                        string[] attachmentArray = Model.Attachments.Split(',');


                                        foreach (string attachment in attachmentArray)
                                        {
                                            string FldPathDoc = ConfigurationManager.AppSettings["provideddocuments"].ToString();
                                            string proImg = string.Empty;
                                            ClientCustomize CC1 = new ClientCustomize();
