                                            model.StatusPDF2DOCXConvert = 0;
                                            model.UploadDate = DateTime.Now;
                                            model.Status = 1;
                                            model.PersonalRowID = Convert.ToInt32(cd.PersonalRowID);
                                            model.SubCheckRowID = Convert.ToInt16(cd.SubCheckRowID);
                                            string ext = Path.GetExtension(attachment).ToLower();
                                            proImg = attachment;
                                            model.FileName = proImg;
                                            cc.UpdateImageArtifact(model.PersonalRowID, model.SubCheckRowID);
                                            repoPQVerifiedUploadDoc.VerifiedUploadDoc1(model);
                                            int Res = repoPQVerifiedUploadDoc.SaveChanges();
                                            if (Res > 0)
