                                                #region Check Action History Save                           
                                                clsCommonMethods.AddCheckActionHistory(model.PersonalRowID, model.SubCheckRowID, model.CheckStatus, "Verification information Upload Doc ");
                                                #endregion

                                            }
                                        }
                                    }

                                    EducationVerCloserViewModel model1 = new EducationVerCloserViewModel();
                                    short TeamMemberRowID = Convert.ToInt16(Session["TeamMemberRowID"]); ;

                                    model1.PersonalRowID = Convert.ToInt32(cd.PersonalRowID);
                                    model1.SubCheckRowID = Convert.ToInt16(cd.SubCheckRowID);
                                    model1.CheckStatus = "Completed";
                                    model1.ActionHistory = Model.Other_Comment;
                                    model1.Remarks = Model.Other_Comment;
                                    int SeverityId = 6;
                                    model1.DispositionID = "148"; //"1033";
                                    model1.ColorName = "Green";
                                    cc.UpdateCheckStatus(model1.PersonalRowID, model1.SubCheckRowID, 1, 24, "Check", Convert.ToInt32(TeamMemberRowID));
                                    cc.UpdatePQCandidateChecksColorCode(Convert.ToInt32(model1.DispositionID), SeverityId, model1.ColorName, model1.PersonalRowID, model1.SubCheckRowID, model1.Remarks);
                                    clsCommonMethods.AddCheckActionHistory(model1.PersonalRowID, model1.SubCheckRowID, model1.CheckStatus, model1.ActionHistory);
                                    cc.UpdatePQCandidateChecksColorCode(Convert.ToInt32(model1.DispositionID), SeverityId, model1.ColorName, model1.PersonalRowID, model1.SubCheckRowID, model1.Remarks);
                                    cc.UpdateStatus(model1.PersonalRowID, model1.SubCheckRowID);
                                    #region Check Action History Save                           
                                    clsCommonMethods.AddCheckActionHistory(model1.PersonalRowID, model1.SubCheckRowID, model1.CheckStatus, model1.ActionHistory);
                                    #endregion

                                    #region Add Bulk Closure Histroy
                                    cc.AddBulkClosureHistroy(model1.PersonalRowID, model1.SubCheckRowID, Convert.ToInt32(checkstatus), 24, 11);
                                    #endregion
                                }

                            }
                        }

                        //========================



                    }

                }
                //==============================================


                ViewBag.Message = "File uploaded successfully!";
            }
            else
            {
                ViewBag.Message = "No file selected!";
            }


            return View();
        }


