        [HttpPost]
        public ActionResult UploadMultiDoc(IEnumerable<HttpPostedFileBase> files)
        {

            if (files != null && files.Any())
            {
                foreach (var file in files)
                {
                    string PathDoc = ConfigurationManager.AppSettings["provideddocuments"].ToString();
                    string absolutePathDoc = Server.MapPath(PathDoc);
                    if (file != null && file.ContentLength > 0)
                    {

                        string DocumentType = "Document";
                        string ext = Path.GetExtension(file.FileName);
                        string originalFileName = Path.GetFileNameWithoutExtension(file.FileName);
                        string uniqueFileName = $"{originalFileName}{ext}"; // Use GUID for uniqueness
                        var provideddocumentsPath = Server.MapPath(PathDoc + uniqueFileName);
                        var filePath = Path.Combine(absolutePathDoc, uniqueFileName);
                        file.SaveAs(filePath);

                    }
                }

                ViewBag.Message = "Files uploaded successfully!";
                return View();
            }

            ViewBag.Message = "No files selected.";
            return View();
        }


