        [HttpGet]
        [SessionExpireFilterAttribute]
        public ActionResult BulKClosureGlobal()
        {
            return View();
        }

        [HttpPost]
        [SessionExpireFilterAttribute]
        public ActionResult BulKClosureGlobal(HttpPostedFileBase fileUpload)
        {
            if (fileUpload != null && fileUpload.ContentLength > 0)
            {
                var fileName = Path.GetFileName(fileUpload.FileName);
                string shortGuid = Guid.NewGuid().ToString().Substring(0, 5);
                var filenamewuthoutext = Path.GetFileNameWithoutExtension(fileUpload.FileName);
                var fileExtension = Path.GetExtension(fileName).ToLower();
                if (fileExtension != ".xls" && fileExtension != ".xlsx")
                {
                    ViewBag.Message = "Invalid file type. Please upload an Excel file.";
                    return View();
                }
                var filePath = Path.Combine(Server.MapPath("~/Uploads/BulkClosureUploadsCRC/"), filenamewuthoutext + "_" + shortGuid + fileExtension);

                var directoryPath = Path.GetDirectoryName(filePath);
                if (!Directory.Exists(directoryPath))
                {
                    Directory.CreateDirectory(directoryPath);
                }

                fileUpload.SaveAs(filePath);

                //==============================================
                string conStr = "";
                switch (fileExtension)
                {
                    case ".xls": //Excel 97-03
                        conStr = ConfigurationManager.ConnectionStrings["Excel03ConString"].ConnectionString;
                        break;
                    case ".xlsx": //Excel 07
                        conStr = ConfigurationManager.ConnectionStrings["Excel07ConString"].ConnectionString;
                        break;
                }
                conStr = String.Format(conStr, filePath, "Yes");
                OleDbConnection connExcel = new OleDbConnection(conStr);
                OleDbCommand cmdExcel = new OleDbCommand();
                OleDbDataAdapter oda = new OleDbDataAdapter();
                DataTable dt = new DataTable();

                cmdExcel.Connection = connExcel;

                //Get the name of First Sheet
                connExcel.Open();
                DataTable dtExcelSchema;
                dtExcelSchema = connExcel.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, null);
                string SheetName = dtExcelSchema.Rows[0]["TABLE_NAME"].ToString();
                connExcel.Close();

                //Read Data from First Sheet
                connExcel.Open();
                cmdExcel.CommandText = "SELECT * From [" + SheetName + "]";
                oda.SelectCommand = cmdExcel;
                oda.Fill(dt);
                connExcel.Close();
                //AddClosureBulkUpViewModel Model = new AddClosureBulkUpViewModel();
                AddClosureBulkUpGlobalViewModel Model = new AddClosureBulkUpGlobalViewModel();
                if (dt.Rows.Count > 0)
                {
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        string companyRefNo = dt.Rows[i]["Company RefNo"].ToString().Trim();
                        string checkUniqueID = dt.Rows[i]["Uniquecomponentid"].ToString().Trim();

                        if (string.IsNullOrWhiteSpace(companyRefNo) || string.IsNullOrWhiteSpace(checkUniqueID))
                        {

                            continue;
                        }

                        //========================
                        DataTable dd = new DataTable();
                        ClientCustomize cc1 = new ClientCustomize();
                        dd = cc1.GetCheckDetailsByCheckUniqueId(checkUniqueID);
                        if (dd.Rows.Count != 0 || dd.Rows[0]["CheckStatusID"] != DBNull.Value)
                        {
                            string checkstatus = Convert.ToString(dd.Rows[0]["CheckStatusID"]);
                            string[] statuses = { "20", "24", "21", "115", "107" };
                            if (statuses.Contains(checkstatus))
                            {
                                //Model.ClientName = dt.Rows[i]["client name"].ToString().Trim();
                                Model.CompanyRefNo = dt.Rows[i]["Company RefNo"].ToString().Trim();
                                Model.CandidateFullName = dt.Rows[i]["Name"].ToString().Trim();
                                Model.SubCheckName = dt.Rows[i]["Type"].ToString().Trim();
                                Model.CheckUniqueID = dt.Rows[i]["Uniquecomponentid"].ToString().Trim();
                                Model.DOB = dt.Rows[i]["DOB"].ToString().Trim();
                                Model.FatherName = dt.Rows[i]["Father Name"].ToString().Trim();
                                Model.Gender = dt.Rows[i]["Gender"].ToString().Trim();
                                Model.Severity = dt.Rows[i]["Severity"].ToString().Trim();
                                Model.Status = dt.Rows[i]["Status"].ToString().Trim();
                                Model.Mode_of_Verification = dt.Rows[i]["Mode of Verification"].ToString().Trim();
                                Model.Date_of_Verification = dt.Rows[i]["Date of Verification"].ToString().Trim();
                                Model.Any_Other_Comments = dt.Rows[i]["Any Other Comments"].ToString().Trim();
                                Model.Color_code = dt.Rows[i]["Color code"].ToString().Trim();
                                Model.CheckStatus = dt.Rows[i]["Check Status"].ToString().Trim();
                                Model.ReportComment = dt.Rows[i]["Report Comment"].ToString().Trim();
                                Model.Attachments = dt.Rows[i]["Attachments"].ToString().Trim();
                                Model.IdentityType = dt.Rows[i]["IdentityType"].ToString().Trim();
                                Model.Address = dt.Rows[i]["address"].ToString().Trim();
                                Model.UAN_No = dt.Rows[i]["UAN No"].ToString().Trim();
                                Model.Contact_No = dt.Rows[i]["ContactNo"].ToString().Trim();
                                Model.Pan_No = dt.Rows[i]["Pan No"].ToString().Trim();


                                OperationViewModel cd = new OperationViewModel();
