                var fileExtension = Path.GetExtension(fileName).ToLower();
                if (fileExtension != ".xls" && fileExtension != ".xlsx")
                {
                    ViewBag.Message = "Invalid file type. Please upload an Excel file.";
                    return View();
                }
                var fileNameWithoutExtension = Path.GetFileNameWithoutExtension(fileName);

              
                var uniqueFileName = $"{fileNameWithoutExtension}_{DateTime.Now:yyyyMMddHHmmss}{fileExtension}";


                var filePath = Path.Combine(Server.MapPath("~/Uploads/BulkClosureUploadsCRC/"), uniqueFileName);

