        public ActionResult GetUANDatafromExcel(FormCollection frm, HttpPostedFileBase DigitalVer)
        {

            List<InstantCheckResultStatus> UANNoNotExistLst = new List<InstantCheckResultStatus>();
            try
            {
                string VendorName = Convert.ToString(frm["VendorName"]);
                var Timestamp = new DateTimeOffset(DateTime.UtcNow).ToUnixTimeSeconds().ToString();
                string path = ConfigurationManager.AppSettings["provideddocuments"].ToString();
                string ext = Path.GetExtension(DigitalVer.FileName).ToLower();
                string filename = "UAN_" + Timestamp + ext;
                string filePath = path + filename;
                filePath = Server.MapPath(path + filename);
                DigitalVer.SaveAs(filePath);
                var UANLst = GetBulkUANDatafromExcel(filePath, ext, "Yes", "UAN2", VendorName);
                UANNoNotExistLst = UANLst;
                ClientCustomize cc = new ClientCustomize();
                ViewBag.PersonalDocDetails = UANLst;
                //ExportToExcel(UANLst, "BulkUANFindDetails");               
                ViewBag.ErrorMsg = Convert.ToString(UANLst.Count) + " UAN Number Process !";

            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return RedirectToAction("GetBulkUAN", new { errorMsg = Ex.Message });
            }

            return View(UANNoNotExistLst);
        }
        private List<InstantCheckResultStatus> GetBulkUANDatafromExcel(string FilePath, string Extension, string isHDR, string instantCheckName, string VendorName)
        {
            int Count = 0;
            ClientCustomize cc = new ClientCustomize();
            List<InstantCheckResultStatus> UANNoNotExistLst = new List<InstantCheckResultStatus>();

            try
            {
                string conStr = "";
                switch (Extension)
                {
                    case ".xls": //Excel 97-03
                        conStr = ConfigurationManager.ConnectionStrings["Excel03ConString"].ConnectionString;
                        break;
                    case ".xlsx": //Excel 07
                        conStr = ConfigurationManager.ConnectionStrings["Excel07ConString"].ConnectionString;
                        break;
                }
                conStr = String.Format(conStr, FilePath, isHDR);
                OleDbConnection connExcel = new OleDbConnection(conStr);
                OleDbCommand cmdExcel = new OleDbCommand();
                OleDbDataAdapter oda = new OleDbDataAdapter();
                DataTable dt = new DataTable();

                cmdExcel.Connection = connExcel;

                //Get the name of First Sheet
                connExcel.Open();
                DataTable dtExcelSchema;
                dtExcelSchema = connExcel.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, null);
                string SheetName = dtExcelSchema.Rows[0]["TABLE_NAME"].ToString();
                connExcel.Close();

                //Read Data from First Sheet
                connExcel.Open();
                cmdExcel.CommandText = "SELECT * From [" + SheetName + "]";
                oda.SelectCommand = cmdExcel;
                oda.Fill(dt);
                connExcel.Close();

                if (dt.Rows.Count > 0)
                {

                    string MobileNo = string.Empty;
                    string DocName = string.Empty;
                    string PRowId = string.Empty;

                    AddUANCheckDetailsByAPI AddApiObj = new AddUANCheckDetailsByAPI();
                    string companyRefNo = "";
                    DataTable UanTD = new DataTable();

                    string[] selectedColumns = new[] { "UAN" };
                    DataTable GroupByDT = new DataView(dt).ToTable(false, selectedColumns);
                    UanTD = GroupByDT.AsEnumerable().GroupBy(r => r.Field<object>("UAN")).Select(g => g.First()).CopyToDataTable();

                    for (int J = 0; J < UanTD.Rows.Count; J++)
                    {
                        InstantCheckResultStatus NotExistUAN = new InstantCheckResultStatus();
                        string UANNO = UanTD.Rows[J]["UAN"].ToString().Trim();
                        DataTable tblFiltered = dt.AsEnumerable()
                            .Where(row => row.Field<string>("UAN").Contains(UANNO)).CopyToDataTable();

                        Rootobject DataObj = new Rootobject();
                        Employment_HistoryData objdata = new Employment_HistoryData();
                        List<Employment_History> employment_Histories = new List<Employment_History>();
                        DataObj.statuscode = 200;
                        DataObj.status = true;
                        DataObj.message = "Data read from Excel";
                        DataObj.reference_id = "";

                        objdata.client_id = "";
                        companyRefNo = Convert.ToString(tblFiltered.Rows[0]["CompanyRefNo"]).ToString().Trim();
                        for (int B = 0; B < tblFiltered.Rows.Count; B++)
                        {
                            employment_Histories.Add(new Employment_History
                            {
                                name = tblFiltered.Rows[B]["Name"].ToString(),
                                guardian_name = tblFiltered.Rows[B]["Father_HusbandName"].ToString(),
                                establishment_name = tblFiltered.Rows[B]["EstablishmentName"].ToString(),
                                member_id = tblFiltered.Rows[B]["MemberID"].ToString(),
                                date_of_joining = tblFiltered.Rows[B]["DOJ"] != DBNull.Value ? Convert.ToDateTime(tblFiltered.Rows[B]["DOJ"]).ToString("dd-MMM-yyyy") : null,
                                date_of_exit = tblFiltered.Rows[B]["DOE"] != DBNull.Value ? Convert.ToDateTime(tblFiltered.Rows[B]["DOE"]).ToString("dd-MMM-yyyy") : null
                            });
                        }

                        objdata.employment_history = employment_Histories.ToArray();
                        DataObj.data = objdata;

                        var dbPersonal = cc.GetpersonaldatafromCompanyRefNo(companyRefNo);
                        string PersonalRowId = "";
                        int SubCheckRowId = 0;
                        if (dbPersonal.Rows.Count > 0)
                        {
                            PersonalRowId = dbPersonal.Rows[0]["PersonalRowId"].ToString();

                        }
                        DataTable tbldb = new DataTable();
                        string data = "";
                        bool UANExists = false;
                        int ClientRowId = 0;

                        if (DataObj.statuscode == 200)
                        {
                            var result = cc.InsertintoSprintVerifyEPFO_history(DataObj, PersonalRowId.ToString(), UANNO.Trim(), 0, VendorName);
                            if (result != "")
                            {
                                Count++;
                                string body = string.Empty;
                                UANExists = true;
                                tbldb = cc.GetSprintVerify_epfoReport(Convert.ToInt32(result));
                            }
                            else
                            {
                                NotExistUAN.PersonalRowID = PersonalRowId;
                                NotExistUAN.CompanyRefNo = companyRefNo;
                                NotExistUAN.FileName = "";
                                NotExistUAN.UAN = UANNO;
                                NotExistUAN.Action = "false";
                                UANNoNotExistLst.Add(NotExistUAN);
                            }
                        }
                        else
                        {
                            NotExistUAN.PersonalRowID = PersonalRowId;
                            NotExistUAN.CompanyRefNo = companyRefNo;
                            NotExistUAN.FileName = "";
                            NotExistUAN.UAN = UANNO;
                            NotExistUAN.Action = "false";
                            UANNoNotExistLst.Add(NotExistUAN);
                        }

                        if (UANExists == true)
                        {
                            string body = string.Empty;
                            string ImageName = "";
                            if (VendorName == "Viotal informatics")
                            {
                                ImageName = "ViotalinformaticsLogo.JPG";
                            }
                            else if (VendorName == "Liilmmra")
                            {
                                ImageName = "LiilmmraLogo.JPG";
                            }
                            else
                            {
                                ImageName = "PaySprintlogo.JPG";
                            }
                            using (StreamReader reader = new StreamReader(Server.MapPath("~/Emailers/UANCheckArtifact.html")))
                            {
                                body = reader.ReadToEnd();
                            }
                            string name = "";
                            string guardian_name = "";
                            string uanNumberId = "";

                            for (int j = 0; j < tbldb.Rows.Count; j++)
                            {
                                string date_of_joining = "";
                                string last_pf_submitted = "";
                                if (j == 0)
                                {
                                    companyRefNo = Convert.ToString(tbldb.Rows[j]["companyRefNo"]);
                                    name = Convert.ToString(tbldb.Rows[j]["name"]);
                                    guardian_name = Convert.ToString(tbldb.Rows[j]["guardian_name"]);
                                    uanNumberId = Convert.ToString(tbldb.Rows[j]["UANNO"]);
                                }
                                if (Convert.ToString(tbldb.Rows[j]["date_of_joining"]) != "")
                                {
                                    DateTime doj = Convert.ToDateTime(tbldb.Rows[j]["date_of_joining"]);
                                    date_of_joining = doj.ToString("dd-MMM-yyyy");
                                }
                                if (Convert.ToString(tbldb.Rows[j]["date_of_exit"]) != "")
                                {
                                    DateTime doe = Convert.ToDateTime(tbldb.Rows[j]["date_of_exit"]);
                                    last_pf_submitted = doe.ToString("dd-MMM-yyyy");
                                }
                                data += "<tr>";
                                data += "<td> " + Convert.ToString(tbldb.Rows[j]["establishment_name"]) + " (" + Convert.ToString(tbldb.Rows[j]["member_id"]) + ")" + " </td>";
                                data += "<td> " + date_of_joining + " </td>";
                                data += "<td> " + last_pf_submitted + " </td>";
                                data += "</tr>";

                            }
                            body = body.Replace("{companyRefNo}", companyRefNo);
                            body = body.Replace("{ImageName}", ImageName);
                            body = body.Replace("{name}", name);
                            body = body.Replace("{guardian_name}", guardian_name);
                            body = body.Replace("{uanNumberId}", uanNumberId);
                            body = body.Replace("{EstablishedDetails}", data);
                            body = body.Replace("{verifiedDate}", DateTime.Now.Date.ToString("dd-MMM-yyyy"));

                            var FileName = "";
                            var DTCheckId = cc.GetUANSubCheckRowID(Convert.ToInt32(PersonalRowId));

                            if (DTCheckId.Rows.Count > 0)
                            {
                                for (int T = 0; T < DTCheckId.Rows.Count; T++)
                                {
                                    short SubCheckId = Convert.ToInt16(DTCheckId.Rows[T]["SubCheckRowID"]);
                                    FileName = SavePQVerifiedUploadUANDoc(Convert.ToInt32(PersonalRowId), SubCheckId, "Verified", "Verification Artifact", "provideddocuments", body, "UAN No Verified", 0, companyRefNo);

                                }
                            }
                            //else
                            //{                         
                            FileName = SavePQVerifiedUploadCaseDocUAN(Convert.ToInt32(PersonalRowId), "Verified", "UAN Case Report", "provideddocuments", body, "UAN No Verified", false, companyRefNo);
                            //}


                            PRowId = PRowId + "," + PersonalRowId;

                            NotExistUAN.PersonalRowID = PersonalRowId;
                            NotExistUAN.FileName = FileName;
                            NotExistUAN.CompanyRefNo = companyRefNo;
                            NotExistUAN.UAN = UANNO;
                            NotExistUAN.Action = "true";
                            UANNoNotExistLst.Add(NotExistUAN);
                        }
                    }

                    if (PRowId.Substring(0, 1) == ",")
                    {
                        Session["PRowIds"] = PRowId.Substring(1, PRowId.Length - 1);
                    }
                }
                else
                {
                    ViewBag.ErrorMsg = "UAN Number found!";
                }

            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                InstantCheckResultStatus NotExistUAN = new InstantCheckResultStatus();
                NotExistUAN.PersonalRowID = "";
                NotExistUAN.FileName = Ex.Message;
                NotExistUAN.CompanyRefNo = Ex.StackTrace;
                NotExistUAN.UAN = "";
                NotExistUAN.Action = "false";
                UANNoNotExistLst.Add(NotExistUAN);
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return UANNoNotExistLst;
            }
            return UANNoNotExistLst;

        }
        public string SavePQVerifiedUploadCaseDocUAN(int PersonalRowID = 0, string DocumentUploadFrom = "", string DocumentType = "", string FolderNameForSave = "", string UploadDoc = "", string remarks = "", bool NADoc = false, string secRefId = "")
        {
            try
            {
                var Timestamp = new DateTimeOffset(DateTime.UtcNow).ToUnixTimeSeconds().ToString();

                string FileName = "";
                string proImg = string.Empty;
                AddPQVerifiedUploadCaseDocViewModel DocModel = new AddPQVerifiedUploadCaseDocViewModel();
                DocModel.PersonalRowID = PersonalRowID;
                DocModel.DocumentUploadFrom = DocumentUploadFrom; //  Provided / Verified
                DocModel.DocumentType = DocumentType; //Name of the selected docs
                FileName = (secRefId + " " + DocumentType).Replace(" ", "_").Replace("-", "_") + "_" + Timestamp;
                if (!NADoc)
                {
                    if (FileName.Contains("24/7CPL_"))
                    {
                        FileName = FileName.Replace("/", "-");
                    }
                    string FldPathDoc = string.Empty;
                    FldPathDoc = ConfigurationManager.AppSettings[FolderNameForSave.Trim().ToLower()].ToString();

                    string existFile = repoPQVerifiedUploadCaseDoc.ExistcaseFileByPersonalIdAndDocType(PersonalRowID, DocumentType, FileName);
                    if (!string.IsNullOrEmpty(existFile))
                    {
                        string path = Server.MapPath(FldPathDoc + existFile);
                        FileInfo file = new FileInfo(path);
                        if (file.Exists)//check file exsit or not
                        {
                            file.Delete();
                        }
                    }


                    proImg = FileName + ".pdf";


                    string IronKey = System.Configuration.ConfigurationManager.AppSettings["IronKey"].ToString();
                    var Renderer = new IronPdf.ChromePdfRenderer();
                    IronPdf.License.LicenseKey = IronKey;
                    var pdf = Renderer.RenderHtmlAsPdf(UploadDoc);

                    pdf.SaveAs(Server.MapPath(FldPathDoc + proImg)); // Saves our PdfDocument object as a PDF

                    DocModel.FileName = Path.GetFileName(proImg);
                    DocModel.FilePath = FldPathDoc;
                }
                else
                {
                    DocModel.FileName = "NA";
                    DocModel.FilePath = "NA";
                }
                DocModel.UploadDate = DateTime.Now;
                DocModel.Status = 1;
                DocModel.Remarks = remarks;
                repoPQVerifiedUploadCaseDoc.AddPQVerifiedUploadCaseDoc(DocModel);
                repoPQVerifiedUploadCaseDoc.SaveChanges();

                return proImg;
            }
            catch (Exception ex)
            {
                string str = ex.Message;
                throw;
            }
        }


        [HttpGet]
        public ActionResult MISExportss()
        {
            string Designation = Session["Designation"].ToString();
            List<MISExport> mISExport = new List<MISExport>();
            if (Designation == "Team Leader-DE")
            {
                DataTable dt = new DataTable();
                dt = cc.Get_Export_Excel_DE();

                ViewBag.record = dt.Rows.Count;
                foreach (DataRow dr in dt.Rows)
                {
                    mISExport.Add(
                        new MISExport
                        {
                            TMFirstName = dr["TMFirstName"].ToString(),
                            InsuffBucket = dr["Insuff_clear"].ToString(),
                            Rejection = dr["DE_Rejection"].ToString(),
                            Research_Clear = dr["Research_Clear"].ToString(),
                            YTR_Clear = dr["YTR_Clear"].ToString(),
                            DE_Scanning = dr["DE_Scanning"].ToString(),
                            DE_Pending = dr["DE_Pending"].ToString(),
                            QCBucket = dr["QC_Bucket"].ToString(),
                            //Research_WIP = dr["Research_WIP"].ToString(),
                            // YTR = dr["YTR"].ToString(),
                            Total_WIP = dr["Total_WIP"].ToString(),
                            Todays_Closure = dr["Todays_Closure"].ToString(),
                            Assigned_Today = dr["Assigned_Today"].ToString(),
                            Old_Assigned = dr["Old_Assigned"].ToString(),
                        }
                        );
                }

                ViewBag.InsuffBucket = mISExport.Sum(T => Convert.ToInt32(T.InsuffBucket));
                ViewBag.Rejection = mISExport.Sum(T => Convert.ToInt32(T.Rejection));
