        public ActionResult GetMISTATInfoDE(string Type = "")
        {
            List<InfoMISTAT> infoMISTATs = new List<InfoMISTAT>();
            DataTable dt = new DataTable();
            Session["Type"] = Type;
            dt = cc.MISInfoDE(Type);
            foreach (DataRow dataRow in dt.Rows)
            {
                infoMISTATs.Add(new InfoMISTAT
                {
                    SecuritasID = dataRow["Securitas ID"].ToString(),
                    CandidateName = dataRow["Candidate Name"].ToString(),
                    CheckID = dataRow["UniqueComponentID"].ToString(),
                    SubCheckName = dataRow["SubCheckName"].ToString(),
                    TMFirstName = dataRow["TMFirstName"].ToString(),
                    ClientName = dataRow["ClientName"].ToString(),
                    CreatedOn = dataRow["Created On"].ToString(),
                    InternalOutDate = dataRow["InternalOutDate"].ToString(),
                    OutDate = dataRow["OutDate"].ToString(),
                    SpocName = dataRow["SpocName"].ToString(),
                    ReWorkCheckStatus = dataRow["ReWorkCheckStatus"].ToString(),
                    CheckStatus = dataRow["CheckStatus"].ToString(),
                    CheckType = dataRow["CheckType"].ToString(),
                    TLAllocationDate = dataRow["TLAllocationDate"].ToString(),
                    TMAllocationDate = dataRow["TMAllocationDate"].ToString(),
                    completedDate = dataRow["completedDate"].ToString(),
                    LastInsuffClearDate = dataRow["LastInsuffClearDate"].ToString(),

                }
                );
            }
            ViewBag.record = dt.Rows.Count;
            ViewBag.Heading = Type + " Data";
            return View(infoMISTATs);
        }

