        [HttpPost]
        public ActionResult SubmitOrganizationDetailsforPV(OrganizationDetailsModel model)
        {
            if (model != null)
            {

                string CombineAddress = model.WebsiteAddress + "__" + model.DocumentAddress + "__" + model.ROCAddress + "__" + model.BGCAddress;
                ClientCustomize cc = new ClientCustomize();
                DataTable dt1 = cc.GetPersonalRowId(model.SecuritasID);
                var PersonalRowID = Convert.ToInt32(dt1.Rows[0]["PersonalRowID"]);
                cc.AddPhysicalVerificationData(model.UniqueCheckID, CombineAddress, model.Remarks, model.state, model.city);
                cc.UpdateCheckStatus(PersonalRowID, Convert.ToInt16(model.SubCheckRowId), 1, 28, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                clsCommonMethods.AddCheckActionHistory(PersonalRowID, Convert.ToInt16(model.SubCheckRowId), "Allocated-PV-Mgr", "");
                DataTable dts = cc.GetReferenceDetailforYTR(model.SecuritasID);
                if (dts.Rows.Count > 0)
                {
                    int clientRowId = 0;
                    clientRowId = Convert.ToInt32(dts.Rows[0]["ClientRowID"].ToString());
                    new API().UpdateAPICheckStatus(clientRowId.ToString().Trim(), PersonalRowID, Convert.ToInt32(model.SubCheckRowId), "Allocated to Manager PV"); //APICheckStatus
                }

                return Json(new { success = true, message = "Data saved successfully!" });
            }


            return Json(new { success = true, message = "Invalid data." });


        }

