        [HttpGet]
        public JsonResult GetOnlineLInkSearching(int id)
        {
            var dt = cc.getOnlineSearchLinkById(id);
            OnlineLinkSearching data = new OnlineLinkSearching();
            data.Id = Convert.ToInt32(dt.Rows[0]["Id"].ToString());
            data.CollageName = dt.Rows[0]["CollegeName"].ToString();
            data.UniversityName = dt.Rows[0]["UniversityName"].ToString();
            data.CourseName = dt.Rows[0]["Course"].ToString();
            data.YearOfPassing = Convert.ToInt32(dt.Rows[0]["YearofPassing"].ToString());
            data.RollNo = dt.Rows[0]["RollNo"].ToString();
            data.ResultScore = dt.Rows[0]["ResultSource"].ToString();
            data.Convocation = dt.Rows[0]["Convocation"].ToString();
            data.Year = Convert.ToInt32(dt.Rows[0]["Year"].ToString());
            data.Link = dt.Rows[0]["Link"].ToString();

            var response = new
            {
                Data = data,
                IsEdit = true
            };
            return Json(response, JsonRequestBehavior.AllowGet);
        }

        [HttpPost]
        public ActionResult OnlineLInkSearching(string collageName, string UniversityName, string courseName, int yearofPassing, string rollNo, string resultSource, string convocation, int year, string link, FormCollection form, int id = 0)
        {
            ClientCustomize cc = new ClientCustomize();

            string a = form["collageid"].Replace(",", "");
            if (a != "")
            {
                id = Convert.ToInt32(a);
            }

            if (id == 0)
            {
                int rst = cc.InsertOnlineLinkSearching(collageName, UniversityName, courseName, yearofPassing, rollNo, resultSource, convocation, year, link);
            }
            else
            {
                int rst = cc.UpdateOnlineLinkSearching(id, collageName, UniversityName, courseName, yearofPassing, rollNo, resultSource, convocation, year, link);


            }

            return RedirectToAction("OnlineLInkSearching");
        }

