        [HttpGet]
        public ActionResult MISExportSpecialCheck()
        {
            string Designation = Session["Designation"].ToString();
            List<MISExport> mISExport = new List<MISExport>();
            if (Designation == "Manager-SPL")
            {
                DataTable dt = new DataTable();
                dt = cc.Get_Export_Excel_Special();

                ViewBag.record = dt.Rows.Count;
                foreach (DataRow dr in dt.Rows)
                {
                    mISExport.Add(
                        new MISExport
                        {
                            TMFirstName = dr["TMFirstName"].ToString(),
                            InsuffBucket = dr["UnAllocated"].ToString(),
                            Rejection = dr["Rejection"].ToString(),
                            RevertReceived = dr["Revert_Received"].ToString(),
                            QCBucket = dr["QC_Bucket"].ToString(),
                            Total_WIP = dr["Total_WIP"].ToString(),
                            Todays_Closure = dr["Todays_Closure"].ToString(),
                            Assigned_Today = dr["Assigned_Today"].ToString(),
                            OutOfTat = dr["Out_Of_Tat"].ToString(),
                        }
                        );
                }



