        public string BulkRenderViewToString(ControllerContext context, string viewPath, int personalRowid, bool partial = false)
        {
            ReportViewModel model = new ReportViewModel();
            model = BulkGenerateReport(personalRowid);



            // first find the ViewEngine for this view
            ViewEngineResult viewEngineResult = null;
            if (partial)
                viewEngineResult = ViewEngines.Engines.FindPartialView(context, viewPath);
            else
                viewEngineResult = ViewEngines.Engines.FindView(context, viewPath, null);

            if (viewEngineResult == null)
                throw new FileNotFoundException("View cannot be found.");

            // get the view and attach the model to view data
            var view = viewEngineResult.View;
            context.Controller.ViewData.Model = model;

            string result = null;

            using (var sw = new StringWriter())
            {
                var ctx = new ViewContext(context, view, context.Controller.ViewData, context.Controller.TempData, sw);
                view.Render(ctx, sw);
                result = sw.ToString();
            }

            return result;
        }
        private void MasterArtifactMappingsApproving(int personalrowid)
        {
            ClientCustomize cc = new ClientCustomize();
            var DTCheckList = cc.GetPQCandidateCheckList(personalrowid);
            if (DTCheckList.Rows.Count > 0)
            {
                for (int i = 0; i < DTCheckList.Rows.Count; i++)
                {
                    int clientRowid = Convert.ToInt32(DTCheckList.Rows[i]["ClientRowID"]);
                    int CheckFamilyRowID = Convert.ToInt32(DTCheckList.Rows[i]["CheckFamilyRowID"]);
                    if (CheckFamilyRowID == 2)
                    {
                        int SubCheckFamilyID = Convert.ToInt32(DTCheckList.Rows[i]["SubCheckFamilyID"]);
                        IEnumerable<MasterArtifactMappingsOrdering> objMasterArtifactMappingsOrdering;
                        objMasterArtifactMappingsOrdering = repoReportQC.GetMasterArtifactMappingsOrdering("", clientRowid, CheckFamilyRowID);
                        if (objMasterArtifactMappingsOrdering.Count() > 0)
                        {
                            foreach (var x in objMasterArtifactMappingsOrdering)
                            {
                                cc.UpdateApproveArtifacts(personalrowid, SubCheckFamilyID, x.DocumentType, x.DocumentSeqNo);
                            }
                        }
                    }
                }
            }
        }
