        [HttpGet]
        public ActionResult UploadBulkReport(string action)
        {
            string UploadReportList = "";
            List<PersonalDocDetails> objlst = new List<PersonalDocDetails>();
            ViewBag.errormsg = "";
            ViewBag.PersonalDocDetails = objlst;

            return View();
        }

        [HttpPost]
        public ActionResult UploadBulkReport(FormCollection frm, string action)
        {
            try
            {
                string CompanyRefNoList = frm["CompanyRefNoList"].ToString();
                string dbvalue = CompanyRefNoList.Replace("\r\n", ",");
                string[] kk = dbvalue.Split(',');
                string UploadReportList = "";
                List<PersonalDocDetails> objlst = new List<PersonalDocDetails>();
                ViewBag.errormsg = "";

                UploadReportList = AutoGenerateReport(kk);
                ViewBag.errormsg = "Done";
                ClientCustomize cc = new ClientCustomize();
                var tbldb = cc.GetBulkReportDocDetails(UploadReportList);

                if (tbldb.Rows.Count > 0)
                {
                    objlst = (from DataRow dr in tbldb.Rows
                              select new PersonalDocDetails()
                              {
                                  PersonalRowID = Convert.ToString(dr["PersonalRowID"]),
                                  FileName = Convert.ToString(dr["FileName"]),
                                  Remarks = Convert.ToString(dr["Remarks"]),
                                  CompanyRefNo = Convert.ToString(dr["CompanyRefNo"]),
                                  CandidateFullName = Convert.ToString(dr["CandidateFullName"])
                              }).ToList();

                }
                ViewBag.PersonalDocDetails = objlst;
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }

            return View();
        }

        public void CandidatePdfListsNew(int id, int dpi, int clientrowid = 0)
        {
            string DocPath = ConfigurationManager.AppSettings["provideddocuments"].ToString();
            //var CandidatePdfList = <IEnumerable>
            // IEnumerable <object> CandidatePdfList = iEnumerable.Empty<object>();
            IEnumerable<CandidateAllDocumentListViewModel> CandidatePdfList = null;



            if (clientrowid == 327)
            {
                CandidatePdfList = repoReportQC.GetCandidatePdfListFor_Conversion_wipro(id);

            }
            else
            {
                CandidatePdfList = repoReportQC.GetCandidatePdfListFor_Conversion(id);

            }
            // CandidatePdfList = repoReportQC.GetCandidatePdfListFor_Conversion(id);
            foreach (var item in CandidatePdfList)
            {
                SautinSoft.PdfFocus f = new SautinSoft.PdfFocus();

                //f.Serial = "10273316474"; //License for development machine
                f.Serial = "80027423579";
                //f.OpenPdf("D:wwwroot2\\Documents\\CandidateDocuments\\ProvidedDocuments\\" + item.DocFile);

                f.OpenPdf(Server.MapPath(DocPath + item.DocFile));
                if (f.PageCount > 0)
                {
                    string jpgFileName = item.DocFile.Replace(".pdf", "");
                    string ImageName = string.Empty;
                    for (int i = 1; i <= f.PageCount; i++)
                    {
                        ImageName += jpgFileName + i + ".jpg,";
                    }
                    if (!string.IsNullOrEmpty(ImageName) && ImageName.Length > 0)
                    {
                        ImageName = ImageName.Substring(0, ImageName.Length - 1);
                        bool res = repoReportQC.UpdateImageName(item.VerifiedUploadRowID, ImageName);
                        if (res)
                        {
                            //int width = 644; // Width in Px
                            //int height = 911; // Height in Px
                            f.ImageOptions.ImageFormat = System.Drawing.Imaging.ImageFormat.Jpeg;
                            //f.ImageOptions.Resize(new System.Drawing.Size { Width = width, Height = height }, false);
                            f.ImageOptions.Dpi = dpi;
                            f.ToImage(Server.MapPath(DocPath), jpgFileName);
                        }
                        //cc.updateReportPDFToImagePages(item.VerifiedUploadRowID, ImageName);
                    }
                }
            }
        }
        public string AutoGenerateReport(string[] kk)
        {
            string UploadReportList = "";

            try
            {
                foreach (var RefId in kk)
                {
                    string CompanyRefNo = RefId.ToString();
                    var Infotbl = cc.GetpersonaldatafromCompanyRefNoNew(CompanyRefNo);
                    if (Infotbl.Rows.Count > 0)
                    {
                        int PersonalRowid = Convert.ToInt32(Infotbl.Rows[0]["PersonalRowID"]);

                        cc.UpdateCheckstatusbulkPersonalrowId(PersonalRowid, Convert.ToInt32(Session["TeamMemberRowID"]));
                        string html = BulkRenderViewToString(ControllerContext, "~/views/Verification/ReportMain.cshtml", PersonalRowid, true);
                        string IronKey = System.Configuration.ConfigurationManager.AppSettings["IronKey"].ToString();
                        var Renderer = new IronPdf.HtmlToPdf();
                        IronPdf.License.LicenseKey = IronKey;
                        //IronPdf.License.LicenseKey = "IRONPDF-MYLICENSE-KEY-1EF01";
