                        Renderer.RenderingOptions.MarginTop = 3;
                        Renderer.RenderingOptions.MarginLeft = 5;
                        Renderer.RenderingOptions.MarginRight = 5;
                        Renderer.RenderingOptions.MarginBottom = 3;

                        var PDF = Renderer.RenderHtmlAsPdf(html);

                        string FldPathDoc = string.Empty;
                        FldPathDoc = ConfigurationManager.AppSettings["CandidateReportdoc".Trim().ToLower()].ToString();
                        string ImgName = CompanyRefNo.ToString() + ".pdf";
                        string fileSavePath = Server.MapPath(FldPathDoc + ImgName);
                        PDF.SaveAs(fileSavePath);

                        cc.UpdateCheckstatusbulkPersonalrowId(PersonalRowid, Convert.ToInt32(Session["TeamMemberRowID"]));

                        var DTColorCode = cc.CaseColorCodeForReportNew(PersonalRowid);
                        string CaseColorName = Convert.ToString(DTColorCode.Rows[0]["colorname"]);
                        cc.UploadReportDetails(PersonalRowid, ImgName, "", "Completed");

                        cc.finalReportDetail(PersonalRowid, Convert.ToInt32(Session["TeamMemberRowID"]), "Final", CaseColorName, ImgName, 1);


                        UploadReportList = UploadReportList + "," + PersonalRowid.ToString();
                    }

                }
                if (UploadReportList.Substring(0, 1) == ",")
                {
                    Session["PRowIds"] = UploadReportList.Substring(1, UploadReportList.Length - 1);
                }
            }
            catch (Exception ex)
            {
                return UploadReportList;
            }

            return UploadReportList;
        }

