        [HttpPost]
        public ActionResult SendDigiLockerLink(FormCollection frm)
        {
            string UniqueComponentID = Convert.ToString(frm["UniqueComponentID"]).Trim();
            string Action = Convert.ToString(frm["Action"]);
            string EmailID = "";
            string CandidateFullName = "";
            string ClientName = "";
            string MobileNo = "";
            string CompanyRefNo = "";
            string QualificationName = "";
            DataTable dt = ObjAPI.Get_Personal_University_Details(UniqueComponentID);
            if (dt.Rows.Count > 0)
            {
                ClientName = Convert.ToString(dt.Rows[0]["ClientName"]);
                EmailID = Convert.ToString(dt.Rows[0]["EmailID"]);
                CandidateFullName = Convert.ToString(dt.Rows[0]["CandidateFullName"]);
                CompanyRefNo = Convert.ToString(dt.Rows[0]["CompanyRefNo"]);
                MobileNo = Convert.ToString(dt.Rows[0]["MobileNo"]);
                QualificationName = Convert.ToString(dt.Rows[0]["SubCheckName"]);
                if (Action == "SEARCH")
                {
                    var codeVerifierDT = ObjAPI.Sp_GetDigiLockerUserPendinDetails(UniqueComponentID);
                    if (codeVerifierDT.Rows.Count > 0)
                    {
                        ViewBag.msg = "Link already sent";
                    }
                }
                else
                {
                    var codeVerifierDT = ObjAPI.Sp_GetDigiLockerUserPendinDetails(UniqueComponentID);
                    if (codeVerifierDT.Rows.Count > 0)
                    {
                        ViewBag.msg = "Link already sent";
                    }
                    else
                    {
                        int randomByte = RandomIntFromInterval(32, 96);
                        string codeVerifier = GenerateCodeVerifier(randomByte);
                        var codeChallenge = GenerateCodeChallenge(codeVerifier);

                        string NSSOauthorizeURL = "https://digilocker.meripehchaan.gov.in/public/oauth2/1/authorize?response_type=code&client_id=EY2460D287&state=" + UniqueComponentID + "&redirect_uri=";
                        NSSOauthorizeURL = NSSOauthorizeURL + "https://bgv.securitas-india.com/Account/DigiLockerRedirect_uri";
                        NSSOauthorizeURL = NSSOauthorizeURL + "&code_challenge=" + codeChallenge.Result;
                        NSSOauthorizeURL = NSSOauthorizeURL + "&code_challenge_method=S256&scope=files.issueddocs+files.uploadeddocs&pla=Y";

                        bool status = SendAlertMassageForDigiLocker(CompanyRefNo, NSSOauthorizeURL, dt);
                        if (status)
                        {
                            int rst = ObjAPI.InsertDigiLockerUserDetails(UniqueComponentID, NSSOauthorizeURL, codeVerifier, 0);
                            ViewBag.msg = "Link sent successfully !";
                        }
                        else
                        {
                            MessageStatus objMessage = new MessageStatus();
                            WhatsAppAPI onj = new WhatsAppAPI();
                            objMessage = onj.SendWhatsAppMessage("+91" + MobileNo, "digilocker_verification_temp", CandidateFullName, "media_template", QualificationName, CompanyRefNo, NSSOauthorizeURL);

                            ViewBag.msg = "Email failed. SMS sent successfully.!";
                        }

                    }
                }
            }
            else
            {
                ViewBag.msg = "Unique component id not found";

            }
            return View();
        }

