        public JsonResult GetWorldCheckStatus()
        {

            List<WorldCheckStatuss> listObj = new List<WorldCheckStatuss>();
            ClientCustomize CC = new ClientCustomize();
            var DTStatus = CC.getWorldCheckstatuses();
            if (DTStatus.Rows.Count > 0)
            {
                listObj = (from DataRow rw in DTStatus.Rows
                           select new WorldCheckStatuss
                           {
                               StatusId = Convert.ToString(rw["statusesId"]),
                               StatusName = Convert.ToString(rw["statusesName"])

                           }).ToList();
            }


            return Json(listObj, JsonRequestBehavior.AllowGet);
        }

