        public bool WorldChecksReviewresults(string ResultId, string StatusesId, string ReasonsId, string risksId, string case_system_id, string Remark)
        {
            var result1 = false;
            string Url = "https://api.risk.lseg.com/screening/v2/cases/" + case_system_id + "/results/review";
            refinitivAPI refinitivAPI = new refinitivAPI();
            string Rbody = "{\n    \"resultIds\": [\n        \"" + ResultId + "\"\n    ],\n    \"remark\": \"not match\"\n}";

            var result = refinitivAPI.PutRequest(Rbody, Url, Server.MapPath("~\\APIErrorLogs\\Logfiles"));

            if (result)
            {
                string Url1 = "https://api.risk.lseg.com/screening/v2/cases/" + case_system_id + "/results/resolution";
                string body = "{\n    \"resultIds\": [\n        \"" + ResultId + "\"\n    ],\n    \"statusId\": \"" + StatusesId + "\",\n    \"riskId\": \"" + risksId + "\",\n    \"reasonId\": \"" + ReasonsId + "\",\n    \"resolutionRemark\": \"" + Remark + "\"\n}";

                result1 = refinitivAPI.PutRequest(body, Url1, Server.MapPath("~\\APIErrorLogs\\Logfiles"));
            }
            return result1;


