        [HttpGet]
        public ActionResult UploadfakelistDetaisbyExceledu(string ErrMessage = "")
        {
            BindClientList();
            return View();

        }

        [HttpPost]
        public ActionResult UploadfakelistDetaisbyExceledu(HttpPostedFileBase file, FormCollection formCollection)
        {
            try
            {
                if (file != null)
                {
                    string fileExtension = Path.GetExtension(file.FileName).ToLower();
                    if (fileExtension != ".xls" && fileExtension != ".xlsx")
                    {
                        ViewBag.ErrorMsg = "Please upload a valid Excel file (.xls or .xlsx).";
                        return View();
                    }
                    string fileName = Path.GetFileName(file.FileName);
                    string filePath = Path.Combine(Server.MapPath("~/Emailers"), fileName);
                    file.SaveAs(filePath);

                    int result = UploadfakelistExceledu(filePath);
                    if (result <= 0)
                    {
                        ViewBag.ErrorMsg = "Error updating data.";
                        if (System.IO.File.Exists(filePath))
                        {
                            System.IO.File.Delete(filePath);
                        }
                        return View();
                    }

                    ViewBag.ErrorMsg = "successfully.";
                    if (System.IO.File.Exists(filePath))
                    {
                        System.IO.File.Delete(filePath);
                    }
                }
                else
                {
                    ViewBag.ErrorMsg = "Please select an Excel file to upload.";
                }
            }
            catch (Exception ex)
            {
                ViewBag.ErrorMsg = "Error: " + ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), ex.Message, ex.StackTrace);
            }

            return View();
        }

        public int UploadfakelistExceledu(string filePath)
        {
            try
            {

                string fileExtension = Path.GetExtension(filePath).ToLower();
                string conStr = "";
                switch (fileExtension)
                {
                    case ".xls":
                        conStr = ConfigurationManager.ConnectionStrings["Excel03ConString"].ConnectionString;
                        break;
                    case ".xlsx":
                        conStr = ConfigurationManager.ConnectionStrings["Excel07ConString"].ConnectionString;
                        break;
                    default:
                        throw new InvalidOperationException("Invalid file format. Only .xls and .xlsx are allowed.");
                }

                conStr = string.Format(conStr, filePath, "YES");

                using (OleDbConnection connExcel = new OleDbConnection(conStr))
                {
                    connExcel.Open();
                    DataTable dtExcelSchema = connExcel.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, null);
                    string sheetName = dtExcelSchema.Rows[0]["TABLE_NAME"].ToString();
                    connExcel.Close();

                    OleDbCommand cmdExcel = new OleDbCommand($"SELECT * FROM [{sheetName}]", connExcel);
                    OleDbDataAdapter oda = new OleDbDataAdapter(cmdExcel);
                    DataTable dt = new DataTable();
                    oda.Fill(dt);
                    connExcel.Close();

                    int updatedCount = 0;
                    if (dt.Rows.Count > 0)
                    {
                        foreach (DataRow row in dt.Rows)
                        {
                            string clientname = row["clientname"].ToString().Trim();
                            string InstituteName = row["InstituteName"].ToString().Trim();
                            string CompeteAddress = row["CompeteAddress"].ToString().Trim();
                            string ReasonforSuspact = row["ReasonforSuspact"].ToString().Trim();
                            string IdentifiedOn = row["IdentifiedOn"].ToString().Trim();
                            string AdditionalRemarks = row["AdditionalRemarks"].ToString().Trim();


                            ClientCustomize cc = new ClientCustomize();
                            cc.UpdatefakelisteduByExcel(clientname, InstituteName, CompeteAddress, ReasonforSuspact, IdentifiedOn, AdditionalRemarks);
                            updatedCount++;
                        }
                    }

                    return updatedCount;
                }
            }
            catch (Exception ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), ex.Message, ex.StackTrace);
                return 0;
            }
        }

