        [HttpGet]
        public ActionResult GetOfflineIdentityChecksReports()
        {
            return View();
        }
        [HttpPost]
        public ActionResult GetOfflineIdentityChecksReports(FormCollection frm, HttpPostedFileBase UploadFile)
        {
            try
            {
                List<InstantIDCheckResultStatus> IDNoNotExistLst = new List<InstantIDCheckResultStatus>();
                try
                {
                    var Timestamp = new DateTimeOffset(DateTime.UtcNow).ToUnixTimeSeconds().ToString();
                    string path = ConfigurationManager.AppSettings["provideddocuments"].ToString();
                    string ext = Path.GetExtension(UploadFile.FileName).ToLower();
                    string filename = "Id_" + Timestamp + ext;
                    string filePath = path + filename;
                    filePath = Server.MapPath(path + filename);
                    UploadFile.SaveAs(filePath);
                    var IDLst = DownloadOfflineBulkInstantIDCheckArtifact(filePath, ext, "Yes");
                    IDNoNotExistLst = IDLst;
                    ViewBag.PersonalDocDetails = IDLst;

                    ViewBag.ErrorMsg = Convert.ToString(IDLst.Count) + " ID Number Process !";
                    List<ClientBulkDownlode> f = new List<ClientBulkDownlode>();
                    foreach (var item in IDNoNotExistLst)
                    {
                        ClientBulkDownlode tt = new ClientBulkDownlode();
                        string fname = Server.MapPath(path + item.FileName);
                        FileInfo fi1 = new FileInfo(fname);
                        tt.fileDetails = fi1;
                        tt.FileDownloadName = item.FileName;
                        f.Add(tt);
                    }
                    using (var memoryStream = new MemoryStream())
                    {
                        using (var ziparchive = new ZipArchive(memoryStream, ZipArchiveMode.Create, true))
                        {
                            foreach (ClientBulkDownlode fo in f)
                            {
                                try
                                {
                                    ziparchive.CreateEntryFromFile(fo.fileDetails.FullName, fo.FileDownloadName);
                                }
                                catch (Exception Ex)
                                {
                                    ViewBag.ErrorMsg = "Invalid paramerter value";
                                    clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                                }
                            }
                        }
                        return File(memoryStream.ToArray(), "application/zip", "BGVReports.zip");
                    }

                }
                catch (Exception Ex)
                {
                    ViewBag.ErrorMsg = Ex.Message;
                    clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                    return RedirectToAction("GetOfflineIdentityChecksReports", new { errorMsg = Ex.Message });
                }
                //return View(IDNoNotExistLst);

            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View();
        }
        private List<InstantIDCheckResultStatus> DownloadOfflineBulkInstantIDCheckArtifact(string FilePath, string Extension, string isHDR)
        {
            int Count = 0;
            ClientCustomize cc = new ClientCustomize();
            List<InstantIDCheckResultStatus> UANNoNotExistLst = new List<InstantIDCheckResultStatus>();

            try
            {
                string conStr = "";
                switch (Extension)
                {
                    case ".xls": //Excel 97-03
                        conStr = ConfigurationManager.ConnectionStrings["Excel03ConString"].ConnectionString;
                        break;
                    case ".xlsx": //Excel 07
                        conStr = ConfigurationManager.ConnectionStrings["Excel07ConString"].ConnectionString;
                        break;
                }
                conStr = String.Format(conStr, FilePath, isHDR);
                OleDbConnection connExcel = new OleDbConnection(conStr);
                OleDbCommand cmdExcel = new OleDbCommand();
                OleDbDataAdapter oda = new OleDbDataAdapter();
                DataTable dt = new DataTable();

                cmdExcel.Connection = connExcel;

                //Get the name of First Sheet
                connExcel.Open();
                DataTable dtExcelSchema;
                dtExcelSchema = connExcel.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, null);
                string SheetName = dtExcelSchema.Rows[0]["TABLE_NAME"].ToString();
                connExcel.Close();

                connExcel.Open();
                cmdExcel.CommandText = "SELECT * From [" + SheetName + "]";
                oda.SelectCommand = cmdExcel;
                oda.Fill(dt);
                connExcel.Close();


                if (dt.Rows.Count > 0)
                {

                    string MobileNo = string.Empty;
                    string DocName = string.Empty;
                    string PRowId = string.Empty;
