                AddUANCheckDetailsByAPI API = new AddUANCheckDetailsByAPI();
                Obj = API.GetLlmtechAadhar(0, 0, aadhaarNo, RefNo, APIPath);
                int teamMemerRowId = Convert.ToInt16(Session["TeamMemberRowID"]);
                if (Obj.success)
                {
                    string body = string.Empty;
                    using (StreamReader reader = new StreamReader(Server.MapPath("~/Emailers/llmtechAadhaar.html")))
                    {
                        body = reader.ReadToEnd();
                    }
                    body = body.Replace("{companyRefNo}", RefNo);
                    body = body.Replace("{aadhaar_number}", aadhaarNo);
                    body = body.Replace("{age_range}", Convert.ToString(Obj.data.age_range));
                    body = body.Replace("{state}", Convert.ToString(Obj.data.state));
                    body = body.Replace("{gender}", Convert.ToString(Obj.data.gender));
                    string isIssued = "False";
                    if (Obj.data.is_mobile)
                    {
                        isIssued = "True";
                    }
                    body = body.Replace("{last_digits}", Convert.ToString(Obj.data.last_digits_of_mobile));
                    body = body.Replace("{is_mobile}", isIssued);
                    body = body.Replace("{verifiedDate}", DateTime.Now.Date.ToString("dd-MMM-yyyy"));
                     FileName = SaveOfflineInstantCheckDocs(aadhaarNo, "Aadhaar", "provideddocuments", body, RefNo);
                }
            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return FileName;
        }

        public string GetLlmtechAadhaarLive(int Pid,int Sid,int Cid,string aadhaarNo, string RefNo,string CandidateName)
        {
            string FileName = "";
            AadharRootobject Obj = new AadharRootobject();
            try
            {
                var ErrorPath = Server.MapPath("~\\ErrorLogs\\Logfiles");
                var APIPath = Server.MapPath("~\\APILogs\\Logfiles");
                ClientCustomize CC = new ClientCustomize();
                AddUANCheckDetailsByAPI API = new AddUANCheckDetailsByAPI();
                Obj = API.GetLlmtechAadhar(Pid, Sid, aadhaarNo, RefNo, APIPath);
                int teamMemerRowId = Convert.ToInt16(Session["TeamMemberRowID"]);
                if (Obj.success)
                {
                    string body = string.Empty;
                    using (StreamReader reader = new StreamReader(Server.MapPath("~/Emailers/llmtechAadhaar.html")))
                    {
                        body = reader.ReadToEnd();
                    }
                    body = body.Replace("{companyRefNo}", RefNo);
                    body = body.Replace("{aadhaar_number}", aadhaarNo);
                    body = body.Replace("{age_range}", Convert.ToString(Obj.data.age_range));
                    body = body.Replace("{state}", Convert.ToString(Obj.data.state));
                    body = body.Replace("{gender}", Convert.ToString(Obj.data.gender));
                    string isIssued = "False";
                    if (Obj.data.is_mobile)
                    {
                        isIssued = "True";
                    }
                    body = body.Replace("{last_digits}", Convert.ToString(Obj.data.last_digits_of_mobile));
                    body = body.Replace("{is_mobile}", isIssued);
                    body = body.Replace("{verifiedDate}", DateTime.Now.Date.ToString("dd-MMM-yyyy"));

                    FileName = SavePQVerifiedUploadUANDoc(Convert.ToInt32(Pid), Convert.ToInt16(Sid), "Verified", "Aadhaar", "provideddocuments", body, "Aadhaar Verified", 0, RefNo);
                  
                    var adhardt = CC.Antecedents_client_select_form(Cid, Sid, "Operation", "Check");
                    if (adhardt.Rows.Count > 0)
                    {
                        for (int i = 0; i < adhardt.Rows.Count; i++)
                        {
                            int Antecedents = Convert.ToInt32(adhardt.Rows[i]["AntecedentsRowID"]);
                            int rst = CC.InsertUpdateAadhaarNumberCheckDetails(Convert.ToInt32(Pid), Sid, Antecedents, Cid, aadhaarNo, CandidateName);
                        }
                    }
                    cc.UpdateCheckStatus(Convert.ToInt32(Pid), Sid, 1, 107, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                    cc.UpdateTmMemberID(Convert.ToInt32(Pid), Sid);

                    clsCommonMethods.AddCheckActionHistory(Convert.ToInt32(Pid), Convert.ToInt16(Sid), "Completed", "Verification recieve throught integration");
                }
            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return FileName;
        }

        public string InterimWithCRCGenerateReport(int PersonalRowid, int SubCheckRowId)
        {
            string UploadReportList = "";
            try
            {
                var Data = repoPQPersonal.GetPQPersonalInfoForSession(PersonalRowid);
                string html = InterimWithCRCRenderViewToString(ControllerContext, "~/views/Verification/ReportMain.cshtml", PersonalRowid, true);
                string IronKey = System.Configuration.ConfigurationManager.AppSettings["IronKey"].ToString();
                var Renderer = new IronPdf.HtmlToPdf();
                IronPdf.License.LicenseKey = IronKey;
                //IronPdf.License.LicenseKey = "IRONPDF-MYLICENSE-KEY-1EF01";
                Renderer.RenderingOptions.PaperSize = IronPdf.Rendering.PdfPaperSize.A4;
                Renderer.RenderingOptions.MarginTop = 3;
                Renderer.RenderingOptions.MarginLeft = 5;
                Renderer.RenderingOptions.MarginRight = 5;
                Renderer.RenderingOptions.MarginBottom = 3;

                var PDF = Renderer.RenderHtmlAsPdf(html);

                string FldPathDoc = string.Empty;
                FldPathDoc = ConfigurationManager.AppSettings["CandidateReportdoc".Trim().ToLower()].ToString();
                string ImgName = Data.CompanyRefNo.ToString() + ".pdf";
                string fileSavePath = Server.MapPath(FldPathDoc + ImgName);
                PDF.SaveAs(fileSavePath);
                var DTColorCode = cc.CaseColorCodeForReportNew(PersonalRowid);
                string CaseColorName = Convert.ToString(DTColorCode.Rows[0]["colorname"]);
                cc.UploadReportDetails(PersonalRowid, ImgName, "Completed", "");
                cc.finalReportDetail(PersonalRowid, Convert.ToInt32(Session["TeamMemberRowID"]), "Interim", CaseColorName, ImgName, 1);
            }
            catch (Exception ex)
            {
                return UploadReportList;
            }

            return UploadReportList;
        }

