        public string InterimWithCRCRenderViewToString(ControllerContext context, string viewPath, int personalRowid, bool partial = false)
        {
            ReportViewModel model = new ReportViewModel();
            model = InterimCRCGenerateReport(personalRowid);

            // first find the ViewEngine for this view
            ViewEngineResult viewEngineResult = null;
            if (partial)
                viewEngineResult = ViewEngines.Engines.FindPartialView(context, viewPath);
            else
                viewEngineResult = ViewEngines.Engines.FindView(context, viewPath, null);

            if (viewEngineResult == null)
                throw new FileNotFoundException("View cannot be found.");

            // get the view and attach the model to view data
            var view = viewEngineResult.View;
            context.Controller.ViewData.Model = model;

            string result = null;

            using (var sw = new StringWriter())
            {
                var ctx = new ViewContext(context, view, context.Controller.ViewData, context.Controller.TempData, sw);
                view.Render(ctx, sw);
                result = sw.ToString();
            }

            return result;
        }

        private void MasterArtifactMappingsApproving(int personalrowid, int CheckFamilyRowID, int SubCheckFamilyID, string colorName, int clientRowid)
        {
            IEnumerable<MasterArtifactMappingsOrdering> objMasterArtifactMappingsOrdering;
            objMasterArtifactMappingsOrdering = repoReportQC.GetMasterArtifactMappingsOrdering(colorName, clientRowid, CheckFamilyRowID);
            if (objMasterArtifactMappingsOrdering.Count() > 0)
            {
                foreach (var x in objMasterArtifactMappingsOrdering)
                {
                    cc.UpdateApproveArtifacts(personalrowid, SubCheckFamilyID, x.DocumentType, x.DocumentSeqNo);
                }
            }
        }

        [HttpGet]
        public ActionResult BulkFaceMatchClosure()
        {
            ViewBag.PersonalDocDetails = null;
            return View();
        }
        [HttpPost]
        public ActionResult BulkFaceMatchClosure(IEnumerable<HttpPostedFileBase> docFile, HttpPostedFileBase xlsFile)
        {
            List<PersonalDocDetails> objlst = new List<PersonalDocDetails>();
            string[] allowedExtensions = { ".jpg", ".jpeg", ".png", ".JPG", ".JPEG", ".PNG" };

            string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["provideddocuments"].ToString();
            string FldPathExlx = System.Configuration.ConfigurationManager.AppSettings["ClientUploadedDocuments"].ToString();
            FldPathDoc = Server.MapPath(FldPathDoc);
            if (docFile != null)
            {
                foreach (var file in docFile)
                {
                    if (file != null && file.ContentLength > 0)
                    {
                        var file_Name = Path.GetFileName(file.FileName).Split('_');
                        string UniqueId = file_Name[0].ToString();
                        string DocType = file_Name[1].ToString().Split('.')[0];
                        string fileName = Path.GetFileName(file.FileName);

                        string FinalFileName = fileName.Replace("-", "_").Trim();
                        string extension = Path.GetExtension(file.FileName);
                        if (allowedExtensions.Contains(extension))
                        {
                            var DT = cc.GetPQCandidateChecksfromCheckUniqueID(UniqueId);
                            if (DT.Rows.Count > 0)
                            {
                                if (!System.IO.File.Exists(FldPathDoc + FinalFileName))
                                {
                                    int personalrowid = Convert.ToInt32(DT.Rows[0]["PersonalRowID"]);
                                    int CheckFamilyRowID = Convert.ToInt32(DT.Rows[0]["SubCheckFamilyID"]);
                                    string path = Path.Combine(FldPathDoc, FinalFileName);
                                    file.SaveAs(path);
                                    SavePQVerifiedUploadDocUAN(personalrowid, CheckFamilyRowID, FinalFileName, FldPathDoc, "Provided", DocType, "");
                                }
                            }
                        }
                    }
                }
            }
            if (xlsFile != null)
            {
                try
                {
                    var Time_stamp = new DateTimeOffset(Convert.ToDateTime(DateTime.Now)).ToUnixTimeSeconds();

                    string filename = Path.GetFileName(xlsFile.FileName);
                    string filePath = FldPathExlx + Time_stamp + "_" + xlsFile.FileName;
                    string extension = Path.GetExtension(xlsFile.FileName);
                    filePath = Server.MapPath(FldPathExlx + filename);
                    xlsFile.SaveAs(filePath);
                    string conStr = "";
                    switch (extension)
                    {
                        case ".xls": //Excel 97-03
                            conStr = ConfigurationManager.ConnectionStrings["Excel03ConString"].ConnectionString;
                            break;
                        case ".xlsx": //Excel 07
                            conStr = ConfigurationManager.ConnectionStrings["Excel07ConString"].ConnectionString;
                            break;
                    }
                    conStr = String.Format(conStr, filePath, "yes");
                    OleDbConnection connExcel = new OleDbConnection(conStr);
                    OleDbCommand cmdExcel = new OleDbCommand();
                    OleDbDataAdapter oda = new OleDbDataAdapter();
                    DataTable dt = new DataTable();

                    cmdExcel.Connection = connExcel;

                    //Get the name of First Sheet
                    connExcel.Open();
                    DataTable dtExcelSchema;
                    dtExcelSchema = connExcel.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, null);
                    string SheetName = dtExcelSchema.Rows[0]["TABLE_NAME"].ToString();
                    connExcel.Close();

                    //Read Data from First Sheet
                    connExcel.Open();
                    cmdExcel.CommandText = "SELECT * From [" + SheetName + "]";
                    oda.SelectCommand = cmdExcel;
                    oda.Fill(dt);
                    connExcel.Close();

                    if (dt.Rows.Count > 0)
                    {
                        for (int J = 0; J < dt.Rows.Count; J++)
                        {
                            PersonalDocDetails personalDoc = new PersonalDocDetails();

                            string CompanyRefNo = Convert.ToString(dt.Rows[J]["CompanyRefNo"]);
                            string CheckUniqueId = Convert.ToString(dt.Rows[J]["CheckUniqueId"]);
                            string Document1 = Convert.ToString(dt.Rows[J]["ImageName"]);
                            string Document2 = Convert.ToString(dt.Rows[J]["Documents1"]);
                            var DT = cc.GetPQCandidateChecksfromCheckUniqueID(CheckUniqueId);
                            if (DT.Rows.Count > 0)
                            {
                                int clientRowid = Convert.ToInt32(DT.Rows[0]["ClientRowId"]);
                                int PersonalRowId = Convert.ToInt32(DT.Rows[0]["PersonalRowID"]);
                                int SubCheckRowId = Convert.ToInt32(DT.Rows[0]["SubCheckFamilyID"]);
                                var DocDt1 = cc.GetPQVerifiedUploadDocsForFaceMatch(PersonalRowId, SubCheckRowId, Document1);
                                string imageName1 = "";
                                string imageName2 = "";
                                if (DocDt1.Rows.Count > 0)
                                {
                                    imageName1 = Convert.ToString(DocDt1.Rows[0]["FileName"]);
                                }
                                var DocDt2 = cc.GetPQVerifiedUploadDocsForFaceMatch(PersonalRowId, SubCheckRowId, Document2);
                                if (DocDt2.Rows.Count > 0)
                                {
                                    imageName2 = Convert.ToString(DocDt2.Rows[0]["FileName"]);
                                }
                                if (imageName1 != "" && imageName2 != "")
                                {
                                    InstantCheckRepository InstantcheckObj = new InstantCheckRepository();
                                    string Image1path = FldPathDoc + imageName1.Replace("-", "_").Trim();
                                    string Image2path = FldPathDoc + imageName2.Replace("-", "_").Trim();
                                    var FatchMatchModel = InstantcheckObj.GetFatchMatch(Image1path, Image2path, "60", "", CheckUniqueId);
                                    string FaceMatchId = "";
                                    if (FatchMatchModel.statuscode == 200)
                                    {
                                        string FaceMatchPass = "Fail";
                                        if (FatchMatchModel.data.status.ToUpper() == "SUCCESS")
                                        {
                                            FaceMatchPass = "Pass";
                                        }
                                        string matchdata = FatchMatchModel.data.match.Replace("%", "").Trim();
                                        FaceMatchId = cc.InsertIntoFaceMatch(FatchMatchModel, PersonalRowId, Image2path, Image1path, "Id Image", "Provided By Candidate Image", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));

                                        var formdt = cc.Antecedents_client_select_form(clientRowid, SubCheckRowId, "Operation", "Check");
                                        if (formdt.Rows.Count > 0)
                                        {
                                            for (int i = 0; i < formdt.Rows.Count; i++)
                                            {
                                                int Antecedents = Convert.ToInt32(formdt.Rows[i]["AntecedentsRowID"]);
                                                int rst = cc.InsertUpdateFaceMatchCheckDetails(PersonalRowId, SubCheckRowId, Antecedents, clientRowid, FaceMatchPass);
                                            }
                                        }
                                        var FaceMatchDt = cc.GetFaceMatch(Convert.ToInt32(FaceMatchId));
