        [HttpPost]
        public ActionResult BulkFileUploadsfromExcelSheet(IEnumerable<HttpPostedFileBase> docFile, HttpPostedFileBase xlsFile)
        {
            List<IsfileUploadsViewModel> objlst = new List<IsfileUploadsViewModel>();
            try
            {
                string[] allowedExtensions = { ".pdf", ".PDF", ".jpg", ".jpeg", ".png", ".JPG", ".JPEG", ".PNG" };
                List<IsfileUploadsViewModel> lstOnj = new List<IsfileUploadsViewModel>();
                string PathDoc = System.Configuration.ConfigurationManager.AppSettings["provideddocuments"].ToString();
                string FldPathExlx = System.Configuration.ConfigurationManager.AppSettings["ClientUploadedDocuments"].ToString();
                string FldPathDoc = Server.MapPath(PathDoc);
                if (docFile != null)
                {
                    DataTable xlsdt = new DataTable();
                    if (xlsFile != null)
                    {
                        var Time_stamp = new DateTimeOffset(Convert.ToDateTime(DateTime.Now)).ToUnixTimeSeconds();
                        string filename = Path.GetFileName(xlsFile.FileName);
                        string filePath = FldPathExlx + Time_stamp + "_" + xlsFile.FileName;
                        string extension = Path.GetExtension(xlsFile.FileName);
                        filePath = Server.MapPath(FldPathExlx + filename);
                        xlsFile.SaveAs(filePath);
                        string conStr = "";
                        switch (extension)
                        {
                            case ".xls": //Excel 97-03
                                conStr = ConfigurationManager.ConnectionStrings["Excel03ConString"].ConnectionString;
                                break;
                            case ".xlsx": //Excel 07
                                conStr = ConfigurationManager.ConnectionStrings["Excel07ConString"].ConnectionString;
                                break;
                        }
                        conStr = String.Format(conStr, filePath, "yes");
                        OleDbConnection connExcel = new OleDbConnection(conStr);
                        OleDbCommand cmdExcel = new OleDbCommand();
                        OleDbDataAdapter oda = new OleDbDataAdapter();
                        cmdExcel.Connection = connExcel;
                        //Get the name of First Sheet
                        connExcel.Open();
                        DataTable dtExcelSchema;
                        dtExcelSchema = connExcel.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, null);
                        string SheetName = dtExcelSchema.Rows[0]["TABLE_NAME"].ToString();
                        connExcel.Close();
                        //Read Data from First Sheet
                        connExcel.Open();
                        cmdExcel.CommandText = "SELECT * From [" + SheetName + "]";
                        oda.SelectCommand = cmdExcel;
                        oda.Fill(xlsdt);
                        connExcel.Close();
                    }
                    foreach (var file in docFile)
                    {
                        if (file != null && file.ContentLength > 0)
                        {
                            string DocumentType = "";
                            string Remarks = "";
                            var UniqueId = Path.GetFileName(file.FileName).Split('.')[0].ToString();
                            string extension = Path.GetExtension(file.FileName);
                            if (allowedExtensions.Contains(extension))
                            {
                                IsfileUploadsViewModel model1 = new IsfileUploadsViewModel();
                                var DT = cc.GetPQCandidateChecksfromCheckUniqueID(UniqueId);
                                if (DT.Rows.Count > 0)
                                {
                                    string searchitem = "CheckUniqueID ='" + UniqueId.Trim() + "'";
                                    DataRow[] filteredRows = xlsdt.Select(searchitem);
                                    DataTable filteredTable = filteredRows.CopyToDataTable();
                                    if (filteredTable.Rows.Count > 0)
                                    {
                                        DocumentType = Convert.ToString(filteredTable.Rows[0]["DocumentType"]);
                                        Remarks = Convert.ToString(filteredTable.Rows[0]["Remark"]);
                                    }
                                    var TimeStamp = new DateTimeOffset(Convert.ToDateTime(DateTime.Now)).ToUnixTimeSeconds();
                                    int personalrowid = Convert.ToInt32(DT.Rows[0]["PersonalRowID"]);
                                    int CheckFamilyRowID = Convert.ToInt32(DT.Rows[0]["SubCheckFamilyID"]);
                                    string FinalFileName = CheckFamilyRowID + "_" + UniqueId + "_" + DocumentType + "" + TimeStamp.ToString() + "" + extension;
                                    string path = Path.Combine(FldPathDoc, FinalFileName);
                                    file.SaveAs(path);
                                    SavePQVerifiedUploadDocUAN(personalrowid, CheckFamilyRowID, FinalFileName, PathDoc, "Verified", DocumentType, Remarks);
                                    model1.CheckUniqueId = UniqueId;
                                    model1.FileName = FinalFileName;
                                    model1.Status = "Upload";
                                    objlst.Add(model1);
                                }
                                else
                                {
                                    model1.CheckUniqueId = UniqueId;
                                    model1.FileName = "";
                                    model1.Status = "not Upload";
                                    objlst.Add(model1);
                                }
                            }
                        }
                    }
                }
                else
                {
                    ViewBag.ErrorMsg = "Please Doc Files Uploads first";
                }
            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View(objlst);
        }

