        public int getDigiTapUAN(int PId, int Sid, string UANNo, int ClientRowId, string CompanyRefNo)
        {
            int rst = 0;
            ClientCustomize CC = new ClientCustomize();
            try
            {
                if (UANNo != "")
                {
                    AddUANCheckDetailsByAPI AddApiObj = new AddUANCheckDetailsByAPI();
                    var Path = Server.MapPath("~\\APILogs\\Logfiles");
                    var Model = AddApiObj.getDigiTapUAN(PId, CompanyRefNo, UANNo, Path);
                    if (Model != null)
                    {
                        string body = string.Empty;
                        using (StreamReader reader = new StreamReader(Server.MapPath("~/Emailers/DigiTapUANCheck.html")))
                        {
                            body = reader.ReadToEnd();
                        }
                        string data = "";
                        string name = Model.name;
                        string guardian_name = Model.relative_name;

                        DataTable dt = new DataTable();
                        dt = CC.Antecedents_client_select_form(ClientRowId, Sid, "Operation", "Check");
                        if (dt.Rows.Count > 0)
                        {
                            for (int i = 0; i < dt.Rows.Count; i++)
                            {
                                int Antecedents = Convert.ToInt32(dt.Rows[0]["AntecedentsRowID"]);
                                int AutoId = CC.InsertUpdateUANCheckDetails(PId, Sid, Antecedents, ClientRowId, UANNo, name, guardian_name);
                            }
                        }

                        foreach (var item in Model.EmploymentHistory)
                        {
                            string date_of_joining = "";
                            string date_of_exit = "";
                            if (Convert.ToString(item.date_of_joining) != "")
                            {
                                DateTime doj = Convert.ToDateTime(item.date_of_joining);
                                date_of_joining = doj.ToString("dd-MMM-yyyy");
                            }
                            if (Convert.ToString(item.date_of_exit) != "")
                            {
                                DateTime doe = Convert.ToDateTime(item.date_of_exit);
                                date_of_exit = doe.ToString("dd-MMM-yyyy");
                            }
                            data += "<tr>";
                            data += "<td> " + Convert.ToString(item.establishment_name) + " (" + Convert.ToString(item.establishment_id) + ")" + " </td>";
                            data += "<td> " + date_of_joining + " </td>";
                            data += "<td> " + date_of_exit + " </td>";
                            data += "</tr>";
                        }
                        body = body.Replace("{companyRefNo}", CompanyRefNo);
                        body = body.Replace("{name}", Model.name);
                        body = body.Replace("{guardian_name}", Model.relative_name);
                        body = body.Replace("{uanNumberId}", UANNo);
                        body = body.Replace("{Gender}", Model.gender);
                        body = body.Replace("{MobileNo}", Model.mobile);
                        body = body.Replace("{date_of_birth}", Model.date_of_birth);
                        body = body.Replace("{EstablishedDetails}", data);
                        body = body.Replace("{verifiedDate}", DateTime.Now.Date.ToString("dd-MMM-yyyy"));
                        if (Sid > 0)
                        {
                            SavePQVerifiedUploadUANDoc(PId, Convert.ToInt16(Sid), "Verified", "UAN Report", "provideddocuments", body, "UAN No Verified", 0, CompanyRefNo);
                        }
                        var FileName = SavePQVerifiedUploadCaseDocUAN(Convert.ToInt32(PId), "Verified", "UAN Case Report", "provideddocuments", body, "UAN No Verified", false, CompanyRefNo);
                        rst = 1;

                    }
                }
            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return rst;
            }
            return rst;
        }
        private string GetIP_Address()
        {
            string myIPAddr = "";
            foreach (NetworkInterface ni in NetworkInterface.GetAllNetworkInterfaces())
            {
                if (ni.OperationalStatus == OperationalStatus.Up)
                {
                    foreach (UnicastIPAddressInformation ip in ni.GetIPProperties().UnicastAddresses)
                    {
                        if (ip.Address.AddressFamily == AddressFamily.InterNetwork)
                        {
                            myIPAddr += $" Interface: {ni.Name}, IP Address: {ip.Address} ";
                        }
                    }
                }
            }
            return myIPAddr.ToString();
        }

