        [HttpGet]
        public async Task<ActionResult> DownloadZipAll(int PersonalRowID)
        {
            ClientCustomize cc = new ClientCustomize();

            DataTable dt = cc.GetPQVerifiedUploadCaseDoc(PersonalRowID, 0);

            if (dt == null || dt.Rows.Count == 0)
            {
                return Json(new
                {
                    success = false,
                    message = "No documents found to download."
                }, JsonRequestBehavior.AllowGet);
            }

            using (var memoryStream = new MemoryStream())
            {
                using (var zipArchive = new ZipArchive(memoryStream, ZipArchiveMode.Create, true))
                using (var httpClient = new HttpClient())
                {
                    foreach (DataRow row in dt.Rows)
                    {
                        try
                        {
                            string fileName = row["FileName"].ToString();

                            string FldPathDoc = ConfigurationManager.AppSettings["provideddocuments"].ToString();
                            string filePath = Server.MapPath(FldPathDoc + fileName);

                            // Check local file first
                            if (System.IO.File.Exists(filePath))
                            {
                                var entry = zipArchive.CreateEntry(fileName, CompressionLevel.Fastest);

                                using (var entryStream = entry.Open())
                                using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
                                {
                                    await fileStream.CopyToAsync(entryStream);
                                }
                            }
                            else
                            {
                                string apiUrl =
                                    "https://api.weverifyglobal.com/CaseDocsFromAPI?fileName=" +
                                    Uri.EscapeDataString(fileName);

                                HttpResponseMessage response = await httpClient.GetAsync(apiUrl);

                                if (response.IsSuccessStatusCode)
                                {
                                    var entry = zipArchive.CreateEntry(fileName, CompressionLevel.Fastest);

                                    using (var entryStream = entry.Open())
                                    using (var apiStream = await response.Content.ReadAsStreamAsync())
                                    {
                                        await apiStream.CopyToAsync(entryStream);
                                    }
                                }
                            }
                        }
                        catch (Exception ex)
                        {

                        }
                    }
                }

                memoryStream.Position = 0;

                return File(
                    memoryStream.ToArray(),
                    "application/zip",
                    "Document.zip");
            }
        }

        [HttpGet]
        public async Task<ActionResult> DownloadZipCheck(int PersonalRowID, int SubCheckRowID = 0)
        {
            ClientCustomize cc = new ClientCustomize();

            DataTable dt = cc.Sp_GetPQVerifiedUploadDocs(PersonalRowID, Convert.ToInt16(SubCheckRowID));

            if (dt == null || dt.Rows.Count == 0)
            {
                return Json(new
                {
                    success = false,
                    message = "No documents found to download."
                }, JsonRequestBehavior.AllowGet);
            }

            using (var memoryStream = new MemoryStream())
            {
                using (var zipArchive = new ZipArchive(memoryStream, ZipArchiveMode.Create, true))
                using (var httpClient = new HttpClient())
                {
                    foreach (DataRow row in dt.Rows)
                    {
                        try
                        {
                            string fileName = row["FileName"].ToString();

                            string FldPathDoc = ConfigurationManager.AppSettings["provideddocuments"].ToString();
                            string filePath = Server.MapPath(FldPathDoc + fileName);

                            // Check if file exists on server
                            if (System.IO.File.Exists(filePath))
                            {
                                var entry = zipArchive.CreateEntry(fileName, CompressionLevel.Fastest);

                                using (var entryStream = entry.Open())
                                using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
                                {
                                    await fileStream.CopyToAsync(entryStream);
                                }
                            }
                            else
                            {
                                // Download from API if file not found locally
                                string apiUrl = "https://api.weverifyglobal.com/CaseDocsFromAPI?fileName="
                                                + Uri.EscapeDataString(fileName);

                                HttpResponseMessage response = await httpClient.GetAsync(apiUrl);

                                if (response.IsSuccessStatusCode)
                                {
                                    var entry = zipArchive.CreateEntry(fileName, CompressionLevel.Fastest);

                                    using (var entryStream = entry.Open())
                                    using (var apiStream = await response.Content.ReadAsStreamAsync())
                                    {
                                        await apiStream.CopyToAsync(entryStream);
                                    }
                                }
                            }
                        }
                        catch (Exception ex)
                        {
                            // Log exception if required
                            // Continue processing remaining files
                        }
                    }
                }

                memoryStream.Position = 0;

                return File(
                    memoryStream.ToArray(),
                    "application/zip",
                    "Document.zip");
            }
        }


        [HttpGet]
        public PartialViewResult GetCVValidationPartial(int PersonalRowID, int ClientRowId, int SubCheckRowID)
        {
            List<VerificationDetailModel1> model =
                new List<VerificationDetailModel1>();

            DataTable dt = new DataTable();

            dt = cc.GetCVValidationCheck(PersonalRowID);

            if (dt.Rows.Count > 0)
            {
                ViewBag.record = dt.Rows.Count;

                foreach (DataRow dr in dt.Rows)
                {
                    model.Add(
                        new VerificationDetailModel1
                        {
                            PersonalRowID = PersonalRowID,
                            DataField = Convert.ToString(dr["DataField"]),
                            ApplicantSubmittedDetails = Convert.ToString(dr["ApplicantSubmittedDetails"]),
                            ResumeCVDetails = Convert.ToString(dr["ResumeCVDetails"])
                        });
                }
            }
            else
            {
                string[] dataFields =
                {
                    "Qualification",
                    "Current Organisation Name",
                    "Tenure",
                    "Current Organisation (Previous-1)",
                    "Tenure1",
                    "Current Organisation (Previous-2)",
                    "Tenure2",
                    "Address",
                    "Check Closed Date",
                    "Mode of verification"
                };

                foreach (string field in dataFields)
                {
                    model.Add(new VerificationDetailModel1
                    {
                        PersonalRowID = PersonalRowID,
                        DataField = field,
                        ApplicantSubmittedDetails = "",
                        ResumeCVDetails = ""
                    });
                }
            }

            return PartialView("_CVValidation", model);
        }


