        [HttpPost]
        public ActionResult UpdateCVValidationCheck(List<VerificationDetailModel1> updatedChecks)
        {
            try
            {
                ClientCustomize cc = new ClientCustomize();

                foreach (var check in updatedChecks)
                {
                    if (check.DataField != null && check.DataField != "")
                    {
                        cc.InsertCVValidationCheck(check.PersonalRowID, 38, 1470, check.DataField, check.ApplicantSubmittedDetails, check.ResumeCVDetails);
                    }
                }

            }
            catch (Exception ex)
            {
                return Json(500, "Bulk update failed.");
            }
            return Json(new { success = true });

        }
        public JsonResult CheckReportStatus(int Pid, int Sid)
        {
            string requestId = "";
            int AutoId = 0;

            AddUANCheckDetailsByAPI API = new AddUANCheckDetailsByAPI();
            DataBaseConnections CE = new DataBaseConnections();

            var DT = CE.getCoinCircleTrustCRC(0, Pid, Sid, "", "", "");

            if (DT.Rows.Count > 0)
            {
                requestId = Convert.ToString(DT.Rows[0]["RequestId"]);
                AutoId = Convert.ToInt32(DT.Rows[0]["AutoId"]);
            }
            else
            {
                return Json(new
                {
                    Success = false,
                    Message = "Record not found"
                }, JsonRequestBehavior.AllowGet);
            }

            var jsonResult = API.GetCourtCaseStatus(requestId);

            if (string.IsNullOrEmpty(jsonResult))
            {
                return Json(new
                {
                    Success = false,
                    Message = "No response received"
                }, JsonRequestBehavior.AllowGet);
            }

            var firstResult = JsonConvert.DeserializeObject<CRC_Root>(jsonResult);

            if (firstResult.data.result == "pending")
            {
                return Json(new
                {
                    Success = false,
                    Message = "Report Status : Pending"
                }, JsonRequestBehavior.AllowGet);
            }

            if (firstResult.data.status == "processing")
            {
                return Json(new
                {
                    Success = false,
                    Message = "Report Status : Processing"
                }, JsonRequestBehavior.AllowGet);
            }

            var modelResult = JsonConvert.DeserializeObject<CRCResultRoot>(jsonResult);

            if (modelResult.success &&
                modelResult.data.status == "completed")
            {
                CE.UpdateCoinCircleTrustCRC(AutoId, jsonResult);

                return Json(new
                {
                    Success = true,
                    Message = "Report Generated Successfully",
                    RequestId = requestId
                }, JsonRequestBehavior.AllowGet);
            }

            return Json(new
            {
                Success = false,
                Message = "Report Not Completed"
            }, JsonRequestBehavior.AllowGet);
        }

        public ActionResult DownloadReportFile(string requestId)
        {
            AddUANCheckDetailsByAPI API = new AddUANCheckDetailsByAPI();

            byte[] fileBytes = API.GetReportBytes(requestId);

            if (fileBytes == null || fileBytes.Length == 0)
            {
                return Content("Report not found");
            }
            return File(fileBytes,"application/pdf",requestId + ".pdf"
            );
        }

        public ActionResult BulkDownloadCRCReport()
        {
            try
            {
                DataBaseConnections DC = new DataBaseConnections();
                ClientCustomize CC = new ClientCustomize();
                var dt = DC.GetCRCRequestData();
                if (dt.Rows.Count > 0)
                {
                    string PRowId = string.Empty;
                    var ErrorPath = Server.MapPath("~\\ErrorLogs\\Logfiles");
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        CRCInputRequest model = new CRCInputRequest();
                        try
                        {
                            string requestId = Convert.ToString(dt.Rows[i]["requestId"]).Trim();
                            int Pid = Convert.ToInt32(dt.Rows[i]["PersonalRowId"]);
                            int Sid = Convert.ToInt32(dt.Rows[i]["SubCheckRowId"]);
                            int AutoId = Convert.ToInt32(dt.Rows[i]["AutoId"]);
                            AddUANCheckDetailsByAPI API = new AddUANCheckDetailsByAPI();
                            var jsonResult = API.GetCourtCaseStatus(requestId);

                            if (!string.IsNullOrEmpty(jsonResult))
                            {
                                var firstResult = JsonConvert.DeserializeObject<CRC_Root>(jsonResult);
                                if (firstResult.data.result == "pending")
                                {
                                    CC.UpdateCandidateChecksReportComments(Pid, Sid, "pending");
                                }
                                else
                                {
                                    if (firstResult.data.status == "processing")
                                    {
                                        CC.UpdateCandidateChecksReportComments(Pid, Sid, "processing");
                                    }
                                    else
                                    {
                                        var modelResult = JsonConvert.DeserializeObject<CRCResultRoot>(jsonResult);
                                        if (modelResult.success && modelResult.data.status == "completed")
                                        {
                                            DC.UpdateCoinCircleTrustCRC(AutoId, jsonResult);
                                            CC.UpdateCandidateChecksReportComments(Pid, Sid, firstResult.data.result.ToString());
                                        }
                                        else
                                        {
                                            CC.UpdateCandidateChecksReportComments(Pid, Sid, "Report Not Completed");
                                        }
                                    }
                                }
                            }
                        }
                        catch (Exception Ex)
                        {
                            clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                            return Json(new
                            {
                                Success = false,
                                Message = "Process not completed Due to some error."
                            }, JsonRequestBehavior.AllowGet);

                        }
                    }
                }
            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return Json(new
                {
                    Success = false,
                    Message = "Process not completed Due to some error."
                }, JsonRequestBehavior.AllowGet);
            }
            return Json(new
            {
                Success = true,
                Message = "Process completed successfully. Please download MIS and check status."
            }, JsonRequestBehavior.AllowGet);
        }

    }

